// W49 d01：三种「人」为什么拆三张表 —— user_account / member / family_member
// 这一天在解决什么问题：家里混着三种「人」——能登录的（账号持有人）、不能登录
// 但要被记账的（孩子、老人）、以及「谁以什么角色属于哪个家」的关系事实。挤进一
// 张表，两种能力就绑死：注销账号时账跟着没（第 4 节现场算出丢了几行几分）；拆
// 三张表，无账号成员在登录门吃 401、却一行不少地进报表与导出（第 2、3 节）。
// family_id 恒进每一条查询且只从会话取，跨家庭读写一律 404 不是 403（第 5 节）。
// 学员侧跑法：cd homecube/server && go run ./lab/s12/d01
package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gormlogger "gorm.io/gorm/logger"
)

var fixedNow = time.Date(2026, 10, 5, 9, 0, 0, 0, time.FixedZone("Asia/Shanghai", 8*3600))
var sign = map[string]int64{"income": 1, "expense": -1}
var mark = map[bool]string{true: "✅", false: "❌"}
var yes = map[bool]int{true: 1, false: 0}
var mIDsAll = []string{"M-dad", "M-gma", "M-gpa", "M-kid", "M-mom", "M-momB"} // 预排好的稳定键清单：两次跑字节一致
var mIDsA = []string{"M-dad", "M-gma", "M-kid", "M-mom"}                      // fam-A 成员（有序）

// —— 三张表各管一件事：登录挂 user_account，记账挂 member，归属挂 family_member ——
type UserAccount struct{ ID, Email, CancelledAt string } // CancelledAt ""=未注销；登录能力只长在这张表上

type Member struct{ ID, FamilyID, DisplayName, AccountID string } // AccountID ""=无账号被记录者：登不了录，照样被记账
func (Member) TableName() string                                  { return "member" }

type FamilyMember struct{ FamilyID, UserAccountID, Role string } // 同一账号可在两个家各一行，角色各是各的

type Txn struct {
	ID, FamilyID, MemberID, Kind string
	Cents                        int64 // 红线：金额一律 *_cents 整数，链路里不出现浮点
}

const famA, famB = "fam-A", "fam-B"

var accounts = map[string]UserAccount{"dad@home.test": {ID: "U-dad", Email: "dad@home.test"}, "mom@home.test": {ID: "U-mom", Email: "mom@home.test"}}
var members = map[string]Member{
	"M-dad":  {ID: "M-dad", FamilyID: famA, DisplayName: "爸爸", AccountID: "U-dad"},
	"M-mom":  {ID: "M-mom", FamilyID: famA, DisplayName: "妈妈", AccountID: "U-mom"},
	"M-kid":  {ID: "M-kid", FamilyID: famA, DisplayName: "小明", AccountID: ""},
	"M-gma":  {ID: "M-gma", FamilyID: famA, DisplayName: "奶奶", AccountID: ""},
	"M-gpa":  {ID: "M-gpa", FamilyID: famB, DisplayName: "爷爷", AccountID: ""},
	"M-momB": {ID: "M-momB", FamilyID: famB, DisplayName: "妈妈", AccountID: "U-mom"}}
var rels = []FamilyMember{{famA, "U-dad", "owner"}, {famA, "U-mom", "editor"}, {famB, "U-mom", "viewer"}}
var people = map[string]string{"P-dad": "爸爸", "P-mom": "妈妈", "P-kid": "小明"} // ❌ 反例表：人=账号行，被记录者也挤进来
var peopleTxns = []Txn{{"A-01", famA, "P-dad", "income", 860000}, {"A-02", famA, "P-dad", "expense", 236500}, {"A-03", famA, "P-dad", "expense", 128000}, {"A-04", famA, "P-mom", "expense", 99000}, {"A-05", famA, "P-kid", "expense", 25800}}
var ledger = []Txn{
	{"T-01", famA, "M-dad", "income", 860000}, {"T-02", famA, "M-dad", "expense", 236500},
	{"T-03", famA, "M-dad", "expense", 128000}, {"T-04", famA, "M-mom", "expense", 99000},
	{"T-05", famA, "M-kid", "expense", 25800}, {"T-06", famA, "M-kid", "expense", 128000},
	{"T-07", famA, "M-gma", "expense", 46000}, {"T-08", famA, "M-gma", "expense", 12500},
	{"T-09", famA, "M-mom", "expense", 33000}, {"T-10", famB, "M-gpa", "expense", 33000},
	{"T-11", famB, "M-momB", "expense", 21000}, {"T-12", famB, "M-gpa", "expense", 15000},
	{"T-13", famB, "M-gpa", "income", 5000}}

func hdr(n int, s string) { fmt.Printf("\n===== %d. %s =====\n", n, s) }
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", strings.Repeat("-", yes[c < 0]), max(c, -c)/100, max(c, -c)%100)
}
func inP(id string) bool { return people[id] != "" }

func dryDB() *gorm.DB {
	db, _ := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_member:dev@127.0.0.1:5432/homecube?sslmode=disable"}),
		&gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	return db
}

// login：唯一入口是 user_account；member 行不给凭据 —— 无账号成员登不进来。
func login(email string) (int, string) {
	a, ok := accounts[email]
	gone := !ok || a.CancelledAt != ""
	return map[bool]int{true: 401, false: 200}[gone], map[bool]string{true: map[bool]string{true: "账号已注销（cancelled_at 非空）：登录门关闭，member 行与流水照旧", false: "user_account 里没有这个邮箱：member 是被记录者，不是登录凭据"}[ok], false: "session{user_id=" + a.ID + "}，family_id 与角色只从 family_member 关系取"}[gone]
}

// record：写账的唯一门 —— family_id 取自会话，成员必须活在该家庭里。
func record(sessionFam, memberID, kind string, cents int64) (int, string) {
	m, ok := members[memberID]
	bad := memberID == "" || kind == "" || cents <= 0 || sign[kind] == 0
	hidden := !bad && (!ok || m.FamilyID != sessionFam)
	ledger = append(ledger, Txn{fmt.Sprintf("T-%02d", len(ledger)+1), sessionFam, memberID, kind, cents})
	ledger = ledger[:len(ledger)-yes[bad || hidden]]
	msg := map[bool]string{true: "非法参数：member_id/kind/amount_cents 必填，kind∈{income,expense}，amount_cents 为正整数分；绝不回落默认值", false: map[bool]string{true: fmt.Sprintf("会话家庭 %s 里看不见 member_id=%s（%s）—— 一律 404，不给 403 去确认「它存在」；未落任何一行", sessionFam, memberID, map[bool]string{true: "它根本不存在", false: "它属于 " + m.FamilyID}[!ok]), false: fmt.Sprintf("记账成功：%s %s %d 分", m.DisplayName, kind, cents)}[hidden]}[bad]
	return map[bool]int{true: 400, false: map[bool]int{true: 404, false: 201}[hidden]}[bad], msg
}

// report：报表按 member 聚合（member→{笔数,净额分}）——账号在不在根本不参与。
func report(fam string) map[string][2]int64 {
	out := map[string][2]int64{}
	for _, t := range ledger {
		out[t.MemberID] = [2]int64{out[t.MemberID][0] + int64(yes[t.FamilyID == fam]), out[t.MemberID][1] + int64(yes[t.FamilyID == fam])*sign[t.Kind]*t.Cents}
	}
	return out
}

func main() {
	hdr(1, "场景与三张表的契约：谁登录、谁被记账、谁属于哪个家")
	fmt.Printf("  user_account 管登录凭据；member 管「被记录者」（孩子/老人可以没有账号）；family_member 管「谁属于哪个家、什么角色」。\n  账挂在 member 上，登录挂在 user_account 上，两者之间只隔一个可空的 account_id —— 能力互不越界。\n")
	db := dryDB()
	fmt.Printf("  —— user_account（%d 行）——\n", len(accounts))
	for _, e := range []string{"dad@home.test", "mom@home.test"} {
		fmt.Printf("     %s email=%-16s cancelled_at=%q\n", accounts[e].ID, e, accounts[e].CancelledAt)
	}
	fmt.Printf("  —— member（%d 行；无账号被记录者就在这张表里）——\n", len(members))
	for _, id := range mIDsAll {
		fmt.Printf("     %s family=%s display=%-3s account=%s\n", id, members[id].FamilyID, members[id].DisplayName, map[bool]string{true: "（空：登不了录，只能被记账）", false: members[id].AccountID}[members[id].AccountID == ""])
	}
	fmt.Printf("  —— family_member（%d 行关系）——\n", len(rels))
	for _, r := range rels {
		fmt.Printf("     %s × %s role=%s（妈妈一个账号，两个家两种角色）\n", r.FamilyID, r.UserAccountID, r.Role)
	}
	nb := Member{ID: "M-new", FamilyID: famA, DisplayName: "新生儿", AccountID: ""}
	fmt.Printf("  DryRun INSERT（Postgres 方言原文，本机不落库）：\n    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB { return tx.Create(&nb) }))
	hdr(2, "无账号成员不能登录，却能被记一笔账")
	kidCode, kidMsg := login("xiaoming@home.test")
	dadCode, dadMsg := login("dad@home.test")
	momCode, momMsg := login("mom@home.test")
	fmt.Printf("  POST /auth/login email=xiaoming@home.test → %d %s\n", kidCode, kidMsg)
	fmt.Printf("  POST /auth/login email=dad@home.test      → %d %s\n", dadCode, dadMsg)
	fmt.Printf("  POST /auth/login email=mom@home.test      → %d %s\n", momCode, momMsg)
	before := len(ledger)
	recCode, recMsg := record(famA, "M-kid", "expense", 9900)
	fmt.Printf("  POST /txns（会话=fam-A，给小明记文具 99.00 元＝9900 分）→ %d %s\n", recCode, recMsg)
	fmt.Printf("  流水行数 %d → %d：登录门挡住的只是「进门」，记账门看的是 member 行 —— 两扇门本来就该分开\n", before, len(ledger))
	hdr(3, "fam-A 报表与导出：无账号成员照样逐行出现（family_id 恒进查询）")
	rep := report(famA)
	bN, bC, repN := int64(0), int64(0), int64(0)
	fmt.Printf("  %-8s %-4s %-8s %-10s %s\n", "member", "笔数", "净额分", "净额元", "备注")
	for _, k := range mIDsA {
		fmt.Printf("  %-8s %-4d %-8d %-10s %s\n", k, rep[k][0], rep[k][1], money(rep[k][1]), map[bool]string{true: "← 无账号，登不了录，账里全在", false: ""}[members[k].AccountID == ""])
		fmt.Printf("    CSV> %s,%s,%d,%d\n", k, members[k].DisplayName, rep[k][0], rep[k][1])
		bN += rep[k][0]
		bC += rep[k][1]
		repN += int64(yes[rep[k][0] > 0])
	}
	fmt.Printf("  CSV 表头（白名单）：member_id,member_display_name,txn_count,net_cents —— nickname 不上导出；共 %d 个成员行、%d 笔、净额合计 %d 分\n", repN, bN, bC)
	fmt.Printf("  流水全表逐行对账（in=%s 的进本报告行）：\n", famA)
	inRep, inB, sumA := 0, 0, int64(0)
	for _, t := range ledger {
		fmt.Printf("    %s %s %-6s %-8s %9d 分  in=%v\n", t.ID, t.FamilyID, t.MemberID, t.Kind, t.Cents, t.FamilyID == famA)
		inRep += yes[t.FamilyID == famA]
		inB += yes[t.FamilyID == famB]
		sumA += sign[t.Kind] * t.Cents * int64(yes[t.FamilyID == famA])
	}
	fmt.Printf("  in=%s 共 %d 笔、净额合计 %d 分；fam-B 的 %d 笔（爷爷×3、妈妈在另一个家的成员行）一笔都不该出现在上表\n", famA, inRep, sumA, inB)
	hdr(4, "❌ 把「能登录」与「能被记账」混成一列：注销账号后账去哪了")
	mixedAfter, mixedLost := int64(0), int64(0)
	fmt.Printf("  ❌ 注销前「人=账号」一张表：%v 共 %d 人，%d 笔流水全挂在这张表上（连无账号的小明也被当成账号行存着）\n", []string{"P-dad", "P-kid", "P-mom"}, len(people), len(peopleTxns))
	delete(people, "P-dad") // ❌ 注销=删行：人和账号是同一条，删不出半个
	for _, t := range peopleTxns {
		lost := !inP(t.MemberID)
		mixedAfter += int64(yes[!lost])
		mixedLost += sign[t.Kind] * t.Cents * int64(yes[lost])
		fmt.Printf("     %s member_id=%-6s %-8s %7d 分 → %s\n", t.ID, t.MemberID, t.Kind, t.Cents, map[bool]string{true: "❌ 查无此人：这行从报表里蒸发了", false: "报表仍认识它"}[lost])
	}
	fmt.Printf("  ❌ 注销 P-dad 后报表只剩 %d 人 —— 笔数 %d → %d，报表净额被撬动 %d 分（%s 元）\n", len(people), len(peopleTxns), mixedAfter, mixedLost, money(mixedLost))
	fmt.Println("  「注销」本意只是关登录门，却顺手把账从报表里抹了 —— 记账能力被绑死在登录能力上，这就是混列的代价")
	dadAcc := accounts["dad@home.test"] // ✅ 三张表：注销只写 user_account.cancelled_at
	dadAcc.CancelledAt = fixedNow.Format(time.RFC3339)
	accounts["dad@home.test"] = dadAcc
	rep2 := report(famA)
	codeAfter, msgAfter := login("dad@home.test")
	diffN, diffC := int64(0), int64(0)
	fmt.Printf("  ✅ 三张表：注销 U-dad 后登录门 %d（%s）\n", codeAfter, msgAfter)
	for _, k := range mIDsA {
		diffN += rep[k][0] - rep2[k][0]
		diffC += rep[k][1] - rep2[k][1]
		fmt.Printf("     %-7s 注销前 %d 笔/%d 分 → 注销后 %d 笔/%d 分\n", k, rep[k][0], rep[k][1], rep2[k][0], rep2[k][1])
	}
	fmt.Printf("  ✅ 报表对照：笔数 %d→%d、净额 %d→%d 分，差值 %d/%d —— member 不动，账就不动\n", bN, bN-diffN, bC, bC-diffC, diffN, diffC)
	hdr(5, "family_id 只从会话取：跨家庭读写一律 404，非法参数 400 不回落")
	crossCode, crossMsg := record(famA, "M-gpa", "expense", 50000)
	badCode, badMsg := record(famA, "", "expense", 50000)
	ghostCode, ghostMsg := record(famA, "M-none", "expense", 50000)
	fmt.Printf("  fam-A 会话给 fam-B 的爷爷记一笔 → %d %s\n", crossCode, crossMsg)
	fmt.Printf("  member_id 缺失 → %d %s（绝不静默落到「默认成员」）\n", badCode, badMsg)
	fmt.Printf("  member_id=M-none 不存在 → %d %s\n", ghostCode, ghostMsg)
	fmt.Printf("  响应码对照（同一请求，两版实现）：\n  %-36s %-6s %s\n", "请求", "本 lab", "泄露版（自认 403）")
	fmt.Printf("  %-36s %-6d %s\n  为什么是 404 不是 403：跨家庭资源的存在性本身就是隐私；404 让它对外根本不存在，无法用状态码爬出成员名册。\n", "GET /members/M-gpa（会话 fam-A）", 404, "403 —— 一句「无权」就向外确认了这行存在")
	ms := []Member{}
	findOut := db.ToSQL(func(tx *gorm.DB) *gorm.DB { return tx.Where("family_id = ? AND id = ?", famA, "M-kid").Find(&ms) })
	fmt.Printf("  每一条查询都带 family_id（DryRun 原文；值只从会话注入，请求里的 ?family_id=%s 一律被忽略）：\n    %s\n", famB, findOut)
	fmt.Println("  fam-A 会话视角的成员可见性：")
	for _, id := range mIDsAll {
		fmt.Printf("    %-7s family=%s 可见=%v\n", id, members[id].FamilyID, members[id].FamilyID == famA)
	}

	hdr(6, "判据收口（每条的证据都是现场算出来的）")
	rejN := len(ledger)
	pr := [][3]any{
		{kidCode == 401 && recCode == 201 && len(ledger) == before+1, "① 无账号成员登不了录、能被记账", fmt.Sprintf("login→%d；记账→%d，行数 %d→%d", kidCode, recCode, before, len(ledger))},
		{rep["M-kid"][0] >= 2 && rep["M-kid"][1] != 0, "② 无账号成员进报表和 CSV", fmt.Sprintf("M-kid 在 fam-A 报表 %d 笔、净额 %d 分（第 3 节 CSV> 行逐行可点）", rep["M-kid"][0], rep["M-kid"][1])},
		{diffN == 0 && diffC == 0 && mixedAfter < int64(len(peopleTxns)), "③ 注销账号绝不带走流水", fmt.Sprintf("挤一张表：%d 笔只剩 %d 笔、撬动 %d 分（丢的行见第 4 节逐行❌）；三张表：差值 %d 笔/%d 分", len(peopleTxns), mixedAfter, mixedLost, diffN, diffC)},
		{crossCode == 404 && ghostCode == 404 && badCode == 400 && len(ledger) == rejN, "④ 跨家庭读写 404、非法参数 400 不回落", fmt.Sprintf("跨家庭写→%d、不存在→%d、缺参→%d；三次拒绝后流水仍是 %d 行", crossCode, ghostCode, badCode, rejN)},
		{strings.Contains(findOut, "family_id"), "⑤ family_id 恒进每一条查询且只从会话取", "第 5 节 DryRun 原文 WHERE 含 family_id；请求参数 family_id 被忽略"},
		{sumA == bC && inRep == int(bN), "⑥ 金额全程整数分", fmt.Sprintf("报表 Σ%d 分 == 流水 in=%s 独立求和 %d 分；笔数两路对账 %d==%d，链路无浮点", bC, famA, sumA, inRep, bN)},
	}
	k := 0
	for _, p := range pr {
		k += yes[p[0].(bool)]
		fmt.Printf("  %s %s\n     证据：%v\n", mark[p[0].(bool)], p[1], p[2])
	}
	fmt.Printf("  %d 条判据通过 %d/6。\n", k, k)
	fmt.Println("  以上全是 DryRun + 内存表模拟。真环境要复跑三条：① psql 按三表契约建表，验证 member.account_id 可空且无级联外键；② 真实 POST /auth/login 用无账号 member 断言 401；③ 注销 U-dad 后重放第 4 节报表 SQL，断言行数与净额分毫不差。")
}

// W49 d04：角色与可见性 —— owner / editor / viewer / 监护人代写；跨家庭一律 404
// 这一天在解决什么问题：① family_id 只要有一个入口能传进来（query、body、前端缓存），隔离就
// 没了 —— 第 2 节把「只从会话取」与「信请求参数」两版并排跑，数出后者多读到别家几笔、几分；
// ② 越权碰别家资源时返 403 最顺手，但 403 等于宣告「这个 id 真实存在、只是不属于你」—— 第 4 节
// 拿 403 版与 404 版对同一批 id 并排打，泄露条数由程序当场数出来；③ 未登录 401、本家庭角色不足
// 403、跨家庭 404 三个码各有分工（第 5 节）；④ 角色刚改，已在途的请求读到哪一档？第 6 节拿「只按
// uid 的缓存」与「key 带 role_version 的缓存」对拍，把越权写次数与窗口秒数算出来。
// 本机无 PG / 无 HTTP 服务：行集在内存表上真跑，SQL 由 GORM DryRun 出原文（复跑清单见第 7 节）。
// 学员侧跑法：cd homecube/server && go run ./lab/s12/d04
package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gormlogger "gorm.io/gorm/logger"
)

const (
	rOwner, rEditor, rViewer = "owner", "editor", "viewer"
	famA, famB               = "fam-A", "fam-B"
)

// 四张表：会话 sess ／ family_member 角色（sess+famVer）／ member 被记录者(mems) ／ 流水(txns+amt+soft)
type acct struct{ uid, fam, role, live string } // live=="on" 才是有效 token；fam/role 只由会话解出，不接受任何外部入参
type mem struct{ id, fam, disp, dep string }    // dep=="dep"：这笔账只能由监护人代写（孩子/老人，本人没有账号）
type txn struct{ id, fam, mid, by string }      // 流水行；金额在 amt（整数分、支出为负），软删位在 soft
type qRow struct{ ID, FamilyID string }

func (qRow) TableName() string { return "finance_transaction" }

var (
	rank   = map[string]int{rViewer: 1, rEditor: 2, rOwner: 3} // 0 = 在本家庭没有角色
	mark   = map[bool]string{true: "✅", false: "❌"}
	yes    = map[bool]int{true: 1, false: 0}
