var txns = []txn{{"t-01", famA, "m-ann", "u-ann"}, {"t-02", famA, "m-bob", "u-bob"}, {"t-03", famA, "m-kid", "u-ann"}, {"t-04", famA, "m-kid", "u-bob"}, {"t-05", famA, "m-ann", "u-ann"}, {"t-06", famB, "m-dan", "u-dan"}, {"t-07", famB, "m-kid2", "u-dan"}, {"t-08", famB, "m-dan", "u-dan"}}
var amt = map[string]int64{"t-01": 860000, "t-02": -230000, "t-03": -45000, "t-04": -12800, "t-05": -50000, "t-06": 430000, "t-07": -66000, "t-08": -21000}
var soft = map[string]bool{"t-05": true} // deleted_at 非空：不进任何报表与导出
var gdb, _ = gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_member:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return now }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})

func mustLoad(n string) *time.Location { l, _ := time.LoadLocation(n); return l }
func day0(y, m, d int) time.Time       { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, loc) }
func hdr(s string)                     { fmt.Printf("\n===== %s =====\n", s) }
func orNone(s string) string           { return map[bool]string{true: s, false: "无关系"}[s != ""] }
func hitStr(b bool) string             { return map[bool]string{true: "命中", false: "miss"}[b] }
func atoi(s string) int                { n, _ := strconv.Atoi(s); return n }
func abs64(v int64) int64              { return map[bool]int64{true: -v, false: v}[v < 0] }
func money(c int64) string             { return fmt.Sprintf("%d.%02d", c/100, abs64(c)%100) } // 负号由 c/100 带出来：全程整数分，只在展示层拼小数点
func minName(n int) string             { return []string{"——", rViewer, rEditor, rOwner}[min(3, n)] }
func cell(r string, n int) string      { return map[bool]string{true: "允许", false: "403"}[rank[r] >= n] }
func pr(p string, rows [][]any) {
	for _, r := range rows {
		fmt.Printf(p, r...)
	}
}
func who(uid string) acct { return sess[uid] } // 会话是唯一来源：fam/role/live 都从这里解出，任何外部参数都改不动它
func rowsOf(fam, mid string) (int, int64) { // rowsOf = SELECT count(*), SUM(amount_cents) ... WHERE family_id=? AND member_id=? AND deleted_at IS NULL（fam=="soft" 专取软删行）
	n, sum := 0, int64(0)
	for _, t := range txns {
		ok := (fam == "soft") == soft[t.id] && (fam == "soft" || (t.fam == fam && (mid == "-" || t.mid == mid)))
		n, sum = n+yes[ok], sum+int64(yes[ok])*amt[t.id]
	}
	return n, sum
}
func agg(f, m string) string { n, s := rowsOf(f, m); return fmt.Sprintf("%d 笔 %s 元", n, money(s)) }

// serve：同一个接口装两版做法。strict=true 是 ✅ 红线版（别家资源与不存在同码同体 404）；strict=false
// 是 ❌ 崩法版（别家资源返 403，把「这个 id 真实存在」告诉了探测者）。判定顺序定死：认证 → 归属 → 角色。
func serve(a acct, id string, need int, strict bool) (int, string) {
	f, known := res[id]
	cross, noRole := known && f != a.fam, known && f == a.fam && rank[a.role] < need
	st := map[bool]int{true: 401, false: map[bool]int{true: 404, false: map[bool]int{true: map[bool]int{true: 404, false: 403}[strict], false: map[bool]int{true: 403, false: 200}[noRole]}[cross]}[!known]}[a.live != "on" || a.fam == ""]
	return st, map[int]string{401: "未登录或 token 过期：连 family_id 都解不出来，一次查询都不发", 404: "资源不存在", 200: fmt.Sprintf("%s 在 %s 内允许该操作", a.role, f), 403: map[bool]string{true: fmt.Sprintf("该资源属于 %s，不属于你的家庭", f), false: fmt.Sprintf("本家庭内角色 %s 不足（需 %s 及以上）", orNone(a.role), minName(need))}[cross]}[st]
}
func codeOf(a acct, id string, need int) int { st, _ := serve(a, id, need, true); return st }
func drySQL(fam, mid string) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("finance_transaction").Where("family_id = ? AND deleted_at IS NULL AND member_id = ?", fam, mid).Order("occurred_at desc").Find(&[]qRow{})
	})
} // 唯一入参 fam 由会话解出：SQL 里没有 query 参数能插进去的位置

