		{mark[ok2], "②", "跨家庭读写一律 404、不是 403", fmt.Sprintf("同一批 %d 个 id：%d 个真实存在，403 版全部点名（与「不存在」不同码 %d 条）；404 版对 fam-A 的 t-06/m-dan 返 %d/%d", len(probe), known, diff, codeOf(who("u-bob"), "t-06", 2), codeOf(who("u-bob"), "m-dan", 1))},
		{mark[ok3], "③", "401／403／404 三者分工不混用", fmt.Sprintf("%d/%d 条落在期望码：未登录 %d 条→401（一次查询都没发）、本家角色不足 %d 条→403、跨家庭+真不存在 %d 条→404", hit, len(cases), c1, c2, c3)},
		{mark[ok4], "④", "viewer 零写权限、只读不受影响", fmt.Sprintf("矩阵 %d 格里 %d 格判 403；写类操作 %d 个逐格实打全部 403=%v；同一会话读本家名录 → %d（读的那 %d 格照样放行）", len(ops)*3, denied, wOps, vDenied, codeOf(who("u-cara"), famA+":list", 1), allowed)},
		{mark[ok5], "⑤", "监护人代写只在本家庭内成立", fmt.Sprintf("owner 代写本家无账号成员 m-kid → %d；本家 editor 代写别家 m-kid2 → %d；别家 owner 代写 m-kid → %d（后两条是 404 而不是 403）", st, codeOf(who("u-bob"), "m-kid2", 2), codeOf(who("u-dan"), "m-kid", 2))},
		{mark[ok6], "⑥", "角色变更后在途请求不得继续用旧档写", fmt.Sprintf("famVer[%s] 7→%d；uid 版只 %d 个 key、恒命中旧档 %s、放行写 %d 次（越权窗口 %d 秒）；版本版 %d 个 key，降档后新 key miss → 回源读到 %s", famA, famVer[famA], len(old), rEditor, overOld, win, len(fresh), rViewer)},
	})
	fmt.Printf("  %s 六条断言通过 %d/6。\n", mark[k == 6], k)
	fmt.Println("  模拟清单：本机无 HTTP 服务（状态码由 serve() 现场返回，不是真 gin 路由）、无 PostgreSQL（行集是内存表，SQL 是 GORM DryRun 原文：DisableAutomaticPing + 固定 NowFunc）。")
	fmt.Println("  真环境要复跑四条：① 真实 JWT 逐条打第 5 节那 11 个请求，断言状态码与本表逐行同值；② 用 fam-B 会话枚举 fam-A 的 id，断言全部 404 且响应体不含 fam-A 字样；")
	fmt.Println("  ③ EXPLAIN 第 2 节那条 SQL，确认走 (family_id, occurred_at) WHERE deleted_at IS NULL 的部分索引；④ 改一次角色，断言在途请求下一次读回源（role_version 变了）而不是旧缓存。")
	fmt.Println("  明天（d05）：成员退出与被记录者删除 —— 级联是禁区，软删必须有恢复路径，报表一笔都不能少。")
