// W49 d05：成员退出与被记录者删除 —— 级联是禁区，软删必须有恢复路径
// 这一天在解决什么问题：① 「这个人没了」在家庭账本里其实是两件事 —— family_member 的关系可以终止，被记账的 member
// 只该软删；顺手挂 ON DELETE CASCADE 是最省事的写法，第 2 节把它的后果真算一遍（物理少几行、逐月报表各低几分），
// 再与软删版并排。② 软删不是终点：第 4 节走恢复路径，拿第 1 节存下的基线快照逐月对账 —— 恢复后报表回到「基线 +
// 窗口里新记的账」这一版，不是某个历史快照。③ 删除是写接口：跨家庭 404、本家角色不足 403、未登录 401、非法参数
// 400 给合法形状、对已在／不在软删态的人再动是 410／409，同一个 client_request_id 连点两次只留一条审计。
// 本机无 PG／无 HTTP 服务：三张表在内存真跑，SQL 用 GORM DryRun 出方言原文（真环境复跑项见第 6 节）。
// 学员侧跑法：cd homecube/server && go run ./lab/s12/d05
package main

import (
	"fmt"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gormlogger "gorm.io/gorm/logger"
)

type sess struct{ uid, fam, role, live string } // 会话：uid → 家庭／角色／登录态（live=="on" 才算已登录）
type mbr struct{ id, fam, disp, dep string }    // member：被记账的人；dep=="dep" 即无账号，只能由监护人代写
type txn struct {
	id, fam, mid, mon string
	amt               int64
}                                                 // 流水：金额一律整数分（支出为负），mon 是账期
type tRow struct{ ID, FamilyID, MemberID string } // 下面两个只是 DryRun 的表映射，不代表真连库
type mRow struct{ ID, FamilyID string }

func (tRow) TableName() string { return "finance_transaction" }
func (mRow) TableName() string { return "member" }

const wSel, tab, ord = "family_id = ? AND deleted_at IS NULL", "finance_transaction", "occurred_at desc" // wSel 是报表行集的唯一口径：第 6 节断言它恒在每一条语句里

var (
	famA, famB               = "fam-A", "fam-B"
	rOwner, rEditor, rViewer = "owner", "editor", "viewer"
	rank, yes                = map[string]int{rViewer: 1, rEditor: 2, rOwner: 3}, map[bool]int{true: 1, false: 0}
	mark, mons               = map[bool]string{true: "✅", false: "❌"}, []string{"2026-08", "2026-09", "2026-10"}
	loc, now                 = mustLoad("Asia/Shanghai"), day0(2026, 10, 12).Add(9 * time.Hour) // 固定时钟：软删与恢复的时刻都从它出发
	us                       = map[string]sess{"u-dad": {"u-dad", famA, rOwner, "on"}, "u-mom": {"u-mom", famA, rEditor, "on"}, "u-zed": {"u-zed", famA, rEditor, "on"}, "u-mao": {"u-mao", famA, rViewer, "on"}, "u-dan": {"u-dan", famB, rOwner, "on"}}
	relOn                    = map[string]bool{"u-dad": true, "u-mom": true, "u-zed": true, "u-mao": true, "u-dan": true} // family_member 关系是否在（终止即 false）
	mFam                     = map[string]string{"m-dad": famA, "m-mom": famA, "m-zed": famA, "m-kid": famA, "m-gran": famA, "m-mao": famA, "m-dan": famB}
	mdel, txd, idem          = map[string]string{}, map[string]bool{"t-07": true}, map[string]string{} // member 软删位（id→deleted_by）／流水自身软删位／client_request_id→首条记录
	audit, base              = []string{}, []txn{}                                                     // 审计行（幂等命中不得新增）／第 1 节存下的基线快照
	members, txns            = []mbr{{"m-dad", famA, "王建国", "-"}, {"m-mom", famA, "李慧", "-"}, {"m-zed", famA, "王哲", "-"}, {"m-mao", famA, "毛阿姨", "-"}, {"m-kid", famA, "王小满", "dep"}, {"m-gran", famA, "王桂芬", "dep"}, {"m-dan", famB, "李丹", "-"}}, []txn{{"t-01", famA, "m-dad", "2026-08", -18900}, {"t-02", famA, "m-mom", "2026-08", -45000}, {"t-03", famA, "m-kid", "2026-08", -28000}, {"t-04", famA, "m-gran", "2026-08", -66000}, {"t-05", famA, "m-mao", "2026-08", -30000}, {"t-06", famA, "m-gran", "2026-09", -128000}, {"t-07", famA, "m-kid", "2026-09", -35000}, {"t-08", famA, "m-mom", "2026-09", -52000}, {"t-09", famA, "m-gran", "2026-09", -88000}, {"t-10", famA, "m-dad", "2026-10", -23000}, {"t-11", famA, "m-gran", "2026-10", -75000}, {"t-12", famA, "m-kid", "2026-10", -41000}, {"t-13", famA, "m-zed", "2026-10", -12000}, {"t-14", famA, "m-mao", "2026-10", -19000}, {"t-15", famB, "m-dan", "2026-09", -36000}, {"t-16", famB, "m-dan", "2026-10", -21000}}
	gdb, _                   = gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_member:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return now }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
)

func mustLoad(n string) *time.Location          { l, _ := time.LoadLocation(n); return l }
func day0(y, m, d int) time.Time                { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, loc) }
func hdr(s string)                              { fmt.Printf("\n===== %s =====\n", s) }
func abs(v int64) int64                         { return map[bool]int64{true: -v, false: v}[v < 0] }
func yuan(c int64) string                       { return fmt.Sprintf("%d.%02d", c/100, abs(c)%100) } // 负号由 c/100 带出来：全程整数分，只在展示层拼小数点
func onOff(b bool) string                       { return map[bool]string{true: "含", false: "不含"}[b] }
func hasID(s string) string                     { return onOff(strings.Contains(s, "family_id")) }
func hasNull(s string) string                   { return onOff(strings.Contains(s, "deleted_at IS NULL")) }
func row(n int, s int64) string                 { return fmt.Sprintf("%d 笔 %s 元", n, yuan(s)) }
func txt(ts []txn, fam, mon, mid string) string { n, s := agg(ts, fam, mon, mid); return row(n, s) }

// agg = 报表行集：WHERE family_id=会话家庭 AND deleted_at IS NULL。"-" 不限；mid 带 "!" 前缀即「这个人的行
// 已经物理消失」（❌ 级联版的口径）；fam=="txd" 专取流水自身被软删的那几行。
func agg(ts []txn, fam, mon, mid string) (int, int64) {
	n, s := 0, int64(0)
	for _, t := range ts {
		ok := (fam == "txd") == txd[t.id] && (fam == "txd" || (t.fam == fam && (mon == "-" || t.mon == mon) && (mid == "-" || strings.HasPrefix(mid, "!") != (t.mid == strings.TrimPrefix(mid, "!")))))
		n, s = n+yes[ok], s+int64(yes[ok])*t.amt
	}
	return n, s
}
func dir(fam string) int { // 名录在册人数：软删过的 member 不再出现，但一笔流水都不会因此消失
	n := 0
	for _, m := range members {
		n += yes[m.fam == fam && mdel[m.id] == ""]
	}
	return n
}

// api：三个写接口共用一条判定链 —— DELETE /api/v1/members/:id（软删）、PATCH …/restore（恢复）、
// POST /api/v1/transactions?member_id=…（记一笔）。顺序定死：认证 → 参数 → 归属 → 角色 → 状态；跨家庭与
// 真不存在同码同体（404），本家庭角色不足才是 403，非法参数 400 给合法形状、绝不回落，也绝不替你级联。
func api(a sess, v, id, q string, do bool) (int, string) {
	f, known := mFam[id]
	need, rest := map[string]int{"POST": rank[rEditor], "DELETE": rank[rOwner], "PATCH": rank[rOwner]}[v], v == "PATCH"
	ill, gone := q != "" && !strings.HasPrefix(q, "reason="), mdel[id] != ""
	st := map[bool]int{true: 401, false: map[bool]int{true: 400, false: map[bool]int{true: 404, false: map[bool]int{true: 404, false: map[bool]int{true: 403, false: map[bool]int{true: map[bool]int{true: 409, false: 410}[rest], false: 200}[gone != rest]}[rank[a.role] < need]}[known && f != a.fam]}[!known]}[ill]}[a.live != "on" || a.fam == ""]
	if st == 200 && do && v != "POST" { // POST 只过判定，不落进 member_audit；软删／恢复才动名录与审计
		mdel[id], audit = map[bool]string{true: "", false: a.uid}[rest], append(audit, v+" member/"+id+" by "+a.uid)
	}
	return st, map[int]string{401: "未登录或 token 过期：连 family_id 都解不出来，一条 UPDATE 都不发", 400: fmt.Sprintf(`非法参数 %s：%s /api/v1/members/:id 只收 body {"client_request_id":"crid-…"}`+"，不回落默认档、更不会替你级联", q, v), 404: "资源不存在（跨家庭与真不存在同码同体）", 409: "该成员没在软删态里，无需恢复（不回落成一次空写、也不替它补审计）", 410: "该成员已软删（deleted_by=" + mdel[id] + "）：恢复请走 PATCH /api/v1/members/" + id + "/restore", 403: fmt.Sprintf("本家庭内角色 %s 不足：%s 要 %s 及以上", map[bool]string{true: a.role, false: "无关系"}[a.role != ""], map[bool]string{true: "改／恢复 member", false: "记一笔"}[need == rank[rOwner]], []string{"——", rViewer, rEditor, rOwner}[min(3, need)]), 200: map[string]string{"POST": fmt.Sprintf("%s 在 %s 内记一笔（dep 成员由监护人代写）", a.role, f), "DELETE": "已软删：只写 deleted_at / deleted_by，finance_transaction 一行都不动", "PATCH": "已恢复：deleted_at / deleted_by 置空 + 一条审计；流水从未被删，报表原样回来"}[v]}[st]
}

// submit：写接口共用的幂等门 —— 同一个 client_request_id 第二次进来必须拿回首条记录，不重复执行。
func submit(crid, what string) (string, bool) {
	r, hit := idem[crid]
	idem[crid] = map[bool]string{true: r, false: what}[hit]
	return idem[crid], hit
}
func sqlOf(k string) string { return gdb.ToSQL(sqls[k]) }
func up(m any, whr string, set map[string]any) func(*gorm.DB) *gorm.DB {
	return func(t *gorm.DB) *gorm.DB { return t.Model(m).Where(whr, "m-gran", famA).Updates(set) }
}
func qCas(t *gorm.DB) *gorm.DB { return t.Where("member_id = ?", "m-gran").Delete(&tRow{}) }
func qSel(t *gorm.DB) *gorm.DB { return t.Table(tab).Where(wSel, famA).Order(ord).Find(&[]tRow{}) }

var sqls = map[string]func(*gorm.DB) *gorm.DB{"cascade": qCas, "select": qSel,
	"soft":    up(&mRow{}, "id = ? AND family_id = ? AND deleted_at IS NULL", map[string]any{"deleted_at": now, "deleted_by": "u-dad"}),
	"restore": up(&mRow{}, "id = ? AND family_id = ? AND deleted_at IS NOT NULL", map[string]any{"deleted_at": nil, "deleted_by": nil})}

func main() {
	hdr("1. 场景：member 名录 ／ family_member 关系 ／ finance_transaction 流水 —— 金额全程整数分")
