	fmt.Printf("  %-9s %-8s %-10s %-26s %s\n", "member", "family", "称谓", "记账方式", "名下可见流水（现算）")
	for _, m := range members {
		fmt.Printf("  %-9s %-8s %-10s %-26s %s\n", m.id, m.fam, m.disp, map[bool]string{true: "无账号：只能监护人代写", false: "本人有账号，可自记"}[m.dep == "dep"], txt(txns, m.fam, "-", m.id))
	}
