		fmt.Printf("  %-10s %-16s %-16s %-17s %-10s %s\n", mo, row(bn, bs), row(gn, gs), fmt.Sprintf("%d 笔 %s 元", bn-gn, yuan(abs(bs-gs))), yuan(bs-gs), mark[bn == gn && bs == gs])
	}
