	fmt.Printf("  %-10s %-16s %-16s %-17s %-10s %s\n  基线逐月相加 %s 与总计 %s 逐字相等（%v）：分组不漏行、不重行 —— 上面 ✅ 软删版的每一行就是这一版基线\n  ❌ 级联：物理少 %d 行、家庭报表少了 %s 元，%d/%d 个账期全部掉数 —— 没写 deleted_at，无可清理的标记，只能拿备份重放，重放回来的 occurred_at／created_by 也不再是原样\n  ✅ 软删（%d，已在内存表真执行）：%s\n     报表 %s —— 与删前逐字相等（笔差 %d、分差 %s 元）；成员名录 %d → %d 人；审计 %d 条\n", "合计", row(na, sa), row(cn2, cs2), fmt.Sprintf("%d 笔 %s 元", na-cn2, yuan(abs(sa-cs2))), yuan(sa-cs2), mark[cn2 == na], row(totN, totS), row(na, sa), totN == na && totS == sa, na-cn2, yuan(abs(sa-cs2)), lostM, len(mons), st, body, row(pN, pS), pN-na, yuan(pS-sa), d0, dir(famA), len(audit))
	fmt.Printf("  逐行对账：每笔流水在两版里各会怎样（金额分毫现算；最后一列只说 ❌ 级联版对 m-gran 的行干了什么）\n  %-6s %-6s %-8s %-9s %-10s %-15s %-9s %s\n", "流水", "家庭", "member", "账期", "金额（分）", "进 fam-A 报表？", "金额（元）", "❌ 级联后会怎样")
	for _, t := range txns {
