func hdr(s string)              { fmt.Printf("\n===== %s =====\n", s) }
func abs(v int64) int64         { return map[bool]int64{true: -v, false: v}[v < 0] }
func yuan(c int64) string       { return fmt.Sprintf("%d.%02d", c/100, abs(c)%100) }
func hasID(s string) string     { return inc[strings.Contains(s, "family_id")] }
func hasNul(s string) string    { return inc[strings.Contains(s, "deleted_at IS NULL")] }
func row(n int, s int64) string { return fmt.Sprintf("%d 笔 %s 元", n, yuan(s)) }
func aliveU(id string) bool     { u := bound[id]; return u != "" && !closed[u] }
func sqlOf(k string) string     { return gdb.ToSQL(sqls[k]) }
func qm(t *gorm.DB, w string, a ...any) *gorm.DB {
	return t.Model(&Member{}).Where(w, a...).Find(&[]Member{})
}
func qt(t *gorm.DB, w string, a ...any) *gorm.DB {
	return t.Table(tab).Where(w, a...).Order(ord).Find(&[]TxnRow{})
}

// agg：报表行集的唯一口径实现。via=0 ✅（member 口径）；via=1 ❌ 混列（账挂账号：INNER JOIN user_account，注销即掉）；
// via=2 ❌ 漏 family_id、按 display_name 查全部家庭（第 3 节反例口径，只此一处）；via=3 ✅ 按名字但恒带 family_id（第 2 节同名口径）。
func agg(fam, mon, mid string, via int) (int, int64) {
	n, s := 0, int64(0)
	for _, t := range txns {
		ok := mdel[t.mid] == "" && (mon == "-" || t.mon == mon) && map[bool]bool{true: via >= 2 && mName[t.mid] == mid && (via == 2 || mFam[t.mid] == fam), false: mFam[t.mid] == fam && (mid == "-" || t.mid == mid) && (via != 1 || aliveU(t.mid))}[via >= 2]
		n, s = n+yes[ok], s+int64(yes[ok])*t.amt
	}
	return n, s
}

func csvRow(t txn) string {
	return strings.Join([]string{t.id, t.mid, mName[t.mid], t.mon, fmt.Sprint(t.amt), "CNY"}, ",")
} // 导出点名靠 member_id，名字只作展示列

// claim：领取动作。guarded=true 就是 d03 那条 UPDATE…WHERE id AND family_id AND state='pending' 的内存语义（affected rows==1 者胜）。
func claim(guarded bool, ch chan int) {
	mu.Lock()
	defer mu.Unlock()
	ok := !guarded || inv.State == ps
	if ok {
		inv.State, accN = ac, accN+1
	}
	ch <- map[bool]int{true: 200, false: 409}[ok]
}

// drain：并发结果先进 channel 收齐再交回（硬规矩 1）；win＝200 计数，all＝原样收集供排序打印。
func drain(ch chan int) (int, []int) {
	win, all := 0, []int{}
	for i := 0; i < 8; i++ {
		c := <-ch
		all = append(all, c)
		win += yes[c == 200]
	}
	return win, all
}

// tick：到期中心到点 —— 只有在册（due 登记命中）且 pending 才动手，口径逐字沿用 d03；accepted 是死状态。
func tick() int {
	_, live := dueReg[ss+"|"+inv.ID+"|expire"]
	act := live && inv.State == ps
	if act {
		inv.State = exp
	}
	return yes[act]
}

var sqls = map[string]func(*gorm.DB) *gorm.DB{
	"memFam": func(t *gorm.DB) *gorm.DB { return qm(t, qYes, famA, xm) },
	"memNo":  func(t *gorm.DB) *gorm.DB { return qm(t, qNo, xm) },
	"byId":   func(t *gorm.DB) *gorm.DB { return qt(t, qBy, "m-kid", famA) },
	"txFam":  func(t *gorm.DB) *gorm.DB { return qt(t, wSel, famA) },
	"claim": func(t *gorm.DB) *gorm.DB {
		return t.Model(&Invite{}).Where(qClaim, inv.ID, famA, ps).Update("state", ac)
	},
	"close": func(t *gorm.DB) *gorm.DB {
		return t.Model(&UserAccount{}).Where("id = ?", "u-mao").Updates(map[string]any{"status": "closed", "deleted_at": now, "deleted_by": "u-dad"})
	},
}

// 字段契约文档：列名→(谁写, 谁读)；打印顺序＝结构体字段声明序（reflect），与 map 存放顺序无关。
var rwOf = map[string][2]string{
	"id": {"各表创建方", "所有查询返回列；跨表引用、点名一律用它，不用名字"}, "username": {"注册流程", "登录口（唯一键）"},
	"phone": {"本人档案页", "通知投递渠道"}, "status": {"本人＋owner 注销口", "认证中间件（只 active 放行）"},
	"created_at": {"落库时写入", "审计列表"}, "deleted_at": {"注销／软删接口（d05 同款列名）", "报表与名录的 WHERE deleted_at IS NULL"},
	"deleted_by": {"同一写接口带会话 uid", "审计「谁删的」"}, "family_id": {"只从会话注入，不收 query 参数", "恒进每条查询／每条日志（d04 立规矩）"},
	"display_name": {"owner／editor 改档案", "报表、CSV、通知展示列（可重名，点名靠 id）"}, "legal_name": {"owner 上传证件时", "永不进 CSV，仅对账争议人工查（d02 边界）"},
	"nickname": {"本人可改", "仅 App 内家人视图，不进导出"}, "user_id": {"邀请 accepted 时绑定", "会话 uid→在册成员（能登录的判定位）"},
	"member_id": {"建关系时指定", "代写时校验被记账人是否本家"}, "role": {"owner 改角色", "中间件按最低角色拦截（403 档）；W50 的 min_role 读这列"},
	"joined_at": {"关系建立时", "成员明细"}, "terminated_at": {"owner 终止关系（d05：≠ 软删成员）", "关系是否在册的判定位"},
}

func printCols(tbl string, v any) { // 契约一行一列，全从结构体现打：类型＝Go 字段类型，可空＝是否指针
	rt := reflect.TypeOf(v)
	for i := 0; i < rt.NumField(); i++ {
		tg, nm := rt.Field(i).Type.String(), (&schema.NamingStrategy{}).ColumnName("", rt.Field(i).Name)
		rw := rwOf[nm]
		fmt.Printf("  %-15s %-15s %-14s %-4s %-26s %s\n", tbl, nm, map[bool]string{true: "timestamptz", false: "varchar"}[strings.Contains(tg, "time.Time")], map[bool]string{true: "是", false: "否"}[strings.HasPrefix(tg, "*")], rw[0], rw[1])
	}
}

