	ck(more == 0 && dueT == 0 && inv.State == ac && accN == win, "⑧ 状态机与关系表自洽", fmt.Sprintf("已 accepted 后迟到请求 200×%d、到期中心动手 %d 条、family_member 只 +accepted 事件（+%d）；死状态不可再迁（d03 边集）", more, dueT, accN))
	fmt.Printf("  %s W49 判据通过 %d/8。\n", mark[k == 8], k)
	fmt.Printf("  交 W50 的字段契约（由上面三个 GORM 模型 reflect 现打——列名／类型就是程序真在用的那份；可空：是＝NULL 允许＝可空指针类型）：\n")
	fmt.Printf("  %-15s %-15s %-14s %-4s %-26s %s\n", "表", "列", "类型", "可空", "谁写", "谁读")
	printCols("user_account", UserAccount{})
	printCols("member", Member{})
	printCols("family_member", FamilyMember{})
	fmt.Printf("  契约三条硬话：① 点名一律 id——display_name 可重名（今天在场：同家庭同名 %d 人一组＋跨家庭重名一组）；② family_id 只从会话注入、恒进每条查询；③ deleted_at 必须配 deleted_by，member 与 user_account 共用 d05 那套软删列名，关系终止走 family_member.terminated_at——W50 面配置的 min_role 直接读 family_member.role。\n", sameN)
	fmt.Println("  以上全是内存表 + GORM DryRun（DisableAutomaticPing + 固定 NowFunc），无真实数据库、无库层并发竞争。真环境复跑四条：① family_invite 上并发重放第 5 节 UPDATE 8 次，断言 affected rows 合计==1；② 报表 SQL EXPLAIN，断言走 (family_id, deleted_at) 索引且无按 display_name 的 join；③ fam-B token 查 fam-A 的小明，断言 404 且响应体不含 fam-A 字样；④ 注销 u-mao 后跑 fam-A 报表，断言行数分毫不差。明天进 W50：面配置（d07 面目录 registry）。")
}

// =====================================================================
// W50 d07：什么是「面」—— 面目录（registry）为什么不能写死在前端
//
// S12 讲「面配置」：HomeCube 首页每个功能块（账本 / 预算 / 报表 / 导出 / 设置 / 提醒 / 动态…）都叫一个
// 「面」。今天先把目录立起来：code / 名称 / 依赖服务 / 最低角色 / 是否已出生，一处声明。「不能写死在前端」
// 的三处代价不靠文案声称，本程序全部当场算成集合差（面集合用位掩码表示，差集就是 &^，能点名到 code）：
//
//	① 新增一个面要发版：服务端目录 11 个 code、bundle 手抄那份 11 行，两边各多/少哪个，逐 code 点名；
//	② 灰度做不了：硬编码只有全局布尔、没有 family 维度 → 四格（两家×两档）清单各多出/少掉几个 code；
//	③ 角色改了前端不知道：目录把 finance.export 的最低角色 viewer→owner，bundle 那份没跟 → 真打状态码。
//
// ④ 同一份目录在 Go 侧与 TS 侧各写一遍会漂成两样：TS 那份以源码文本内嵌、由本程序逐行解析成真清单，再与
// Go 侧逐 code 逐字段对拍 —— 漂移处数、落在几个 code 上、规范化后有哪几行不一致，全是 diff 算出来的。
// 本机无 PG / 无 HTTP / 无前端构建：行集是内存表，SQL 是 GORM DryRun 原文（DisableAutomaticPing + 固定
// NowFunc），状态码由 get() 现场返回；「今天」钉在 2026-10-12，出生按日期字典序判，两次跑字节一致。
// 学员侧跑法：cd homecube/server && go run ./lab/s12/d07
// =====================================================================
package main

import (
	"fmt"
	"regexp"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gormlogger "gorm.io/gorm/logger"
)

const (
	rOwner, rEditor, rViewer = "owner", "editor", "viewer"
	famA, famB               = "fam-A", "fam-B"
	today                    = "2026-10-12" // 「今天」钉死：出生按 YYYY-MM-DD 字典序比，不取 time.Now()
)

// ---------- 目录：全项目唯一一处声明（Go 侧 v11）。rollout = 出生灰度批次白名单：nil 表示全量出生 ----------
type face struct {
	code, name, svc, minRole, bornAt string
	rollout                          []string
}

var reg = []face{
	{"home.summary", "首页摘要", "homeos-core", rViewer, "2026-03-01", nil},
	{"finance.ledger", "账本", "finance-svc", rViewer, "2026-03-01", nil},
	{"finance.budget", "预算", "finance-svc", rEditor, "2026-04-15", nil}, // bundle 里这个 name 被抄成了「预算看板」
	{"family.settings", "家庭与成员设置", "member-svc", rOwner, "2026-04-01", nil},
	{"finance.report", "报表", "analytics-svc", rViewer, "2026-05-10", nil},
	{"finance.export", "导出 CSV", "finance-svc", rOwner, "2026-06-01", nil}, // v10→v11：最低角色 viewer→owner，今天动的就是这格
	{"notify.center", "提醒中心", "notify-svc", rViewer, "2026-06-20", nil},    // 依赖服务名在 bundle 里被抄成了 notification-svc
	{"activity.feed", "动态流", "activity-svc", rViewer, "2026-07-05", nil},
	{"homeos.panel", "设备面板", "iot-svc", rEditor, "2026-08-01", []string{famB}},            // 出生了，但只对 fam-B 这个批次
	{"insight.cashflow", "现金流透视", "analytics-svc", rViewer, "2026-10-01", []string{famB}}, // 今天刚进目录的新面，bundle 里没有
	{"lab.recipe", "实验室·菜谱", "lab-svc", rEditor, "2026-11-20", nil},                       // 还没出生，bundle 里却写着 born: true
}

// ---------- family_face：家庭级开关表（内存表）。行前缀 "!" = enabled=false；没列的 code = 本家压根没这行 ----------
var ffRows = map[string][]string{
	famA: {"home.summary", "finance.ledger", "finance.budget", "family.settings", "finance.report", "!finance.export", "notify.center", "activity.feed", "homeos.panel", "lab.recipe", "finance.wallet.v1"},
	famB: {"home.summary", "finance.ledger", "!finance.budget", "finance.report", "finance.export", "!notify.center", "activity.feed", "homeos.panel", "!lab.recipe", "insight.cashflow"},
}                                                                                                                                         // fam-A 多一条 finance.wallet.v1 残留行（目录里已下架）、fam-B 没写 family.settings 那一行
var limit = map[string]int64{famA + "|finance.budget": 25000000, famB + "|finance.budget": 30000000, famA + "|finance.wallet.v1": 180000} // monthly_limit_cents：整数分

// ---------- 客户端 bundle 里手抄的那份：以 TS 源码文本内嵌，由本程序逐行解析成真清单 ----------
const tsSrc = `export type Face = { code: string; name: string; service: string; minRole: Role; born: boolean };
export const FACE_CATALOG: Face[] = [
  { code: "home.summary", name: "首页摘要", service: "homeos-core", minRole: "viewer", born: true },
  { code: "finance.ledger", name: "账本", service: "finance-svc", minRole: "viewer", born: true },
  { code: "finance.budget", name: "预算看板", service: "finance-svc", minRole: "editor", born: true },
  { code: "finance.report", name: "报表", service: "analytics-svc", minRole: "viewer", born: true },
  { code: "finance.export", name: "导出 CSV", service: "finance-svc", minRole: "viewer", born: true },
  { code: "notify.center", name: "提醒中心", service: "notification-svc", minRole: "viewer", born: true },
  { code: "activity.feed", name: "动态流", service: "activity-svc", minRole: "viewer", born: true },
  { code: "family.settings", name: "家庭与成员设置", service: "member-svc", minRole: "owner", born: true },
  { code: "homeos.panel", name: "设备面板", service: "iot-svc", minRole: "editor", born: true },
  { code: "lab.recipe", name: "实验室·菜谱", service: "lab-svc", minRole: "editor", born: true },
  { code: "finance.wallet.v1", name: "钱包", service: "finance-svc", minRole: "viewer", born: true },
];`

var (
	rank    = map[string]int{rViewer: 1, rEditor: 2, rOwner: 3}
	mark    = map[bool]string{true: "✅", false: "❌"}
	yes     = map[bool]int{true: 1, false: 0}
	roles   = []string{rViewer, rEditor, rOwner}
	fams    = []string{famA, famB}
	regBy   = map[string]face{}
	tsBy    = map[string]map[string]string{}
	tsOrder []string           // bundle 那份的源码序：解析时按行追加，打印时不依赖 map 序
	by      = map[string]int{} // code → 位槽（1 起）：槽 0 留给「查无此 code」，bit() 直接给空掩码
	order   []string           // 目录声明序 + bundle 独有的 code；打印集合时用它当稳定键
	regM    uint32
	tsAll   uint32 // bundle 那份的 code 全集（只 OR，与 map 序无关）
	enM     = map[string]uint32{}
	bornM   = map[string]uint32{}
	roleM   = map[string]uint32{} // ✅ 按目录 min_role 的角色可见集
	cliM    = map[string]uint32{} // ❌ 按 bundle 那份 min_role/born 算出来的前端清单
	rowN    = map[string]int{}
	onN     = map[string]int{}
	rf      = regexp.MustCompile(`(\w+)\s*:\s*("[^"]*"|[A-Za-z]+)`)
	now     = time.Date(2026, 10, 12, 9, 0, 0, 0, time.UTC) // 固定时钟：DryRun 的写入值与两次跑字节都靠它
	gdb, _  = gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_face:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return now }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
)

// ---------- 会话：family_id / role 只从会话解出（live=="off" 是 token 过期：连 family_id 都解不出来）----------
type acct struct{ uid, fam, role, live string }
type ffRow struct{ Code string }

var accts = map[string]acct{"u-ann": {"u-ann", famA, rOwner, "on"}, "u-bob": {"u-bob", famA, rEditor, "on"},
	"u-cara": {"u-cara", famA, rViewer, "on"}, "u-faye": {"u-faye", famB, rOwner, "on"},
	"u-gus": {"u-gus", famB, rViewer, "on"}, "u-zed": {"u-zed", famA, rEditor, "off"}}

func who(uid string) acct { return accts[uid] }
func hdr(s string)        { fmt.Printf("\n===== %s =====\n", s) }
func pr(p string, rs [][]any) {
	for _, r := range rs {
		fmt.Printf(p, r...)
	}
}
func abs64(v int64) int64 { return map[bool]int64{true: -v, false: v}[v < 0] }
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs64(c)/100, abs64(c)%100)
}
func join(xs []string) string {
	return map[bool]string{true: strings.Join(xs, ", "), false: "——"}[len(xs) > 0]
}
func inXs(xs []string, x string) bool {
	return strings.Contains("|"+strings.Join(xs, "|")+"|", "|"+x+"|")
}
func bit(c string) uint32 { return map[bool]uint32{true: 1 << uint(by[c]-1), false: 0}[by[c] > 0] }
func isReg(c string) bool { _, ok := regBy[c]; return ok }
func nameOf(c string) string {
	return map[bool]string{true: regBy[c].name, false: tsBy[c]["name"]}[isReg(c)]
}
func isBorn(f face) bool { return f.bornAt <= today }
func bornFor(f face, fam string) bool {
	return isBorn(f) && (len(f.rollout) == 0 || inXs(f.rollout, fam))
}
func msk(b bool, c string) uint32    { return map[bool]uint32{true: bit(c), false: 0}[b] } // 判定成立才给这一位
func vis(f face, role string) uint32 { return msk(rank[role] >= rank[f.minRole], f.code) }
func cliVis(c string, m map[string]string, role string) uint32 {
	return msk(m["born"] == "true" && rank[role] >= rank[m["minRole"]], c)
}

// build：把目录 / family_face / 出生批次 / bundle 那份一次摊成位掩码，之后的集合运算全是位运算。
// 只往掩码里 OR，与 map 遍历顺序无关，所以两次跑字节一致；打印时统一过 pick() 回到目录声明序。
func build() {
	for _, f := range reg {
		regBy[f.code] = f
	}
	for _, ln := range strings.Split(tsSrc, "\n") {
		if i := strings.Index(ln, `{ code: "`); i >= 0 { // 真解析内嵌源码：逐行抽 key:value 去引号，这份清单不是我手打的 map
			m := map[string]string{}
			for _, g := range rf.FindAllStringSubmatch(ln[i:], -1) {
				m[g[1]] = strings.Trim(g[2], `"`)
			}
			tsBy[m["code"]] = m
			tsOrder = append(tsOrder, m["code"])
		}
	}
	for _, f := range reg {
		order = append(order, f.code)
	}
	for _, c := range tsOrder {
		if _, ok := regBy[c]; !ok && !inXs(order, c) {
			order = append(order, c)
		}
	} // bundle 独有的也得有槽，否则差集算不出来
	for i, c := range order {
		by[c] = i + 1
	}
	for _, f := range reg {
		regM |= bit(f.code)
	}
	for _, c := range tsOrder {
		tsAll |= bit(c)
	}
	for fam, xs := range ffRows {
		for _, s := range xs {
			rowN[fam]++
			if !strings.HasPrefix(s, "!") {
				enM[fam] |= bit(strings.TrimPrefix(s, "!"))
			}
			onN[fam] += yes[!strings.HasPrefix(s, "!")]
		}
	}
	for _, fam := range fams {
		for _, f := range reg {
			bornM[fam] |= msk(bornFor(f, fam), f.code)
		}
	}
	for _, role := range roles {
		for _, f := range reg {
			roleM[role] |= vis(f, role)
		}
		for c, m := range tsBy {
			cliM[role] |= cliVis(c, m, role)
		}
	}
}
func pick(mk uint32) []string { // 掩码 → code 列表，按目录声明序（稳定键）
	var o []string
	for _, c := range order {
		o = append(o, mskStr(mk&bit(c) != 0, c)...)
	}
	return o
}
func mskStr(b bool, c string) []string { return map[bool][]string{true: {c}, false: nil}[b] }
func cnt(mk uint32) int                { return len(pick(mk)) }
func nm(mk uint32) string              { return join(pick(mk)) } // 掩码 → 稳定序 code 列表文本

// get 装 GET /api/v1/faces/:code，判定顺序定死：认证 → 形状合法（在不在目录）→ 本家合成清单 → 角色。
// strict=false 是 ❌ 版：非法 code 静默回落到清单头一个面，照样 200。
func get(a acct, code string, strict bool) (int, string) {
	if a.live != "on" || a.fam == "" {
		return 401, "未登录：family_id 都解不出来，一次查询都不发"
	}
	if !isReg(code) {
		if !strict {
			return 200, fmt.Sprintf("面 %s 的入口渲染成了清单头一个「%s」", code, nameOf(firstCode(srvList(a.fam, a.role))))
		}
		return 400, fmt.Sprintf("非法 code %q：不在目录的 %d 个 code 里。合法形状=下面这些 code 之一：[%s]", code, len(reg), join(codes()))
	}
	if srvFull(a.fam)&bit(code) == 0 {
		return 404, fmt.Sprintf("面 %s 对 %s 不存在（未启用 / 未出生 / 不在本家的出生批次）", code, a.fam)
	}
	if rank[a.role] < rank[regBy[code].minRole] {
		return 403, fmt.Sprintf("本家庭内角色 %s 不足（需 %s 及以上）", a.role, regBy[code].minRole)
	}
	return 200, fmt.Sprintf("%s：%s（依赖 %s）已下发，monthly_limit_cents=%d", code, regBy[code].name, regBy[code].svc, limit[a.fam+"|"+code])
}
func srvFull(fam string) uint32       { return regM & enM[fam] & bornM[fam] } // 目录 ∩ 本家已启用 ∩ 已出生（角色还没进来）
func srvList(fam, role string) uint32 { return srvFull(fam) & roleM[role] }   // 再叠第 4 层：角色可见
func cliList(role string) uint32      { return cliM[role] }                   // ❌ 前端自己那份：压根没有 family 这个入参
func codes() []string {
	var o []string
	for _, f := range reg {
		o = append(o, f.code)
	}
	return o
}
func firstCode(mk uint32) string {
	return map[bool]string{true: pick(mk)[0], false: "（清单为空）"}[mk != 0]
}
func st(a acct, code string) int { n, _ := get(a, code, true); return n }
func tsLine(code, name, svc, role string, born bool) string {
	return fmt.Sprintf("{ code: %q, name: %q, service: %q, minRole: %q, born: %v },", code, name, svc, role, born)
}
func genTS(code string) string {
	f := regBy[code]
	return tsLine(code, f.name, f.svc, f.minRole, isBorn(f))
} // 由目录生成那一行：客户端那份必须是派生物
func tsRow(code string) string {
	m, ok := tsBy[code]
	return map[bool]string{true: tsLine(code, m["name"], m["service"], m["minRole"], m["born"] == "true"), false: "（bundle 里没这一行）"}[ok]
}
func drySel(fam string) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("family_face").Where("family_id = ? AND deleted_at IS NULL", fam).Order("code").Find(&[]ffRow{})
	})
}
func dryUpd(fam, code string, on bool) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("family_face").Where("family_id = ? AND code = ? AND version = ?", fam, code, 3).Updates(map[string]any{"enabled": on, "monthly_limit_cents": 26000000, "updated_by": "u-ann", "version": 4})
	})
}

func main() {
	build()
	onlySrv, onlyCli := regM&^tsAll, tsAll&^regM // 目录 ∖ bundle、bundle ∖ 目录：位差集，能点名到 code
	fa, fb := rowN[famA], rowN[famB]
	ann, bob, cara, faye, gus, zed := who("u-ann"), who("u-bob"), who("u-cara"), who("u-faye"), who("u-gus"), who("u-zed")
	drift, fieldDrift, rowDrift := [][3]string{}, 0, 0

	hdr(fmt.Sprintf("1. 场景：目录 %d 个面，一处声明 code / 名称 / 依赖服务 / 最低角色 / 出生（今天=%s）", len(reg), today))
	fmt.Printf("  %-17s %-15s %-14s %-8s %-11s %-9s %s\n", "code", "名称", "依赖服务", "最低角色", "出生日", "出生批次", "fam-A/fam-B 已出生")
	bornN, rollN, svcU := 0, 0, map[string]int{}
	for _, f := range reg {
		bornN, rollN = bornN+yes[isBorn(f)], rollN+yes[len(f.rollout) > 0]
		svcU[f.svc]++
		fmt.Printf("  %-17s %-15s %-14s %-8s %-11s %-9s %d/%d\n", f.code, f.name, f.svc, f.minRole, f.bornAt, join(f.rollout), yes[bornM[famA]&bit(f.code) != 0], yes[bornM[famB]&bit(f.code) != 0])
	}
	fmt.Printf("  已出生 %d/%d（lab.recipe 的 2026-11-20 还没到）；按家庭批次出生的 %d 个；依赖服务 %d 个；目录 %d 行 ｜ family_face %d 行（%s %d 行·开着 %d ｜ %s %d 行·开着 %d）\n",
		bornN, len(reg), rollN, len(svcU), len(reg), fa+fb, famA, fa, onN[famA], famB, fb, onN[famB])

	hdr("2. ❌ 代价一：硬编码在前端 —— 新增一个面要发版")
	fmt.Printf("  服务端目录 %d 个 code ｜ bundle 手抄那份解析出 %d 行 ｜ 两边共有 %d 个\n", len(reg), len(tsBy), len(reg)-cnt(onlySrv))
