func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func join(xs []string) string {
	return map[bool]string{true: strings.Join(xs, ", "), false: "——"}[len(xs) > 0]
}
func money(c int64) string {
	abs := map[bool]int64{true: -c, false: c}[c < 0]
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs/100, abs%100)
}

// ---------- 逐行工具：两种写法（env 的 KEY=V、yaml 的 KEY: V）都真解析，注释行/空行跳过 ----------
func stripComment(t string) string {
	if i := strings.Index(t, " #"); i >= 0 {
		return strings.TrimSpace(t[:i])
	}
	return t
}
func splitKV(t string) (string, string, bool) {
	t = strings.TrimPrefix(t, "- ")
	i1, i2 := strings.Index(t, ": "), strings.IndexByte(t, '=')
	switch {
	case i1 >= 0 && (i2 < 0 || i1 < i2):
		return t[:i1], strings.TrimSpace(t[i1+2:]), true
	case i2 > 0:
		return t[:i2], strings.TrimSpace(t[i2+1:]), true
	}
	return "", "", false
}
func isRefVal(v string) bool {
	return strings.HasPrefix(v, "${") && strings.HasSuffix(v, "}") && len(v) > 3
}
func isPathVal(v string) bool { return strings.HasPrefix(v, "/") || strings.HasPrefix(v, "./") }
func isListVal(v string) bool { return strings.HasPrefix(v, "[") && strings.HasSuffix(v, "]") }

// looksPlaintext：值形态判定 —— ${VAR} 引用、*_FILE 挂载路径、[声明名] 列表、空值、短值都不算明文密钥
func looksPlaintext(key, v string) bool {
	if v == "" || isRefVal(v) || isListVal(v) {
		return false
	}
	if strings.HasSuffix(strings.ToUpper(key), "_FILE") || isPathVal(v) {
		return false
	}
	return len(v) >= minSecretLen
}
func fixFor(key string, dsn bool) string {
	if dsn {
		return fmt.Sprintf("%s 只留 ${%s:?…} 引用（或拆 DB_HOST/DB_PORT/DB_USER 分量 + 口令走 %s_FILE: /run/secrets/…），URL 由进程运行时在内存拼装、永不落回文本", key, key, key)
	}
	return fmt.Sprintf("改成 %s: ${%s:?未设置则拒绝启动}，或 %s_FILE: /run/secrets/%s —— 真值只活在 .gitignore 掉的目录/运行时环境里", key, key, key, strings.ToLower(key))
}

// scan：真逐行扫。返回行切片（给行号回查用）与命中表；命中数由 len(fs) 当场得出，不是我数好了写上去的。
func scan(name, text string) ([]string, []finding) {
	lines := strings.Split(strings.TrimSpace(text), "\n")
	var fs []finding
	for i, raw := range lines {
		t := strings.TrimSpace(raw)
		if t == "" || strings.HasPrefix(t, "#") {
			continue
		}
		t = stripComment(t)
		key, val, ok := splitKV(t)
		switch {
		case reCred.MatchString(t):
			k := map[bool]string{true: key, false: "（行本体）"}[ok]
			fs = append(fs, finding{name, i + 1, raw, k,
				"URL 内联凭证 scheme://user:口令@ —— 与键名在不在白名单无关，这一行进了任何会落盘/进仓库的文本就是泄露",
				fixFor(map[bool]string{true: key, false: "HOMECUBE_DSN"}[ok], true)})
		case ok && reSensitive.MatchString(key) && looksPlaintext(key, val):
			fs = append(fs, finding{name, i + 1, raw, key,
				"键名命中白名单（PASSWORD/SECRET/TOKEN/DSN…），值又不是 ${VAR} 引用 / *_FILE 挂载路径 / 声明名列表 → 明文密钥",
				fixFor(key, false)})
		}
	}
	return lines, fs
}
func countRefs(lines []string) int {
	n := 0
	for _, raw := range lines {
		if _, val, ok := splitKV(stripComment(strings.TrimSpace(raw))); ok && isRefVal(val) {
			n++
		}
	}
	return n
}
func hitLines(fs []finding) []string {
	var o []string
	for _, f := range fs {
		o = append(o, fmt.Sprintf("%d", f.line))
	}
	return o
}
func hitKeys(fs []finding) []string {
	var o []string
	for _, f := range fs {
		o = append(o, f.key)
	}
	return o
}
func printFindings(fs []finding) {
	for _, f := range fs {
		fmt.Printf("     L%-2d│%s\n", f.line, strings.TrimRight(f.raw, " "))
		fmt.Printf("        判定：%s\n        正确写法：%s\n", f.why, f.fix)
	}
}

// verify：命中行号必须能指回产物原文（第 f.line 行真含那个键名）—— 行号不是装饰，是可对账的坐标
func verify(lines []string, fs []finding) bool {
	for _, f := range fs {
		if f.line < 1 || f.line > len(lines) || !strings.Contains(lines[f.line-1], f.key) {
			return false
		}
	}
	return len(fs) > 0
}
func show(name string, lines []string) {
	fmt.Printf("  ── %s（%d 行）──\n", name, len(lines))
	for i, ln := range lines {
		fmt.Printf("  %3d│ %s\n", i+1, ln)
	}
}

// ---------- ${VAR} 展开：模拟 docker compose 创建容器时拿 .env 做的插值（纯内存，不调 docker） ----------
func envMap(text string) map[string]string {
	m := map[string]string{}
	for _, ln := range strings.Split(strings.TrimSpace(text), "\n") {
		t := stripComment(strings.TrimSpace(ln))
		if i := strings.IndexByte(t, '='); i > 0 && !strings.HasPrefix(t, "#") {
			m[t[:i]] = strings.TrimSpace(t[i+1:])
		}
	}
	return m
}
func expandRefs(text string, env map[string]string) (string, int) {
	n := 0
	out := reRef.ReplaceAllStringFunc(text, func(m string) string {
		g := reRef.FindStringSubmatch(m)
		if v, ok := env[g[1]]; ok {
			n++
			return v
		}
		return m
	})
	return out, n
}

// ---------- DSN：逐参数点名含义；keyword 式给 GORM/pgx 吃，URL 式给「会被复制粘贴」的场景，两种都由这份参数表拼 ----------
var dsnParts = []struct{ key, val, guards string }{
	{"host", "postgres", "容器网络里的服务名（compose 默认网络 DNS，S14 W58）；写 localhost 指向的是自己那个容器，不是数据库"},
	{"port", "5432", "Postgres 监听端口；host+port 合成这条连接的去向"},
	{"user", pgUser, "业务账号（非超级用户，只授自己库的权限）；与 POSTGRES_USER 同名不同用：建库是它、日常连接也是它，但权限只到本库"},
	{"password", pgPassword, "全链路唯一的明文时刻只存在于装配期的进程内存 —— 不进 .env、不进仓库、不进镜像、打印前先脱敏"},
	{"dbname", pgDB, "库名 = POSTGRES_DB 建的那一个；家庭/业务不按库拆，按 family_id 列拆（S3 起的老口径）"},
	{"sslmode", "disable", "家庭局域网内直连关 TLS；任何公网出口必须换 require（S14 d05）"},
	{"TimeZone", famTZ, "这条连接的会话时区（引擎连接层）：防「timestamp 无时区值读写被解释成哪一刻、CURRENT_TIMESTAMP 按哪区输出」；与 S11 的家庭时区同名不同物 —— 日/月桶归属是业务侧口径，不靠这个参数"},
	{"extra_float_digits", "2", "浮点按精度返回（pgx 惯例）；金额口径不靠它 —— 一律 *_cents 整数分"},
}

func partVal(k string) string {
	for _, p := range dsnParts {
		if p.key == k {
			return p.val
		}
	}
	return ""
}
func kwDSN() string {
	var o []string
	for _, p := range dsnParts {
		o = append(o, p.key+"="+p.val)
	}
	return strings.Join(o, " ")
}
func urlDSN() string {
	u := &url.URL{Scheme: "postgres"}
	q := url.Values{}
	for _, p := range dsnParts {
		switch p.key {
		case "host":
			u.Host = p.val
		case "port":
			u.Host = u.Host + ":" + p.val
		case "user":
			u.User = url.UserPassword(p.val, partVal("password"))
		case "password": // 已随 user 进 userinfo
		case "dbname":
			u.Path = "/" + p.val
		default:
			q.Set(p.key, p.val)
		}
	}
	u.RawQuery = q.Encode()
	return u.String()
}
func maskDSN(s string) string { return reCredMask.ReplaceAllString(s, "://${1}:******@") }
func parseURLDSN(s string) (map[string]string, error) {
	u, err := url.Parse(s)
	if err != nil {
		return nil, err
	}
	pw, _ := u.User.Password()
	m := map[string]string{"host": u.Hostname(), "port": u.Port(), "user": u.User.Username(), "password": pw, "dbname": strings.TrimPrefix(u.Path, "/")}
	for k, v := range u.Query() {
		m[k] = v[0]
	}
	return m, nil
}
func dryTx(bound string) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("finance_transaction").
			Where("family_id = ? AND deleted_at IS NULL AND occurred_at >= ? AND amount_cents >= ?", famA, bound, int64(500000)).
			Order("occurred_at, id").Limit(pageLimit).Find(&[]txRow{})
	})
}

