func renderCompose(o composeOpts) string {
	var b strings.Builder
	if err := composeTpl.Execute(&b, struct {
		Drift, PlainDSN bool
		Password        string
	}{o.Drift, o.PlainDSN, pgPassword}); err != nil {
		panic(fmt.Sprintf("compose 模板渲染失败（模板是静态文本，走到这里就是代码 bug）: %v", err))
	}
	return b.String()
}
func dayBoundUTC() string {
	t0, _ := time.Parse(time.RFC3339, stamp)
	sh, err := time.LoadLocation(famTZ)
	if err != nil {
		sh = time.FixedZone(famTZ, 8*3600)
	}
	d := t0.In(sh)
	return time.Date(d.Year(), d.Month(), d.Day(), 0, 0, 0, 0, sh).UTC().Format(time.RFC3339)
}

