// W50 d09：零请求红线 —— 未启用/未出生的面，客户端必须零请求（前端视角，所以这天是 .mjs）
//
// d08 把「目录 ∩ 家庭已启用 ∩ 已出生 ∩ 角色可见」在服务端合成成一份清单；今天验的是消费侧的硬约束：
// 清单之外的 code（lab.recipe 这种没到出生日的、homeos.panel 这种不在本家出生批次的、finance.export 这种
// 本家没开的）—— 客户端一个请求都不许发。请求发了就是 404/400/403 白打一轮，还顺手把「哪些面存在」泄露给探测者。
//
// 本机没有浏览器：这条判据只能这样证 —— 自己写一个假 fetch，计数器真长在发请求的路上（fakeFetch 每被调一次
// 才 +1 并记 URL）；服务端路由 serve() 用与 d07 同一份目录、同一套字段名（code/name/svc/minRole/bornAt/rollout）
// 现算合成清单。正例只请求清单内的 code → 请求数 == 清单长度；反例照旧按 bundle 写死的那份清单把 11 个 code
// 全打一遍 → 被多打的请求数与具体 code 清单当场点名。两端（H5 / App 跑同一份 bundle）并排对数。
// 无耗时、无随机、无 Date.now()、全同步 —— 两次跑字节一致。
// 学员侧跑法：node lab/s12/d09/main.mjs
// =====================================================================

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')
const inXs = (xs, x) => xs.includes(x)
const join = (xs) => (xs && xs.length ? xs.join(', ') : '——')
const mark = { true: '✅', false: '❌' }
const yes = (b) => (b ? 1 : 0)
const abs = (v) => (v < 0 ? -v : v)
const money = (c) => `${c < 0 ? '-' : ''}${Math.floor(abs(c) / 100)}.${String(abs(c) % 100).padStart(2, '0')}`

const R_OWNER = 'owner', R_EDITOR = 'editor', R_VIEWER = 'viewer'
const FAM_A = 'fam-A', FAM_B = 'fam-B'
const TODAY = '2026-10-12' // 「今天」钉死（与 d07 同一天）：出生按 YYYY-MM-DD 字典序判，不取本机时钟
const rank = { [R_VIEWER]: 1, [R_EDITOR]: 2, [R_OWNER]: 3 }

// ---------- 目录：与 d07 同一份声明、同一套字段（code/name/svc/minRole/bornAt/rollout）----------
const REG = [
  { code: 'home.summary', name: '首页摘要', svc: 'homeos-core', minRole: R_VIEWER, bornAt: '2026-03-01', rollout: null },
  { code: 'finance.ledger', name: '账本', svc: 'finance-svc', minRole: R_VIEWER, bornAt: '2026-03-01', rollout: null },
  { code: 'finance.budget', name: '预算', svc: 'finance-svc', minRole: R_EDITOR, bornAt: '2026-04-15', rollout: null },
  { code: 'family.settings', name: '家庭与成员设置', svc: 'member-svc', minRole: R_OWNER, bornAt: '2026-04-01', rollout: null },
  { code: 'finance.report', name: '报表', svc: 'analytics-svc', minRole: R_VIEWER, bornAt: '2026-05-10', rollout: null },
  { code: 'finance.export', name: '导出 CSV', svc: 'finance-svc', minRole: R_OWNER, bornAt: '2026-06-01', rollout: null },
  { code: 'notify.center', name: '提醒中心', svc: 'notify-svc', minRole: R_VIEWER, bornAt: '2026-06-20', rollout: null },
  { code: 'activity.feed', name: '动态流', svc: 'activity-svc', minRole: R_VIEWER, bornAt: '2026-07-05', rollout: null },
  { code: 'homeos.panel', name: '设备面板', svc: 'iot-svc', minRole: R_EDITOR, bornAt: '2026-08-01', rollout: [FAM_B] },
  { code: 'insight.cashflow', name: '现金流透视', svc: 'analytics-svc', minRole: R_VIEWER, bornAt: '2026-10-01', rollout: [FAM_B] },
  { code: 'lab.recipe', name: '实验室·菜谱', svc: 'lab-svc', minRole: R_EDITOR, bornAt: '2026-11-20', rollout: null },
]
const regBy = Object.fromEntries(REG.map((f) => [f.code, f]))

// ---------- family_face：家庭级开关（与 d07 同一份行数据；行前缀 "!" = enabled=false，没列的 code = 本家没这行）----------
const FF_ROWS = {
  [FAM_A]: ['home.summary', 'finance.ledger', 'finance.budget', 'family.settings', 'finance.report', '!finance.export', 'notify.center', 'activity.feed', 'homeos.panel', 'lab.recipe', 'finance.wallet.v1'],
  [FAM_B]: ['home.summary', 'finance.ledger', '!finance.budget', 'finance.report', 'finance.export', '!notify.center', 'activity.feed', 'homeos.panel', '!lab.recipe', 'insight.cashflow'],
}
const LIMIT_CENTS = { [`${FAM_A}|finance.budget`]: 25000000, [`${FAM_B}|finance.budget`]: 30000000, [`${FAM_A}|finance.wallet.v1`]: 180000 } // 金额口径：*_cents 整数

// ---------- 客户端 bundle 里手抄那份（d07 的 TS 源码原文）：真逐行解析，反例「照旧」打的就是这份 ----------
const TS_SRC = `export const FACE_CATALOG: Face[] = [
  { code: "home.summary", name: "首页摘要", service: "homeos-core", minRole: "viewer", born: true },
  { code: "finance.ledger", name: "账本", service: "finance-svc", minRole: "viewer", born: true },
  { code: "finance.budget", name: "预算看板", service: "finance-svc", minRole: "editor", born: true },
  { code: "finance.report", name: "报表", service: "analytics-svc", minRole: "viewer", born: true },
  { code: "finance.export", name: "导出 CSV", service: "finance-svc", minRole: "viewer", born: true },
  { code: "notify.center", name: "提醒中心", service: "notification-svc", minRole: "viewer", born: true },
  { code: "activity.feed", name: "动态流", service: "activity-svc", minRole: "viewer", born: true },
  { code: "family.settings", name: "家庭与成员设置", service: "member-svc", minRole: "owner", born: true },
  { code: "homeos.panel", name: "设备面板", service: "iot-svc", minRole: "editor", born: true },
  { code: "lab.recipe", name: "实验室·菜谱", service: "lab-svc", minRole: "editor", born: true },
  { code: "finance.wallet.v1", name: "钱包", service: "finance-svc", minRole: "viewer", born: true },
];`
const bundle = []
for (const ln of TS_SRC.split('\n')) {
  const i = ln.indexOf('{ code: "')
  if (i < 0) continue
  const m = {}
  for (const g of ln.slice(i).matchAll(/(\w+)\s*:\s*("[^"]*"|[A-Za-z]+)/g)) m[g[1]] = g[2].replace(/"/g, '')
  bundle.push(m.code)
}

// ---------- 会话：family_id / role 只从会话解出（live=="off" = token 过期，连 family_id 都解不出来）----------
const ACCTS = {
  'u-ann': { uid: 'u-ann', fam: FAM_A, role: R_OWNER, live: 'on', paramTrusted: false },
  'u-bob': { uid: 'u-bob', fam: FAM_A, role: R_EDITOR, live: 'on', paramTrusted: false },
  'u-cara': { uid: 'u-cara', fam: FAM_A, role: R_VIEWER, live: 'on', paramTrusted: false },
  'u-faye': { uid: 'u-faye', fam: FAM_B, role: R_OWNER, live: 'on', paramTrusted: false },
  'u-gus': { uid: 'u-gus', fam: FAM_B, role: R_VIEWER, live: 'on', paramTrusted: false },
  'u-zed': { uid: 'u-zed', fam: FAM_A, role: R_EDITOR, live: 'off', paramTrusted: false },
}

const trimRow = (s) => s.replace(/^!/, '')
const enabledIn = (fam) => new Set((FF_ROWS[fam] || []).filter((s) => !s.startsWith('!')).map(trimRow))
const hasRow = (fam, code) => (FF_ROWS[fam] || []).map(trimRow).includes(code)
const bornFor = (f, fam) => f.bornAt <= TODAY && (!f.rollout || inXs(f.rollout, fam))
// 与服务端同一口径的四处合成（d07/d08）：目录 ∩ 本家已启用 ∩ 已出生，再叠角色可见；清单之外 = 对客户端「不存在」
const srvFull = (fam) => REG.filter((f) => enabledIn(fam).has(f.code) && bornFor(f, fam)).map((f) => f.code)
const srvList = (fam, role) => srvFull(fam).filter((c) => rank[role] >= rank[regBy[c].minRole])

// ---------- 假 fetch：计数器真长在发请求的路上 —— fakeFetch 每被调一次才 +1、才记一条 URL ----------
const mkHttp = () => {
  const h = { n: 0, log: [] }
  h.fetch = (uid, url) => {
    h.n++
    const r = { url, uid, ...serve(uid, url) }
    h.log.push(r)
    return r
  }
  return h
}
// 路由判定顺序与 d07 的 get() 一一对应：认证 → 在不在目录 → 在不在本家合成清单 → 角色。
// ❌ 版（paramTrusted=true）只演示「信 query 参数」这一种事故形状，其余路径同 ✅。
function serve(uid, url) {
  const a = ACCTS[uid]
  if (!a || a.live !== 'on') return { status: 401, body: '未登录：family_id 都解不出来，一次查询都不发' }
  const q = url.includes('?') ? url.slice(url.indexOf('?') + 1).split('&') : []
  const pget = (k) => { const p = q.find((s) => s.startsWith(k + '=')); return p ? p.split('=')[1] : '' }
  const path = url.includes('?') ? url.slice(0, url.indexOf('?')) : url
  if (path === '/api/v1/faces') {
    const fam = a.paramTrusted ? pget('family_id') || a.fam : a.fam
    const role = a.paramTrusted ? pget('role') || a.role : a.role
    const codes = srvList(fam, role)
    return { status: 200, codes, body: `清单 ${codes.length} 个（family_id=${fam}、role=${role} 从${a.paramTrusted ? '❌ query 参数' : '✅ 会话'}取）` }
  }
  const code = path.split('/').pop()
  if (!regBy[code]) return { status: 400, body: `非法 code ${code}：不在目录 ${REG.length} 个 code 里，合法清单=[${join(REG.map((f) => f.code))}]` }
  if (!srvFull(a.fam).includes(code)) {
    const why = hasRow(a.fam, code) ? (enabledIn(a.fam).has(code) ? (regBy[code].bornAt > TODAY ? `未到出生日（${regBy[code].bornAt}）` : `不在本家出生批次（rollout=${join(regBy[code].rollout)}）`) : '本家已停用（enabled=false）') : '本家没有这一行'
    return { status: 404, body: `面 ${code} 对 ${a.fam} 不存在（${why}）—— 与「不是你的家」同码同体，探测者分不出` }
  }
  if (rank[a.role] < rank[regBy[code].minRole]) return { status: 403, body: `本家庭内角色 ${a.role} 不足（${code} 需 ${regBy[code].minRole} 及以上）` }
  return { status: 200, body: `${code}：${regBy[code].name}（依赖 ${regBy[code].svc}）已下发，monthly_limit_cents=${LIMIT_CENTS[`${a.fam}|${code}`] ?? 0}` }
}
const diff = (xs, ys) => xs.filter((x) => !ys.includes(x))

// ============ 开跑 ============
H(`1. 场景：目录 ${REG.length} 个面（与 d07 同一份声明），今天=${TODAY}；会话 u-cara = ${FAM_A}/${R_VIEWER}`)
const cara = ACCTS['u-cara']
const list = srvList(cara.fam, cara.role)
L(`  服务端合成清单（目录 ∩ 本家已启用 ∩ 已出生 ∩ 角色可见）共 ${list.length} 个：${join(list)}`)
for (const f of REG) {
  const why = []
  if (!enabledIn(FAM_A).has(f.code)) why.push(hasRow(FAM_A, f.code) ? '本家已停用（enabled=false）' : '本家没有这一行')
  if (!bornFor(f, FAM_A)) why.push(f.bornAt > TODAY ? `未到出生日（${f.bornAt}）` : `不在本家出生批次（rollout=${join(f.rollout)}）`)
  if (rank[cara.role] < rank[f.minRole]) why.push(`角色不足（需 ${f.minRole}）`)
  L(`  ${mark[list.includes(f.code)]} ${f.code.padEnd(17)} ${f.name.padEnd(9)} min_role=${f.minRole.padEnd(7)} born_at=${f.bornAt} rollout=${join(f.rollout)}  ${why.length ? '← 清单外原因：' + why.join('、') : '（在清单内）'}`)
}

H('2. 假 fetch：计数器和 URL 日志都写在 fakeFetch() 内部，客户端没有绕过它改计数的入口')
L(`  本机没有浏览器也没有网络，「零请求」这种否定命题只能这样证：把发请求这个动作收口到一个自己写的`)
L(`  fakeFetch 上，请求数由它当场累加、请求 URL 由它当场登记 —— 正例/反例各挂一个独立计数器（${mkHttp().n}/${mkHttp().n} 起步），`)
L(`  服务端路由 serve() 用与 d07 同口径的判定：401 未登录 / 400 非法 code 给合法清单 / 404 清单外 / 403 角色不足 / 200 命中。`)

H('3. ✅ 正例：只请求合成清单里的面')
const httpOK = mkHttp()
for (const code of list) {
  const r = httpOK.fetch('u-cara', `/api/v1/faces/${code}`)
  L(`  GET /api/v1/faces/${code.padEnd(15)} → ${r.status}  ${r.body}`)
}
const outOfListOK = diff(httpOK.log.map((r) => r.url.split('/').pop()), list)
const okPos = httpOK.n === list.length && httpOK.log.every((r) => r.status === 200) && outOfListOK.length === 0
L(`  请求数 ${httpOK.n} == 清单长度 ${list.length}？${mark[httpOK.n === list.length]}；其中非 200 的 ${httpOK.log.filter((r) => r.status !== 200).length} 个；清单之外被碰到的 code：${join(outOfListOK)}（${outOfListOK.length} 个）→ 正例判定 ${mark[okPos]}。`)

H('4. ❌ 反例：照旧按 bundle 写死那份清单，把 lab/homeos 里未启用的面也打一遍')
const httpBad = mkHttp()
for (const code of bundle) httpBad.fetch('u-cara', `/api/v1/faces/${code}`)
const over = httpBad.log.filter((r) => !list.includes(r.url.split('/').pop()))
const cS = (n) => over.filter((r) => r.status === n).length
L(`  bundle 解析出 ${bundle.length} 个 code 全打 → 总请求 ${httpBad.n} 个，其中被多打 ${over.length} 个：`)
for (const r of over) L(`    GET ${r.url} → ${r.status}  ${r.body}`)
