// DryRun 用的行形状（列名即真表列名）
type ffRec struct {
	FamilyID, Code, UpdatedBy string
	Enabled                   bool
	MonthlyLimitCents         int64
	Version                   int64
}
type auRec struct {
	Actor, FamilyID, Code, ClientRequestID string
	ChangedAt                              time.Time
	OldEnabled, NewEnabled                 bool
	OldVersion, NewVersion                 int64
}
type irRec struct {
	ClientRequestID, FamilyID, Code string
	ResponseStatus                  int64
}

func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func join(xs []string) string {
	return map[bool]string{true: strings.Join(xs, ", "), false: "——"}[len(xs) > 0]
}
func inXs(xs []string, x string) bool {
	return strings.Contains("|"+strings.Join(xs, "|")+"|", "|"+x+"|")
}
func abs64(v int64) int64 { return map[bool]int64{true: -v, false: v}[v < 0] }
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs64(c)/100, abs64(c)%100)
}
func codes() []string {
	var o []string
	for _, f := range reg {
		o = append(o, f.code)
	}
	return o
}
func key(fam, code string) string { return fam + "|" + code }
func hasRow(fam, code string) bool {
	_, ok := rows[key(fam, code)]
	return ok
}
func ver(fam, code string) int64 {
	if r, ok := rows[key(fam, code)]; ok {
		return r.version
	}
	return -1
}
func famRowCount(fam string) int {
	n := 0
	for _, k := range rowKeys {
		n += yes[strings.HasPrefix(k, fam+"|")]
	}
	return n
}
func famEnabledCount(fam string) int {
	n := 0
	for _, k := range rowKeys {
		if strings.HasPrefix(k, fam+"|") {
			n += yes[rows[k].enabled]
		}
	}
	return n
}

// ---------- 与服务端 d07/d08 同一口径的四处合成（目录 ∩ 本家已启用 ∩ 已出生，再叠角色可见）----------
func isReg(c string) bool { _, ok := regBy[c]; return ok }
func isBorn(f face) bool  { return f.bornAt <= today }
func bornFor(f face, fam string) bool {
	return isBorn(f) && (len(f.rollout) == 0 || inXs(f.rollout, fam))
}
func enabledNow(fam, code string) bool { return hasRow(fam, code) && rows[key(fam, code)].enabled }
func srvFull(fam string) []string {
	var o []string
	for _, f := range reg {
		if enabledNow(fam, f.code) && bornFor(f, fam) {
			o = append(o, f.code)
		}
	}
	return o
}
func srvList(fam, role string) []string {
	var o []string
	for _, c := range srvFull(fam) {
		if rank[role] >= rank[regBy[c].minRole] {
			o = append(o, c)
		}
	}
	return o
}
func diffXs(xs, ys []string) []string {
	var o []string
	for _, x := range xs {
		if !inXs(ys, x) {
			o = append(o, x)
		}
	}
	return o
}

// ---------- 写接口：判定顺序定死 —— 401 认证 → 400 形状 → 幂等命中 → 404 无行 → 403 角色 → 409 版本 → 落库 ----------
func put(uid, code string, want bool, crid string, expVer int64, newLimit *int64) resp {
	return putFam(uid, "", code, want, crid, expVer, newLimit, true)
}
func putFam(uid, famOverride, code string, want bool, crid string, expVer int64, newLimit *int64, strict bool) resp {
	a := who(uid)
	if a.live != "on" || a.fam == "" {
		return resp{401, "未登录：family_id 都解不出来，一次写入都不发"}
	}
	fam := a.fam // ✅ 路径永远只取会话；famOverride 只存在于 ❌ 反证（= 服务端信了 query 参数）
	if famOverride != "" {
		fam = famOverride
	}
	if !isReg(code) {
		if strict {
			return resp{400, fmt.Sprintf("非法 code %q：不在目录 %d 个 code 里，绝不猜、绝不回落。合法 code 清单=[%s]", code, len(reg), join(codes()))}
		}
		guess := srvList(fam, a.role)[0]
		code = guess // ❌ 回落版：猜清单头一个面写下去，后面的链路照常走（这一格只活在反证里）
	}
	if r, ok := idemResp[crid]; ok && crid != "" {
		return r // 幂等命中：原样返回首次那条，一行都不写
	}
	r0, ok := rows[key(fam, code)]
	if !ok {
		return resp{404, fmt.Sprintf("开关行 %s|%s 不存在（没这行/没开启记录，与「不是你的家」同码同体）", fam, code)}
	}
	if rank[a.role] < rank[regBy[code].minRole] {
		return resp{403, fmt.Sprintf("本家庭内角色 %s 不足（%s 的开关需 %s 及以上）", a.role, code, regBy[code].minRole)}
	}
	if crid != "" && expVer != r0.version {
		return resp{409, fmt.Sprintf("乐观锁冲突：expected_version=%d ≠ 当前 version=%d（上一次落库是 %s 把它改成 enabled=%v）；你这条想写的 %v→%v 前提已过期，重读后带新 version 再来",
			expVer, r0.version, r0.updatedBy, r0.enabled, r0.enabled, want)}
	}
	oldEn, oldVer := r0.enabled, r0.version
	r0.enabled, r0.version, r0.updatedBy = want, r0.version+1, a.uid
	if newLimit != nil {
		r0.limitCents = *newLimit
	}
	audits = append(audits, auditRow{a.uid, fam, code, crid, now, oldEn, want, oldVer, r0.version})
	applied++
	msg := fmt.Sprintf("%s|%s enabled %v→%v，version %d→%d，monthly_limit_cents=%d，operator=%s，client_request_id=%s",
		fam, code, oldEn, want, oldVer, r0.version, r0.limitCents, a.uid, orNone(crid))
	if crid != "" {
		idemResp[crid] = resp{200, msg}
	}
	return resp{200, msg}
}
func orNone(s string) string { return map[bool]string{true: s, false: "（没带！）"}[s != ""] }

// putNoVer：❌ 无乐观锁版（last-write-wins）—— 不比对 version，直接落
func putNoVer(uid, code string, want bool) resp {
	a, r0 := who(uid), rows[key(who(uid).fam, code)]
	oldEn, oldVer := r0.enabled, r0.version
	r0.enabled, r0.version, r0.updatedBy = want, r0.version+1, a.uid
	audits = append(audits, auditRow{a.uid, a.fam, code, "", now, oldEn, want, oldVer, r0.version})
	applied++
	return resp{200, fmt.Sprintf("%s|%s enabled %v→%v version %d→%d（没有 version 检查，照单全收）", a.fam, code, oldEn, want, oldVer, r0.version)}
}

// putBatch：先整批预检（400/404/403/409 任一命中 → 一条都不落），全过才逐条落库（= 同事务，错一起回滚）
func putBatch(uid string, items []bItem, crid string) (resp, int) {
	a := who(uid)
	if a.live != "on" {
		return resp{401, "未登录：整批 0 条落库"}, 0
	}
	for i, it := range items {
		if !isReg(it.code) {
			return resp{400, fmt.Sprintf("第 %d/%d 条 code %q 非法：不猜不回落，合法 code 清单=[%s] —— 整批预检失败，0 条落库", i+1, len(items), it.code, join(codes()))}, 0
		}
		r0, ok := rows[key(a.fam, it.code)]
		if !ok {
			return resp{404, fmt.Sprintf("第 %d/%d 条 %s|%s 无行 —— 整批预检失败，0 条落库", i+1, len(items), a.fam, it.code)}, 0
		}
		if rank[a.role] < rank[regBy[it.code].minRole] {
			return resp{403, fmt.Sprintf("第 %d/%d 条角色不足 —— 整批预检失败，0 条落库", i+1, len(items))}, 0
		}
		if it.expVer != r0.version {
			return resp{409, fmt.Sprintf("第 %d/%d 条 %s：expected_version=%d ≠ 当前 version=%d（库 enabled=%v；你写的 old/new=%v→%v）—— 整批回滚，0 条落库",
				i+1, len(items), it.code, it.expVer, r0.version, r0.enabled, r0.enabled, it.want)}, 0
		}
	}
	n := 0
	for _, it := range items {
		if put(uid, it.code, it.want, crid+"#"+it.code, it.expVer, it.newLimit).st == 200 {
			n++
		}
	}
	return resp{200, fmt.Sprintf("整批预检全过，%d 条同事务落库（每条各配子幂等键 %s#code）", n, crid)}, n
}

// putBatchNaive：❌ 非原子版 —— 逐条打，打到第一条失败就中止，前面已落库的收不回来
func putBatchNaive(uid string, items []bItem) (resp, int) {
	n := 0
	for i, it := range items {
		r := put(uid, it.code, it.want, fmt.Sprintf("naive%d#%s", i+1, it.code), it.expVer, it.newLimit)
		if r.st != 200 {
			return resp{r.st, fmt.Sprintf("第 %d/%d 条中止：%s —— 但前面 %d 条已经真落库、回不来了", n+1, len(items), r.msg, n)}, n
		}
		n++
	}
	return resp{200, "全成了（这次没踩到失败而已，不是保证）"}, n
}

// ---------- DryRun：一次写操作在真环境要跑的 SQL（现场生成、只打印不落库）----------
func drySel(fam string) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("family_face").Where("family_id = ? AND deleted_at IS NULL", fam).Order("code").Find(&[]ffRec{})
	})
}
func dryUpd(fam, code string, want bool, curVer, newLimit int64, by string) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("family_face").Where("family_id = ? AND code = ? AND version = ?", fam, code, curVer).
			Updates(map[string]any{"enabled": want, "monthly_limit_cents": newLimit, "updated_by": by, "version": curVer + 1})
	})
}
func dryAudit(a auditRow) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("face_toggle_audit").Create(&auRec{Actor: a.actor, FamilyID: a.fam, Code: a.code, ClientRequestID: a.crid,
			ChangedAt: a.at, OldEnabled: a.oldEn, NewEnabled: a.newEn, OldVersion: a.oldVer, NewVersion: a.newVer})
	})
}
func dryIdem(crid, fam, code string) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("client_request_id").Create(&irRec{ClientRequestID: crid, FamilyID: fam, Code: code, ResponseStatus: 200})
	})
}

// whyOut：code 对 fam 而言为什么不在合成清单里 —— 逐层现查（没行 / 没开 / 未出生），不写死在文案里
func whyOut(fam, code string) string {
	if !hasRow(fam, code) {
		return "本家没写行"
	}
	if !rows[key(fam, code)].enabled {
		return "本家开关 enabled=false"
	}
	f := regBy[code]
	if f.bornAt > today {
		return fmt.Sprintf("还没到出生日（born_at=%s > %s）", f.bornAt, today)
	}
	return fmt.Sprintf("不在本家出生批次（rollout=%s）", join(f.rollout))
}

