func hdr(s string) { fmt.Printf("\n===== %s =====\n", s) }
func join(xs []string) string {
	return map[bool]string{true: strings.Join(xs, ", "), false: "——"}[len(xs) > 0]
}
func inXs(xs []string, x string) bool {
	return strings.Contains("|"+strings.Join(xs, "|")+"|", "|"+x+"|")
}
func bit(c string) uint32 { return map[bool]uint32{true: 1 << uint(by[c]-1), false: 0}[by[c] > 0] }
func isReg(c string) bool { _, ok := regBy[c]; return ok }
func bornFor(f face, fam string) bool {
	return f.bornAt <= today && (len(f.rollout) == 0 || inXs(f.rollout, fam))
}
func msk(b bool, c string) uint32       { return map[bool]uint32{true: bit(c), false: 0}[b] }
func cnt(mk uint32) int                 { return len(pick(mk)) }
func nm(mk uint32) string               { return join(pick(mk)) }
func code(a acct, c string) int         { n, _ := gate(a, c, 0); return n }
func gm(a acct, c string, mode int) int { n, _ := gate(a, c, mode); return n } // mode 1=403 误标 404；2=404 误标 403
func pick(mk uint32) (o []string) {
	for _, c := range order {
		if mk&bit(c) != 0 {
			o = append(o, c)
		}
	}
	return
}
func owners(fam string) (o []string) {
	for _, u := range []string{"u-ann", "u-faye"} {
		if accts[u].fam == fam && accts[u].role == rOwner {
			o = append(o, u)
		}
	}
	return
}
func reason(c int, f face, fam string) string {
	if c == 200 {
		return "—"
	}
	return fmt.Sprintf("权限不足：本家已开但需 %s·找 %s 开", f.minRole, join(owners(fam)))
}

// build：把目录 / family_face / 出生批次摊成位掩码，之后全是位运算。只 OR，与 map 遍历序无关，故两次跑字节一致；打印过 pick() 回到声明序。
func build() {
	for _, f := range reg {
		regBy[f.code] = f
		order = append(order, f.code)
	}
	for i, c := range order {
		by[c] = i + 1
	}
	for _, f := range reg {
		regM |= bit(f.code)
	}
	for fam, xs := range ffRows {
		for _, s := range xs {
			if !strings.HasPrefix(s, "!") {
				enM[fam] |= bit(strings.TrimPrefix(s, "!"))
			}
		}
	}
	for _, fam := range fams {
		for _, f := range reg {
			bornM[fam] |= msk(bornFor(f, fam), f.code)
		}
	}
	for _, role := range roles {
		for _, f := range reg {
			roleM[role] |= msk(rank[role] >= rank[f.minRole], f.code)
		}
	}
}

// 三层服务端合成（角色还没进来）；再叠角色可见＝d08 的四层清单。
func srvFull(fam string) uint32       { return regM & enM[fam] & bornM[fam] }
func srvList(fam, role string) uint32 { return srvFull(fam) & roleM[role] }

// gate 是「读一个面」的唯一判定，顺序写死：401 → 400 形状 → 404 归属/存在 → 403 角色 → 200。mode 只用来现算反例，真实路径是 mode 0。
func gate(a acct, code string, mode int) (int, string) {
	if a.live != "on" || a.fam == "" {
		return 401, "未登录：family_id 都解不出来，一次 family_face 查询都不发（lookups 保持 0）"
	}
	if !isReg(code) {
		return 400, fmt.Sprintf("非法 code %q：不在目录 %d 个 code 里。合法形状＝[%s]，不猜最像的、不回落默认面", code, len(reg), nm(regM))
	}
	lookups++ // 认证通过才会读 family_face / 成员表
	if srvFull(a.fam)&bit(code) == 0 {
		if mode == 2 {
			return 403, fmt.Sprintf("❌ 反例：面 %s 对 %s 不存在却回 403——向探测者承认「这面真的存在，只是你家没开」", code, a.fam)
		}
		return 404, fmt.Sprintf("面 %s 对 %s 不存在（未启用/未出生/不在本家批次/不是你家）——与跨家庭 404 同码同体", code, a.fam)
	}
	if rank[a.role] < rank[regBy[code].minRole] {
		if mode == 1 {
			return 404, fmt.Sprintf("❌ 反例：%s 本家明明开着 %s、只是角色不足，却回 404——客户端会把这个面当成不存在悄悄抹掉", a.fam, code)
		}
		return 403, fmt.Sprintf("本家庭 %s 内角色 %s 不足（读 %s 需 %s 及以上）：归属与身份都成立，只有权限不成立", a.fam, a.role, code, regBy[code].minRole)
	}
	return 200, fmt.Sprintf("%s（%s·依赖 %s）已下发：%s 可进，monthly_limit_cents=%d", code, regBy[code].name, regBy[code].svc, a.role, limit[a.fam+"|"+code])
}

func cellOf(fam, role, c string) string {
	if srvFull(fam)&bit(c) == 0 {
		return "404 不在本家"
	}
	if rank[role] < rank[regBy[c].minRole] {
		return "403 角色不足"
	}
	return "200 可进"
}

type ffRow struct{ Code string }

// selSQL/updSQL：本机无 PostgreSQL，GORM DryRun 只出文本不落库（固定 NowFunc 保两次跑字节一致）。
func selSQL(fam string) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("family_face").Where("family_id = ? AND deleted_at IS NULL", fam).Order("code").Find(&[]ffRow{})
	})
}
func updSQL(fam, code string, on bool) string {
	return gdb.ToSQL(func(t *gorm.DB) *gorm.DB {
		return t.Table("family_face").Where("family_id = ? AND code = ? AND version = ?", fam, code, 3).Updates(map[string]any{"enabled": on, "updated_by": "u-ann", "version": 4})
	})
}

func main() {
	build()
	ann, bob, cara := accts["u-ann"], accts["u-bob"], accts["u-cara"]
	gus, zed := accts["u-gus"], accts["u-zed"]

	hdr(fmt.Sprintf("1. 场景：路由表→最低角色映射（目录声明序 %d 个）＋会话三档（今天=%s）", len(reg), today))
	fmt.Printf("  %-16s %-15s %-7s %-16s %-18s %s\n", "code", "名称", "min_role", "route(新)", "icon(新)", "启用A/B 出生A/B")
	for _, f := range reg {
		fmt.Printf("  %-16s %-15s %-7s %-16s %-18s %d/%d  %d/%d\n", f.code, f.name, f.minRole, route[f.code], icon[f.code], yes[enM[famA]&bit(f.code) != 0], yes[enM[famB]&bit(f.code) != 0], yes[bornM[famA]&bit(f.code) != 0], yes[bornM[famB]&bit(f.code) != 0])
	}
	fmt.Printf("  三档 rank：viewer=%d editor=%d owner=%d；中间件只认这张表的 min_role，前端传来的 role/is_admin 一概不用。\n", rank[rViewer], rank[rEditor], rank[rOwner])
	fmt.Printf("  fam-A 可达层(srvFull, 含角色不足)=%d 个、授权层(srvList viewer)=%d 个；两层之差就是「本家已开但你没权」那一档：%s。\n", cnt(srvFull(famA)), cnt(srvList(famA, rViewer)), nm(srvFull(famA)&^roleM[rViewer]))
	fmt.Printf("  角色判定取数（family_id 恒在 WHERE 里、只从会话取）：\n    %s\n", selSQL(bob.fam))

	hdr("2. 三个码各自用对：对照表（每格现场算，非写死）")
	scs := []struct {
		a    acct
		code string
		want int
		desc string
	}{
		{zed, "home.summary", 401, "未登录(token 过期)打任意面"},
		{cara, "finance.export", 404, "viewer@A 打本家没启用的面"},
