		{gus, "finance.export", 403, "viewer@B 打本家已开但要 owner 的面"},
		{cara, "finance.ledger", 200, "viewer@A 打 viewer 面"},
		{ann, "family.settings", 200, "owner@A 打 owner 面"},
	}
	fmt.Printf("  %-30s %-18s %-6s %-6s %s\n", "请求场景", "会话", "期望", "实算", "判定")
	ok2 := 0
	for _, s := range scs {
		got := code(s.a, s.code)
		ok2 += yes[got == s.want]
