// synth 是全程序唯一的合成口：目录 ∩ 已出生 ∩ 已启用 ∩ 依赖就绪 ∩ 未熔断 ∩ 角色可见，一次算完，顺序＝声明序。
// 返回体里不带 stage／svc／开关行／熔断表——客户端不是「被禁止」重切，而是「拿不到原料」。
var sites = map[string]int{}

func synth(fam, uid, where string) []Item {
	sites[where]++
	_, role := member(uid)
	o := []Item{}
	for _, f := range dir {
		it := Item{code: f.code, name: f.name, icon: f.icon, route: f.route, minRole: f.rd}
		switch {
		case f.stage == "unborn":
			it.reason = "即将上线"
		case !en[fam][f.code]:
			it.reason = "未启用"
		case !ready[f.svc][fam]:
			it.reason = "依赖未就绪"
		case degraded[fam+"|"+f.code]:
			it.reason = "暂不可用"
		case rank[role] < need[f.rd]:
			it.reason = "权限不足：最低 " + f.rd
		default:
			it.available = true
		}
		o = append(o, it)
	}
	return o
}

// 清单的字节序列化：ETag 就对它取 sha256 —— 所以「顺序」和 available／reason 都进了指纹。
func serial(items []Item) string {
	o := []string{}
	for _, it := range items {
		o = append(o, fmt.Sprintf("%s|%s|%t|%s|%s|%s|%s", it.code, it.name, it.available, it.reason, it.icon, it.route, it.minRole))
	}
	return strings.Join(o, "\n")
}
func etag(items []Item) string {
	h := sha256.Sum256([]byte(serial(items)))
	return `"` + h12(h[:8]) + `"`
}
func codesOf(items []Item) string {
	o := []string{}
	for _, it := range items {
		o = append(o, it.code)
	}
	return strings.Join(o, ",")
}
func declCodes() string { return codesOf(synthDir()) }
func synthDir() []Item {
	o := []Item{}
	for _, f := range dir {
		o = append(o, Item{code: f.code})
	}
	return o
}
func availOf(items []Item) int {
	n := 0
	for _, it := range items {
		n += yes[it.available]
	}
	return n
}
func orDash(s string) string { return map[bool]string{true: s, false: "—"}[s != ""] }
func cntPre(items []Item, p string) int {
	n := 0
	for _, it := range items {
		if strings.HasPrefix(it.reason, p) {
			n++
		}
	}
	return n
}

// sample：Go 运行时的 map 遍历序钉不死（钉死了就验不出「漂」），这里用一条固定种子的线性同余序列把两个采样复现成可比字节。
func sample(sd uint64) string {
	keys, out := []string{}, []string{}
	for _, f := range dir {
		keys = append(keys, f.code)
	}
	for len(keys) > 0 {
		sd = sd*6364136223846793005 + 1442695040888963407
		i := int(sd>>33) % len(keys)
		out = append(out, keys[i])
		keys = append(keys[:i], keys[i+1:]...)
	}
	return strings.Join(out, ",")
}

// ---------- 本机无 PostgreSQL：GORM DryRun 生成真实 Postgres 语句（DisableAutomaticPing + 固定 NowFunc），只出文本不落库 ----------
type ModRow struct {
	ID, FamilyID, FaceCode, UpdatedBy string
	Enabled                           bool
	MonthBudgetCents                  int64
	Version                           int
	DeletedAt                         gorm.DeletedAt
}
type CacheRow struct {
	ID, Scope, FamilyID string
	Pver                int
}

func (ModRow) TableName() string   { return "homeos_family_module" }
func (CacheRow) TableName() string { return "homeos_cache_version" }
func dryDB() *gorm.DB {
	db, e := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_homeos:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return now }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if e != nil {
		panic(e)
	}
	return db
}
func listSQL(db *gorm.DB) string { // 四处合成的取数：开关行 join 成员行，family_id 两边都在 WHERE 里，顺序由 ORDER BY 钉死
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Table("homeos_family_module AS m").Select("m.face_code, m.enabled, m.month_budget_cents, m.version, f.role").Joins("JOIN homeos_family_member AS f ON f.family_id = m.family_id").Where("m.family_id = ? AND f.user_id = ? AND m.deleted_at IS NULL AND f.deleted_at IS NULL", famA, "u-bob").Order("m.face_code ASC").Find(&[]ModRow{})
	})
}
func pverSQL(db *gorm.DB) string { // homeos.family.module.updated 落这一行：pver+1，module 缓存随之失效
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&CacheRow{}).Where("scope = ? AND family_id = ?", "module", famA).Update("pver", gorm.Expr("pver + 1"))
	})
}
func noOrderSQL(db *gorm.DB) string { // ❌ 反例：没有 ORDER BY，行序交给 Postgres 的执行计划
	return db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Where("family_id = ?", famA).Find(&[]ModRow{})
	})
}

