// mapDrift / mapTwoOrders：真的遍历 Go map 200 次，只回答「有没有漂」，不把漂出来的字节写进 stdout。
func mapDrift() bool {
	m := mapSigSet()
	for k := range m {
		if k != declCodes() {
			return true
		}
	}
	return false
}
func mapTwoOrders() bool {
	return len(mapSigSet()) > 1
}
func mapSigSet() map[string]bool {
	m := map[string]bool{}
	for _, f := range dir {
		m[f.code] = true
	}
	seen := map[string]bool{}
	for i := 0; i < 200; i++ {
		o := []string{}
		for k := range m {
			o = append(o, k)
		}
		seen[strings.Join(o, ",")] = true
	}
	return seen
}
func sha(b []byte) []byte {
	h := sha256.Sum256(b)
	return h[:]
}
func siteNames() string {
	k := []string{}
	for x := range sites {
		k = append(k, x)
	}
	sort.Strings(k)
	return strings.Join(k, "、")
}

// clientRecut ❌ 反例：客户端按 reason 字符串自己再过滤一遍——它猜不到 stage，也猜不到开关行与熔断表。
func clientRecut(items []Item) (int, []Item) {
	sites["client.recut"]++
	keep, cut := []Item{}, 0
	for _, it := range items {
		if !it.available {
			cut++
		} else {
			keep = append(keep, it)
		}
	}
	return cut, keep
}
func countReqs(items []Item) map[string]int {
	r := map[string]int{}
	for _, it := range items {
		if it.available { // 正解：只有 available=true 的面才配一次首屏请求
			r[it.code]++
		}
	}
	return r
}
func sum(r map[string]int) (n int) {
	for _, v := range r {
		n += v
	}
	return
}
func reqLine(r map[string]int) string {
	o := []string{}
	for _, f := range dir {
		o = append(o, fmt.Sprintf("%s=%d", f.code, r[f.code]))
	}
	return strings.Join(o, " ")
}

// allZero：判据②的机器验法——清单里每一个 available=false 的面，请求计数都必须是 0。
func allZero(items []Item) bool {
	r := countReqs(items)
	for _, it := range items {
		if !it.available && r[it.code] != 0 {
			return false
		}
	}
	return true
}
func unreadOf(fam string) int {
	n := 0
	for _, x := range notes {
		if x.fam == fam && x.code == "notification" {
			n++
		}
	}
	return n
}
func notesFor(fam, code string) int {
	n := 0
	for _, x := range notes {
		if x.fam == fam && x.code == code {
			n++
		}
	}
	return n
}

// 三个消费出口各自独立取数一遍：导航角标按 (家庭,面) 数通知行，首屏卡片走 faceOf 拿目录再数，设置行从清单的 available 出发。
// 它们相等不是「写了三遍同一个函数」的自证，而是三条不同代码路径算到同一个数——这才是判据③要的「只有一个来源」。
func navBadge(fam string) int {
	n := 0
	for _, x := range notes {
		if x.fam == fam && x.code == "notification" {
			n++
		}
	}
	return n
}
func homeCard(fam string) int {
	n := 0
	for _, x := range notes {
		f := faceOf(x.code)
		if f != nil && x.fam == fam && f.code == "notification" {
			n++
		}
	}
	return n
}
func settingsRow(fam string) int {
	n := 0
	for _, it := range synth(fam, "u-ann", "homeos.synth") {
		if it.available && it.code == "notification" {
			n = notesFor(fam, it.code)
		}
	}
	return n
}
