func hdr(s string)                                                                            { fmt.Printf("\n===== %s =====\n", s) }
func at(t time.Time) string                                                                   { return t.Format("2006-01-02 15:04:05") }
func money(c int64) string                                                                    { return fmt.Sprintf("%d.%02d", c/100, abs(c)%100) }
func abs(v int64) int64                                                                       { return map[bool]int64{true: -v, false: v}[v < 0] }
func or(s, alt string) string                                                                 { return map[bool]string{true: alt, false: s}[s == ""] }

// wd/pad/cut：CJK 在终端占两列，按显示宽度补齐、按 rune 截断表格才对齐（纯函数 → 两次跑字节一致）。
func wd(s string) int            { return (len(s)+len([]rune(s)))/2 - strings.Count(s, "…") }
func pad(s string, n int) string { return s + strings.Repeat(" ", max(0, n-wd(s))) }
func cut(s string, n int) string {
	r := []rune(s)
	return map[bool]string{true: s, false: string(r[:n-1]) + "…"}[len(r) <= n]
}

// ---------- 内存表：homeos_notification（软删列必须是 gorm.DeletedAt，GORM 才会自动加 IS NULL） ----------
type Note struct {
	ID                                                              int64
	FamilyID, RecipientUserID                                       string
	Kind, SourceSystem, SourceID, ClientRequestID, Title, DeletedBy string
	AmountCents                                                     int64
	CreatedAt                                                       time.Time
	ReadAt, RecalledAt                                              *time.Time
	DeletedAt                                                       gorm.DeletedAt
	bypass                                                          bool // true＝业务面直接 INSERT 的行（第 5 节反例专用；真库里没这条路径）
}
type Ev struct {
	Topic, Fam, Recipient, SourceSystem, SourceID, Kind, CRID, Title, Code string
	SpentCents, LimitCents                                                 int64
	DueAt                                                                  time.Time
}
type Rule struct {
	Code, Fam, Recipient string
	cents                int64
	next                 time.Time
	active               bool
}

func (n Note) Dedup() string   { return n.SourceSystem + sep + n.SourceID + sep + n.Kind }
func (e Ev) Dedup() string     { return e.SourceSystem + sep + e.SourceID + sep + e.Kind }
func (Note) TableName() string { return "homeos_notification" }

var notes []Note
var byKey = map[string]Note{}    // 幂等键 → 首次那条（consume 维护；第 2/3 节打印返回行用它）
var center = map[string]Rule{}   // 到期中心的条目：键＝幂等键 (source_system, source_id, kind)，值＝那根 next_at
var localDue = map[string]Rule{} // ❌ 反例专用：业务面自己 sleep 的计时器，中心不知道它们存在
var delivered = map[string]int{}
var nextID int64
var busPub, dropped, bizTimers, revokeHits, revokeMisses int
var rules = []Rule{{"rent-house", famA, uDad, 180000, d19, true}, {"tuition-learn", famA, uDad, 260000, d19, true}, {"pet-vet", famA, uDad, 30000, d20, false}}

// filter/cnt 逐行真数；isUnread/unread 是全项目唯一的未读口径（S11 d33 定名，W51 沿用）；toMe/from 是谓词复用。
func cnt(p func(Note) bool) (c int) {
	for _, x := range notes {
		c += yes[p(x)]
	}
	return c
}
func isUnread(x Note) bool { return x.ReadAt == nil && !x.DeletedAt.Valid }
func toMe(x Note, fam, user string) bool {
	return x.FamilyID == fam && x.RecipientUserID == user && isUnread(x)
}
func from(x Note, sys, sid string) bool {
	return x.SourceSystem == sys && x.SourceID == sid && isUnread(x)
}
func unread(fam, user string) int  { return cnt(func(x Note) bool { return toMe(x, fam, user) }) }
func miss(f func(Note) string) int { return cnt(func(x Note) bool { return x.bypass && f(x) == "" }) }
func findDedup(e Ev) Note          { return byKey[e.Dedup()] }

// traceable：一行能不能反查回 source_system + source_id（直插行三样都缺）。
func traceable(n Note) bool {
	return !n.bypass && n.SourceSystem != "" && n.ClientRequestID != "" && strings.Contains(n.SourceID, sep)
}

// pub：通知表唯一发布口——投递计数 + 交给唯一消费者 consume。到期注册走 pubDue，两条路都在 busPub 里计数。
func pub(e Ev) int { busPub++; delivered[e.Dedup()]++; return consume(e) }

// guard：落库前三道门。family_id 只从会话取（query 传了也不认）、kind 必须三选一、写操作必带
// client_request_id、跨家庭收件人 404。两条 400 分支都在信息里给合法形状，没有一条会「默默用默认值」。
func guard(sessionFam, queryFam, kind, crid, recipient string) (int, string) {
	if recipient == uMom && sessionFam != famB || recipient == uDad && sessionFam != famA {
		return 404, fmt.Sprintf("收件人 %s 不在会话家庭 %s：返 404 不返 403（403 会把「这行存在」泄露给别家）", recipient, sessionFam)
	}
	if !kindOK[kind] {
		return 400, fmt.Sprintf("kind=%q 非法：合法形状＝kind ∈ {budget_alert, system, reminder} 三选一，不回落 system、不置空", kind)
	}
	if crid == "" {
		return 400, "client_request_id 缺失：写接口必带，合法形状＝crid=<source_system>-<source_id>（幂等命中时返回首次那条）"
	}
	return 200, map[bool]string{true: "落库（query family_id 已忽略，仍按会话家庭写）", false: "落库"}[queryFam != "" && queryFam != sessionFam]
}

// consume：通知表唯一的写入者——先过三道门，再按幂等键落库；同键命中就返回首次那条、不新增。
func consume(e Ev) int {
	if code, _ := guard(e.Fam, "", e.Kind, e.CRID, e.Recipient); code != 200 {
		dropped++
		return 0
	}
	if _, ok := byKey[e.Dedup()]; ok {
		return 0
	}
	nextID++
	n := Note{ID: nextID, FamilyID: e.Fam, RecipientUserID: e.Recipient, Kind: e.Kind, SourceSystem: e.SourceSystem, SourceID: e.SourceID, ClientRequestID: e.CRID, Title: e.Title, AmountCents: e.SpentCents, CreatedAt: fixedNow}
	notes, byKey[e.Dedup()] = append(notes, n), n
	return 1
}

// recall：按来源撤回（不删行，落 recalled_at，由出口过滤——d16 展开）。命中 0 就是撤回落空。
func recall(sys, sid string) (int, int) {
	hit := 0
	for i := range notes {
		if from(notes[i], sys, sid) {
			notes[i].RecalledAt, hit = &fixedNow, hit+1
		}
	}
	revokeHits, revokeMisses = revokeHits+yes[hit > 0], revokeMisses+yes[hit == 0]
	return hit, len(notes)
}

// pubBudget：finance 面的超支判定。库里无该周期预算行 → 不发事件（页面显「未设该周期预算」，不做月度 ×3 折算）。
func pubBudget(fam, recipient, p string) (Note, int) {
	sp, lim := spentCents[fam+sep+p], budgetCents[fam+sep+p]
	if lim == 0 || sp <= lim || !alertOn[fam] {
		return Note{}, 0
	}
	e := Ev{topicOf[kBudget], fam, recipient, srcOf[kBudget], fam + sep + topicOf[kBudget] + sep + p, kBudget, "fin-" + fam + "-" + p, fmt.Sprintf("%s 支出 %s 元，超出预算 %s 元", p, money(sp), money(sp-lim)), "", sp, lim, clock}
	add := pub(e)
	return findDedup(e), add
}

// pubSystem：homeos 自己的公告生成器，source_system 恒为 homeos。
func pubSystem(fam, recipient, sid, crid, title string) (Note, int) {
	e := Ev{topicOf[kSys], fam, recipient, srcOf[kSys], sid, kSys, crid, title, "", 0, 0, clock}
	add := pub(e)
	return findDedup(e), add
}

// pubDue：{code}.due.registered|revoked 的唯一入口，幂等键就是中心那张 map 的键。返（中心变动条数, 中心条数）。
func pubDue(r Rule, revoke bool) (int, int) {
	busPub++
	e := Ev{dueTopic(r.Code, revoke), r.Fam, r.Recipient, srcOf[kBudget], "finance" + sep + r.Code + sep + "recurring_rule", "recurring_rule", "due-" + dueTopic(r.Code, revoke), "", r.Code, r.cents, 0, r.next}
	delivered[e.Dedup()]++
	_, ok := center[e.Dedup()]
	if revoke && ok {
		delete(center, e.Dedup())
	}
	if !revoke && !ok {
		center[e.Dedup()] = r
	}
	return yes[ok == revoke], len(center)
}
func dueTopic(code string, revoke bool) string {
	return map[bool]string{true: code + ".due.revoked", false: code + ".due.registered"}[revoke]
}
func reminderEv(r Rule, sys, sid string) Ev {
	return Ev{topicOf[kReminder], r.Fam, r.Recipient, sys, sid, kReminder, "due-" + r.Code + "-" + r.next.Format("2006-01-02"), fmt.Sprintf("%s 周期记账 %s 元到点", r.Code, money(r.cents)), r.Code, r.cents, 0, r.next}
}

// tick：到点触发的唯一实现。喂 center 就是到期中心（正例），喂 localDue 就是 ❌ 业务面自起的计时器——同一段
// 代码，但中心那张表里没有这条规则，所以 {code}.due.revoked 撤不掉它产的行。只有中心那一版会推 clock。
func tick(m map[string]Rule, t time.Time, pre string) (f int) {
	for _, k := range keys(m) {
		r := m[k]
		if !r.next.After(t) {
			f += pub(reminderEv(r, srcOf[kReminder], pre+sep+r.Code+sep+r.next.Format("2006-01-02")))
			r.next, m[k] = r.next.AddDate(0, 1, 0), r
		}
	}
	return f
}

// keys：Map 序一律先排再读 → 字节一致。
func keys(m map[string]Rule) (out []string) {
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// ---------- DryRun：本机无库，只出 Postgres 原文 ----------
