// =====================================================================
// W51 d14：未读数只有一个来源 —— 三个出口必须同值
// 核心不变量：homeos_notification 的未读数只有一个实现——unread(fam, user)（S11 d33 定名，W51 沿用）。
// 首页角标、列表页的 total_unread、标记已读接口的返回体，三个出口必须调同一个函数、返回同一个数。
// 口径也只有一句：read_at IS NULL 且 deleted_at IS NULL 且 family_id = 会话家庭 且 recipient_user_id = 自己。
// 反例三件套：列表页拿 LIMIT 20 的结果集数未读、首页用一条漏了 recipient 与软删过滤的 COUNT、已读接口把
// 「前端本地减 1」当新未读数返回——三个数当场不一样，程序把各自差几个也算出来。内存里真跑的部分：43 行通知的
// 读/未读/软删状态、批量已读、client_request_id 幂等重放、三个出口与三个反例的计数全部现算，没一个数是写死的。
// DryRun 真实 SQL 的部分：未读口径的 SELECT count、列表页的 SELECT ... LIMIT 20、首页那条漏条件的 COUNT、
// 批量已读的 UPDATE、软删与恢复的 UPDATE，全由 GORM DryRun 生成（DisableAutomaticPing + NowFunc 固定时间戳
// → 两次跑字节一致），本机不连库只打印。真环境要复跑：① 那三条 SELECT 换真库执行，未读数必须与内存一致；② 批量
// 已读的 UPDATE 加 RETURNING，返回体里的 unread 由这条 SQL 现算，不能让前端报数；③ 软删/恢复走真库的 deleted_at
// + deleted_by，并验证账本表 homeos_ledger_row 一行都不少。
// 学员侧跑法：cd homecube/server && go run ./lab/s12/d14
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gormlogger "gorm.io/gorm/logger"
)

const (
	famA, famB, uDad, uKid, uMom = "fam-A", "fam-B", "u-dad", "u-kid", "u-mom"
	kBudget, kSys, kReminder     = "budget_alert", "system", "reminder"
	sep, pageLimit               = "|", 20
)

var fixedNow = time.Date(2026, 10, 19, 9, 0, 0, 0, time.FixedZone("Asia/Shanghai", 8*3600))
var tMark = fixedNow.Add(2 * time.Hour) // 批量已读写下的 read_at（固定 → 两次跑字节一致）
var yes = map[bool]int{true: 1, false: 0}
var mark = map[bool]string{true: "✅", false: "❌"}
var legalKind = []string{kBudget, kSys, kReminder}
var famOf = map[string]string{uDad: famA, uKid: famA, uMom: famB} // 收件人归属：读别人家的通知就是越权

func hdr(s string)          { fmt.Printf("\n===== %s =====\n", s) }
func at(t time.Time) string { return t.Format("2006-01-02 15:04:05") }

// wd/pad：CJK 占两列，按显示宽度补齐（纯函数 → 字节一致）。
func wd(s string) int            { return (len(s)+len([]rune(s)))/2 - strings.Count(s, "…") }
func pad(s string, n int) string { return s + strings.Repeat(" ", max(0, n-wd(s))) }

// ---------- 内存表：homeos_notification（软删列必须是 gorm.DeletedAt，GORM 才会自动补 IS NULL） ----------
type noteRow struct {
	ID                                     int64
	FamilyID, RecipientUserID, Kind, Title string
	SourceSystem, SourceID, DeletedBy      string
	AmountCents                            int64
	ReadAt                                 *time.Time
	DeletedAt                              gorm.DeletedAt
}

func (noteRow) TableName() string { return "homeos_notification" }

type seed struct {
	fam, user, kind, sys, pre, title string
	n                                int
	cents                            int64
	read, del                        bool
}

var seeds = []seed{{famA, uDad, kBudget, "finance", "budget-exceeded", "本月支出超预算", 8, 2518000, false, false}, {famA, uDad, kSys, "homeos", "announcement", "维护窗口 / 面配置变更", 10, 0, false, false}, {famA, uDad, kReminder, "due-center", "recurring-due", "周期记账到点提醒", 8, 180000, false, false}, {famA, uDad, kBudget, "finance", "budget-exceeded-old", "上月支出超预算（已读过）", 5, 2400000, true, false}, {famA, uDad, kSys, "homeos", "announcement-gone", "公告已撤回（软删）", 3, 0, false, true}, {famA, uKid, kReminder, "due-center", "kid-due", "兴趣班到点提醒", 5, 30000, false, false}, {famB, uMom, kSys, "homeos", "mom-announcement", "别家的通知", 4, 2380000, false, false}}

var notes []noteRow
var nextID, totalCents int64
var timers int                                                                                  // 判据：出口谁都不许自己算未读/自己起计时器，这个数必须是 0
var byCRID = map[string]int{}                                                                   // client_request_id → 首次返回的未读数（写接口幂等）
var delivered = map[string]int{}                                                                // 幂等键 (source_system, source_id, kind) → 投递次数（d15 展开）
var ledger = map[string]int64{famA + sep + "2026-10": 2518000, famB + sep + "2026-10": 2380000} // 账本月桶：通知怎么删都不许级联动它

// filt/cnt：全项目只这一处遍历通知表；alive() 只有一处未读判定。
func filt(p func(noteRow) bool) (out []noteRow) {
	for _, x := range notes {
		if p(x) {
			out = append(out, x)
		}
	}
	return out
}
func cnt(p func(noteRow) bool) int          { return len(filt(p)) }
func alive(x noteRow) bool                  { return x.ReadAt == nil && !x.DeletedAt.Valid }
func mine(x noteRow, fam, user string) bool { return x.FamilyID == fam && x.RecipientUserID == user }

func ledgerCents() (t int64) {
	for _, v := range ledger {
		t += v
	}
	return t
}

// unread：全项目唯一的未读数来源。三个出口只许调它，谁自己 COUNT 一遍谁就是第 4 节的反例。
func unread(fam, user string) int {
	return cnt(func(x noteRow) bool { return mine(x, fam, user) && alive(x) })
}

// addRow：通知只能由事件产出（d13 口径），这里按 source_system + source_id 落一行，read/del 控状态。
func addRow(fam, user, kind, sys, sid, title string, cents int64, read, del bool) {
	nextID, totalCents = nextID+1, totalCents+cents
	delivered[fam+sep+sid+sep+kind]++
	n := noteRow{ID: nextID, FamilyID: fam, RecipientUserID: user, Kind: kind, Title: title, SourceSystem: sys, SourceID: sid, AmountCents: cents}
	if read {
		n.ReadAt = &fixedNow
	}
	if del {
		n.DeletedAt, n.DeletedBy = gorm.DeletedAt{Time: fixedNow, Valid: true}, user
	}
	notes = append(notes, n)
}
func seedAll() {
	for _, g := range seeds {
		for i := 1; i <= g.n; i++ {
			addRow(g.fam, g.user, g.kind, g.sys, fmt.Sprintf("%s-%02d", g.pre, i), fmt.Sprintf("%s %02d", g.title, i), g.cents, g.read, g.del)
		}
	}
}

// guardSession：三个出口共用的会话门。family_id 只从会话取（query 传了也不认）、收件人不在会话家庭一律 404（不是 403）、scope 非法 400 给形状——绝不静默回落。
func guardSession(sessFam, queryFam, user, scope string) (int, string) {
	if famOf[user] != sessFam {
		return 404, fmt.Sprintf("收件人 %s 不在会话家庭 %s：返 404 不返 403（403 会把「这家有这个人」泄露出去）", user, sessFam)
	}
	if scope != "" && scope != "unread" && scope != "all" {
		return 400, fmt.Sprintf("scope=%q 非法：合法形状＝scope ∈ {unread, all} 二选一，不回落 unread、不置空", scope)
	}
	return 200, map[bool]string{true: "query family_id=" + queryFam + " 被忽略，只认会话家庭 " + sessFam, false: "会话家庭为准"}[queryFam != "" && queryFam != sessFam]
}

// badge：首页角标。
func badge(sessFam, queryFam, user string) (int, int, string) {
	code, msg := guardSession(sessFam, queryFam, user, "unread")
	if code != 200 {
		return code, -1, msg
	}
	return code, unread(sessFam, user), msg
}

// listPage：列表页。limit 只决定这次回几行，total_unread 永远来自 unread()，跟 limit 没关系。
func listPage(sessFam, user string, limit int) (rows []noteRow, code int, total int, msg string) {
	if code, msg = guardSession(sessFam, "", user, "unread"); code != 200 {
		return nil, code, -1, msg
	}
	if limit < 1 || limit > 50 {
		return nil, 400, -1, fmt.Sprintf("limit=%d 非法：合法形状＝limit ∈ [1, 50] 的整数，不静默按 20 行返回", limit)
	}
	for _, x := range filt(func(y noteRow) bool { return mine(y, sessFam, user) && alive(y) }) {
		if len(rows) < limit {
			rows = append(rows, x)
		}
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].ID < rows[j].ID })
	return rows, 200, unread(sessFam, user), msg
}

// markRead：标记已读（写接口，必带 client_request_id）。返回体的 unread 由 unread() 现算，不是前端报的数。
func markRead(sessFam, user, crid string, ids []int64) (int, int, string) {
	code, msg := guardSession(sessFam, "", user, "unread")
	if code != 200 {
		return code, -1, msg
	}
	if crid == "" {
		return 400, -1, "client_request_id 缺失：写接口必带，合法形状＝crid=markread-<家庭>-<时间戳>（同 crid 重放返回首次那个数）"
	}
	if v, ok := byCRID[crid]; ok {
		return 200, v, "幂等命中：同一 crid 重放，一行都没再改，原样返回首次结果"
	}
	changed := 0
	for i := range notes {
		for _, id := range ids {
			if notes[i].ID == id && mine(notes[i], sessFam, user) && alive(notes[i]) {
				notes[i].ReadAt, changed = &tMark, changed+1
			}
		}
	}
	byCRID[crid] = unread(sessFam, user)
	return 200, byCRID[crid], fmt.Sprintf("本次真改了 %d 行（逐行验 read_at IS NULL，写 read_at=%s），返回体的 unread 现算于库", changed, at(tMark))
}

// ---------- 三个出口各自会长歪的地方（反例三件套，全部真跑） ----------
// ❌ 反例一：列表页拿 LIMIT 20 的结果集数未读——第 21 条开始永远看不见。
func unreadFromPage(sessFam, user string, limit int) (int, int) {
	rows, _, _, _ := listPage(sessFam, user, limit)
	return len(rows), len(rows) // ❌ 把「这次回了几个」直接当成「还欠几个没读」
}

// ❌ 反例二：首页那条 COUNT 漏了 recipient_user_id，也漏了软删过滤（整家人的 + 已撤回的都算进来）。
func unreadByFamilyCount(sessFam string) int {
	return cnt(func(x noteRow) bool { return x.FamilyID == sessFam && x.ReadAt == nil })
}

// ❌ 反例三：已读接口不查库，把前端本地减 1 的数原样返回（snapshot＝旧角标，taps＝点了几下）；顺手记一笔 timers，它正是「出口自己算未读」这条红线的反证。
func unreadFromFrontend(snapshot, taps int) int {
	timers++
	return snapshot - taps
}

// restore：软删的唯一恢复路径（真库里就是那条 Unscoped UPDATE）。
func restore(id int64) bool {
	for i := range notes {
		if notes[i].ID == id {
			notes[i].DeletedAt = gorm.DeletedAt{}
			return true
		}
	}
	return false
}

// ---------- DryRun：本机无库，只出 Postgres 原文 ----------
func dryDB() *gorm.DB {
	db, e := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_homeos:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if e != nil {
		panic(e)
	}
	return db
}

func main() {
	db, cnt6 := dryDB(), new(int64)
	hdr("1. 未读口径只有一句话，实现只有一个函数")
	fmt.Printf("  口径：read_at IS NULL 且 deleted_at IS NULL 且 family_id = 会话家庭 且 recipient_user_id = 自己\n  实现：unread(fam, user) —— 除此之外谁都不许自己数；未读判定只有 alive() 一处，遍历通知表只有 filt() 一处\n    func unread(fam, user string) int { return cnt(func(x noteRow) bool { return mine(x, fam, user) && alive(x) }) }\n  三个出口（今天就这三个口子）：首页角标 badge() · 列表页 listPage() 的 total_unread · 已读接口 markRead() 的返回体 unread\n  它们本该是同一条 SELECT count（DryRun 原文，末尾的 deleted_at IS NULL 是 GORM 自己补的）：\n    %s\n",
		db.ToSQL(func(tx *gorm.DB) *gorm.DB {
			return tx.Model(&noteRow{}).Where("family_id = ? AND recipient_user_id = ? AND read_at IS NULL", famA, uDad).Count(cnt6)
		}))
