// wd/pad：CJK 占两列，按显示宽度补齐（纯函数 → 两次跑字节一致）。
func wd(s string) int            { return (len(s) + len([]rune(s))) / 2 }
func pad(s string, n int) string { return s + strings.Repeat(" ", max(0, n-wd(s))) }

// ---------- 内存表 homeos_notification：唯一约束由 store.byKey 这个 map 真实现，map 的键就是幂等键 ----------
type noteRow struct {
	ID                                int64
	FamilyID, RecipientUserID         string
	Kind, SourceSystem, SourceID      string
	ClientRequestID, Title, DeletedBy string
	AmountCents                       int64
	CreatedAt                         time.Time
	ReadAt                            *time.Time
	DeletedAt                         gorm.DeletedAt
}

func (noteRow) TableName() string { return "homeos_notification" }
func (x noteRow) Dedup() string   { return x.SourceSystem + sep + x.SourceID + sep + x.Kind }

// dueRow：到期中心的表（DryRun 只出 INSERT 文本；键与通知表同进退）。
type dueRow struct {
	ID                           int64
	SourceSystem, SourceID, Kind string
	DueAt                        time.Time
}

func (dueRow) TableName() string { return "homeos_due_entry" }

// Ev：一条待投递的通知事件。幂等键是这三元组，client_request_id 是「谁投的这一次」，两者缺一不可。
type Ev struct {
	Fam, Recipient, SourceSystem, SourceID, Kind, CRID, Title string
	AmountCents                                               int64
}

func (e Ev) Dedup() string { return e.SourceSystem + sep + e.SourceID + sep + e.Kind }
func (e Ev) row() noteRow {
	return noteRow{FamilyID: e.Fam, RecipientUserID: e.Recipient, Kind: e.Kind, SourceSystem: e.SourceSystem, SourceID: e.SourceID,
		ClientRequestID: e.CRID, Title: e.Title, AmountCents: e.AmountCents, CreatedAt: fixedNow}
}

// outcome：一个并发 worker 的返回。只收「与调度无关」的字段；调度相关的（谁抢到首次插入）另做汇总计数。
type outcome struct {
	w, ukID, ukRows, ukUnread, rawIns, rawID int
	rawKey                                   string
}

// store：一份通知表。uk=true 代表库上真有 uniq(source_system, source_id, kind)，
// uk=false 就是「忘了建索引」那一版——同一段投递代码，两种下场。
type store struct {
	name                string
	uk                  bool
	mu                  sync.Mutex
	rows                []noteRow
	byKey               map[string]noteRow // 唯一约束在内存里的等价实现：这个 map 的键就是幂等键
	next, inserts, hits int
}

func newStore(name string, uk bool) *store {
	return &store{name: name, uk: uk, byKey: map[string]noteRow{}}
}

// deliver：落库。有约束那版命中同键就原样返回第一次那行、一行都不新增（等价 ON CONFLICT DO NOTHING）；
// 无约束那版 byKey 恒空、一句判重都没有，来一次落一次。
func (s *store) deliver(e Ev) (noteRow, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if r, ok := s.byKey[e.Dedup()]; ok {
		s.hits++
		return r, false
	}
	s.next++
	r := e.row()
	r.ID = int64(s.next)
	s.rows = append(s.rows, r)
	if s.uk {
		s.byKey[e.Dedup()] = r
	}
	s.inserts++
	return r, true
}

func (s *store) count() int { s.mu.Lock(); defer s.mu.Unlock(); return len(s.rows) }

// unread：全项目唯一的未读口径（d14 定死的那句话）——read_at IS NULL 且没软删，family_id 与收件人恒在条件里。
func (s *store) unread(fam, user string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	c := 0
	for _, x := range s.rows {
		if x.FamilyID == fam && x.RecipientUserID == user && x.ReadAt == nil && !x.DeletedAt.Valid {
			c++
		}
	}
	return c
}

func famOf(u string) string { return map[bool]string{true: famB, false: famA}[u == uMom] }

// guard：落库前三道门（与 d13 同一套口径）。family_id 只从会话取、跨家庭 404、kind 三选一、写必带 crid。
func guard(sessFam, kind, crid, recipient string) (int, string) {
	if famOf(recipient) != sessFam {
		return 404, fmt.Sprintf("收件人 %s 不在会话家庭 %s：返 404 不返 403（403 会把「这行存在」泄露给别家）", recipient, sessFam)
	}
	if !kindOK[kind] {
		return 400, fmt.Sprintf("kind=%q 非法：合法形状＝kind ∈ {budget_alert, system, reminder} 三选一，不回落 system、不置空", kind)
	}
	if crid == "" {
		return 400, "client_request_id 缺失：写接口必带，合法形状＝crid=<source_system>-<source_id>（同 crid 重投返回首次那行）"
	}
	return 200, "三道门全过（family_id 取会话那个，参数里塞的不认）"
}

var dropped int

// accept：投递的唯一入口——先过门，再落库；被门挡下的次数累计在 dropped 里。
func accept(s *store, e Ev) (noteRow, bool) {
	if code, _ := guard(e.Fam, e.Kind, e.CRID, e.Recipient); code != 200 {
		dropped++
		return noteRow{}, false
	}
	return s.deliver(e)
}

// 到期中心：注册与撤回吃同一把幂等键，业务面自己不许起计时器（d13 已验，今天把重复注册钉死）。
var center = map[string]string{}

func pubDue(code string, revoke bool) bool {
	k := srcOf[kReminder] + sep + code + sep + kReminder
	if revoke {
		_, ok := center[k]
		delete(center, k)
		return ok
	}
	_, dup := center[k]
	center[k] = code
	return !dup
}

// dupGroups：按幂等键分组数「行数 > 1 的组」，就是那条 GROUP BY ... HAVING count(*) > 1 的内存等价实现。
func dupGroups(s *store) (n int) {
	seen := map[string]int{}
	for _, x := range s.rows {
		seen[x.Dedup()]++
	}
	for _, v := range seen {
		n += yes[v > 1]
	}
	return n
}

// cntOfKey：表里同一个幂等键占了几行（重复投递的直接证据）。
func cntOfKey(s *store, e Ev) int {
	n := 0
	for _, x := range s.rows {
		if x.Dedup() == e.Dedup() {
			n++
		}
	}
	return n
}

// keyList：把「行 id → 出现次数」的 map 排好序拼成一行（并发表里 20 路返回 id 的集合观测，调度无关）。
func keyList(m map[int]int) string {
	var ids []int
	for k := range m {
		ids = append(ids, k)
	}
	sort.Ints(ids)
	s := make([]string, 0, len(ids))
	for _, v := range ids {
		s = append(s, fmt.Sprintf("%d×%d", v, m[v]))
	}
	return strings.Join(s, " ")
}

// allSame：字符串数组是否全等（三次同键投递返回的 id / 行数 / 未读数各自对拍用）。
func allSame(v []string) bool {
	for _, x := range v {
		if x != v[0] {
			return false
		}
	}
	return true
}

// idSet：从 20 路并发结果里取返回行 id（useUK=true 取 uk 那份，false 取 raw 那份），去重升序拼串，再给 distinct 数。
func idSet(got []outcome, useUK bool) (string, int) {
	set := map[int]bool{}
	for _, r := range got {
		if useUK {
			set[r.ukID] = true
		} else {
			set[r.rawID] = true
		}
	}
	ids := make([]int, 0, len(set))
	for id := range set {
		ids = append(ids, id)
	}
	sort.Ints(ids) // 去重升序：与并发调度顺序无关，输出字节确定
	s := make([]string, 0, len(ids))
	for _, id := range ids {
		s = append(s, fmt.Sprint(id))
	}
	return strings.Join(s, ","), len(ids)
}

// inOrder：got 是否严格按 worker 编号 0..n-1 升序（排序打印生效的证据）。
func inOrder(got []outcome) bool {
	for i, r := range got {
		if r.w != i {
			return false
		}
	}
	return true
}

