	at, due, read, recall, del            time.Time
	delBy                                 string // 软删必须成对：deleted_at + deleted_by
}

func counted(n note) bool { return n.read.IsZero() && n.recall.IsZero() && n.del.IsZero() } // 未读的唯一谓词

