// ---------- 过滤与未读数：所有计数、列表、抽样只从 filt 出来；谓词里 family_id 恒在最前（对应每条 SQL 都带 family_id、只从会话取）----------
func filt[T any](rs []T, f func(T) bool) []T {
	out := []T{}
	for _, x := range rs {
		if f(x) {
			out = append(out, x)
		}
	}
	return out
}
func unreadOf(rs []note, fam string) int {
	return len(filt(rs, func(x note) bool { return x.fam == fam && counted(x) }))
}
func unread(fam string) int { return unreadOf(notes, fam) }
func visOf(rs []note, fam string) []note {
	out := filt(rs, func(x note) bool { return x.fam == fam && x.recall.IsZero() && x.del.IsZero() }) // 已读仍可见，撤回 / 软删才不出列表
	sort.Slice(out, func(i, j int) bool { return out[i].at.After(out[j].at) })                        // 本批 created_at 互不相同；同秒全序留给 d17
	return out
}
func visible(fam string) []note { return visOf(notes, fam) }
func row(id string) note        { return filt(notes, func(x note) bool { return x.id == id })[0] }
func exitBadge(fam string) int  { return unread(fam) } // 出口 1：/home/summary 的 unread_count（首页角标）
func exitList(fam string) int   { return unread(fam) } // 出口 2：通知列表响应的 unread_count
func exitAct(fam string) int    { return unread(fam) } // 出口 3：recall / mark-read 接口返回的 unread_count
func cat(rs []note) string {
	s := ""
	for _, x := range rs {
		s += x.id + " "
	}
	return strings.TrimRight(s, " ")
}
func born(rs []note) string { return map[bool]string{true: "（无）", false: cat(rs)}[len(rs) == 0] }
func same3(fam string) string {
	b, l, a := exitBadge(fam), exitList(fam), exitAct(fam)
	return fmt.Sprintf("角标 %d｜列表 %d｜动作返回 %d %s", b, l, a, mark[b == l && l == a])
}

// fakeRead 返回副本：命中的行被「调度器替用户写 read_at」。原表不动，所以反证跑完不需要回滚。
func fakeRead(rs []note, f func(note) bool, at time.Time) []note {
	out := append([]note{}, rs...)
	for i := range out {
		out[i].read = map[bool]time.Time{true: at, false: out[i].read}[f(out[i])]
	}
	return out
}

// ---------- 到期中心：{code}.due.registered | {code}.due.revoked，幂等键 (source_system, source_id, kind) ----------
type due struct {
	sys, sid, kind, fam, code string
	next, cancel              time.Time
}

func (d due) key() string { return d.sys + "|" + d.sid + "|" + d.kind }

var dues, clock = []due{}, day0(2026, 12, 1)
var timers, published, directInsert, bizTimers, inTick = 0, 0, 0, 0, false
var seenCrid = map[string]int{}

func dueIdx(k string) int {
	for i, d := range dues {
		if d.key() == k {
			return i
		}
	}
	return -1
}
func regDue(r due, revoke bool) int { // 事件总线上只有这两条路：注册与撤注
	published++
	i := dueIdx(r.key())
	switch {
	case i < 0 && !revoke:
		dues, timers = append(dues, r), timers+1
		return 1
	case i >= 0 && revoke && dues[i].cancel.IsZero():
		dues[i].cancel, timers = clock, timers-1 // 撤注＝终止条目，不删条目（审计要留「何时撤的」）
		return 1
	}
	return 0 // 其余全是 no-op：同键重复注册 / 撤不存在的条目 / 撤已撤的条目
}
func busDeliver(fam, kind, sys, sid, title string, cents int64, at, dueAt time.Time) int { // 通知落库的唯一入口
	published++
	dk := fam + "|" + sys + "|" + sid + "|" + kind
	if len(filt(notes, func(x note) bool { return x.dedup == dk })) > 0 {
		return 0 // 同 (family_id, dedup_key) 命中 → no-op，等价 ON CONFLICT DO NOTHING
	}
	seq++
	notes = append(notes, note{fmt.Sprintf("N-%02d", seq), fam, kind, sys, sid, dk, title, cents, at, dueAt, time.Time{}, time.Time{}, time.Time{}, ""})
	return 1
}
func advanceClock(t time.Time) { bizTimers += yes[!inTick]; clock = t } // 推时钟的唯一入口：不在 tick 里推＝业务面自起计时器
func tick(t time.Time) (int, []note) { // 只有到期中心能推时钟
	if inTick {
		return 0, nil // 重入保护：中心里不再套第二层计时器
	}
	inTick = true
	fired, rows := 0, []note{}
	advanceClock(t)
	for i := range dues {
		d := &dues[i]
		if !d.cancel.IsZero() || d.next.After(t) {
			continue // 已撤注的条目永远扫不到
		}
		sid := fmt.Sprintf("recurring.reminder|%s@%s", d.code, d.next.Format("2006-01-02"))
		before := len(notes)
		if busDeliver(d.fam, "reminder", d.sys, sid, "周期记账提醒 "+d.code, 0, d.next, d.next.Add(23*time.Hour+59*time.Minute)) == 1 {
			fired, rows = fired+1, append(rows, notes[before])
		}
		d.next = d.next.AddDate(0, 1, 0) // 期次推到下个月
	}
	inTick = false
	return fired, rows
}

// recall：撤回一条已投递的通知 —— 只写 recalled_at，绝不删行
func recall(sessFam, crid, id string, at time.Time) (int, string, int) {
	if crid == "" {
		return 400, "缺 client_request_id：写接口必须带。合法形状＝<actor>-<action>-<target>（例 u-owner-recall-N-06-1212）", 0
	}
	if first, hit := seenCrid[crid]; hit {
		return 200, fmt.Sprintf("幂等命中：返回首次结果（首次 affected=%d），本次不再写库", first), 0
	}
	r := -1
	for k, x := range notes {
		if x.id == id {
			r = k
		}
	}
	if r < 0 || notes[r].fam != sessFam { // 「不存在」与「属于别家」同一个 404；404 不写幂等表，改对参数还能重试
		return 404, map[bool]string{true: "家内查不到该通知（不存在 / 属于别家，一律 404，不给 403）", false: "该行属于别家：跨家庭返 404（返 403 就把「这行确实存在」泄露给了调用方）"}[r < 0], 0
	}
	if !notes[r].recall.IsZero() {
		return 200, "已是撤回态，affected=0", 0
	}
	notes[r].recall = at
	seenCrid[crid] = 1
	return 200, fmt.Sprintf("recalled_at=%s，行保留、不删", hm(at)), 1
}

