package main

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	gormlogger "gorm.io/gorm/logger"
)

var famLoc = time.FixedZone("CST", 8*3600) // 家庭时区＝东八区固定偏移（不查系统 tz 库，两次跑字节一致）
var fixedNow, day10, day20 = day0(2026, 12, 8).Add(9 * time.Hour), day0(2026, 12, 10), day0(2026, 12, 20)
var mark, yes = map[bool]string{true: "✅", false: "❌"}, map[bool]int{true: 1, false: 0}

const famA, famB, famC = "fam-A", "fam-B", "fam-C"

func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }
func hm(t time.Time) string      { return t.In(famLoc).Format("2006-01-02 15:04") }
func ts(t time.Time) string      { return map[bool]string{true: "—（NULL）", false: hm(t)}[t.IsZero()] }
func hdr(s string)               { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string       { return fmt.Sprintf("%d.%02d 元", c/100, c%100) }

// ---------- 内存表 homeos_notification：read_at / recalled_at 的零值就是 SQL 里的 NULL ----------
type note struct {
	id, fam, kind, sys, sid string
	cents                   int64
	at, read, recall        time.Time
}

func counted(n note) bool { return n.read.IsZero() && n.recall.IsZero() } // 未读的唯一谓词（撤回的行不算未读，也不能被标已读）

var notes []note
var base = day0(2026, 12, 8).Add(8 * time.Hour) // 分页现场：12-08 08:00 起，每条差 7 分钟，created_at 互不相同（另造一对同秒行）

func seed(fam, kind string, lo, hi, state int) { // state：0 未读｜1 已读｜2 已撤回
	for i := lo; i <= hi; i++ {
		at, c := base.Add(time.Duration(i)*7*time.Minute), int64(0)
		if kind == "budget_alert" {
			c = int64(120000 + i*700) // 金额一律 *_cents 整数分
		}
		notes = append(notes, note{fmt.Sprintf("%s-%02d", fam[4:5], i), fam, kind, "finance", kind + "|" + fam[4:5] + fmt.Sprintf("#%02d", i), c, at, map[bool]time.Time{true: at.Add(30 * time.Minute), false: time.Time{}}[state == 1], map[bool]time.Time{true: at.Add(40 * time.Minute), false: time.Time{}}[state == 2]})
	}
}

// ---------- 过滤与未读数：所有计数、列表、翻页都只从 filt 这一个遍历入口出来 ----------
func filt[T any](rs []T, f func(T) bool) []T {
	out := []T{}
	for _, x := range rs {
		if f(x) {
			out = append(out, x)
		}
	}
	return out
}
func unreadOf(rs []note, fam string) int {
	return len(filt(rs, func(x note) bool { return x.fam == fam && counted(x) }))
}
func unread(fam string) int { return unreadOf(notes, fam) }
func sorted(rs []note) []note {
	out := append([]note{}, rs...)
	sort.Slice(out, func(i, j int) bool {
		return out[i].at.After(out[j].at) || out[i].at.Equal(out[j].at) && out[i].id > out[j].id
	}) // (created_at,id) 全序：同秒也要有唯一先后
	return out
}
func unreads(fam string) []note {
	return sorted(filt(notes, func(x note) bool { return x.fam == fam && counted(x) }))
}
func visible(fam string) []note {
	return sorted(filt(notes, func(x note) bool { return x.fam == fam && x.recall.IsZero() }))
}
func exitBadge(fam string) int { return unread(fam) } // 出口 1：/home/summary 的 unread_count（首页角标）
func exitList(fam string) int  { return unread(fam) } // 出口 2：列表响应的 unread_count（分页也报这个数）
func exitAct(fam string) int   { return unread(fam) } // 出口 3：mark-read 接口返回的 unread_count
func cat(rs []note) string     { return strings.TrimRight(idsOf(rs), " ") }
func idsOf(rs []note) (s string) {
	for _, x := range rs {
		s += x.id + " "
	}
	return
}
func same3(fam string) string {
	b, l, a := exitBadge(fam), exitList(fam), exitAct(fam)
	return fmt.Sprintf("角标 %d｜列表 %d｜动作返回 %d %s", b, l, a, mark[b == l && l == a])
}

// ---------- 翻页：游标＝(created_at, id) 二元组；offset＝行号，行集一缩就错位 ----------
type cur struct {
	at time.Time
	id string
}

func (c cur) str() string {
	return map[bool]string{true: "（首页：不带游标）", false: c.at.Format(time.RFC3339Nano) + "_" + c.id}[c.at.IsZero()]
}
func (c cur) after(x note) bool {
	return x.at.Before(c.at) || x.at.Equal(c.at) && x.id < c.id
}

// window 取第 skip 条起的 limit 条：不够就少给（真库里就是 LIMIT/OFFSET 的返回行数）
func window(rs []note, skip, limit int) []note {
	if skip >= len(rs) {
		return []note{}
	}
	return rs[min(skip+limit, len(rs)):]
}

// notIn ＝「这几行已被标读」的谓词：写库里是 read_at 非空，未读列表就不再返回它们
func notIn(got []note) func(note) bool {
	set := map[string]bool{}
	for _, x := range got {
		set[x.id] = true
	}
	return func(x note) bool { return !set[x.id] }
}

// walk 真跑「边翻边已读」：每取一页就把这几行标已读（未读集随之变小），再翻下一页。
// mode＝0 OFFSET（❌ 事故版）｜1 只带 created_at 的游标（❌ 同秒会漏）｜2 带 (created_at,id) 的游标（✅ 正解）。
func walk(rs []note, limit, mode int) (shown, missed []note, pages int) {
	left, c := append([]note{}, rs...), cur{}
	for {
		pool := left
		if mode > 0 && !c.at.IsZero() {
			pool = filt(pool, func(x note) bool { return x.at.Before(c.at) || mode == 2 && x.at.Equal(c.at) && x.id < c.id })
		}
		got := window(pool, map[bool]int{true: 0, false: pages * limit}[mode > 0], limit)
		if len(got) == 0 {
			break
		}
		pages++
		for _, x := range got {
			shown = append(shown, x)
		}
		fmt.Printf("    第 %d 页（%s）→ 返回 %d 条：%s\n", pages, map[int]string{0: "OFFSET", 1: "游标只带 created_at", 2: "游标带 (created_at,id)"}[mode], len(got), cat(got))
		c = cur{got[len(got)-1].at, got[len(got)-1].id}
		left = filt(left, notIn(got)) // 边读边已读：这几行立刻从未读列表消失
	}
	return shown, left, pages
}

// ---------- 批量已读：正解＝family_id + 分型 + 截止时刻；❌ 无界＝WHERE read_at IS NULL ----------
var seenCrid = map[string]int{}

// stamp 给命中谓词的行写 read_at，返回受影响行数（真库＝UPDATE 的 RowsAffected）
func stamp(f func(note) bool, at time.Time) int {
	n := 0
	for i := range notes {
		if f(notes[i]) && notes[i].read.IsZero() {
			notes[i].read = at
			n++
		}
	}
	return n
}

// markRead 是写接口：只认会话里的 family_id，kind 与截止时刻必带，client_request_id 缺失就 400。
func markRead(sessFam, wantFam, kind string, cutoff, at time.Time, crid string) (int, string, int) {
	if crid == "" {
		return 400, "缺 client_request_id：写接口必须带。合法形状＝<actor>-<action>-<scope>（例 u-owner-readall-budget_alert-1208）", 0
	}
	if wantFam != sessFam {
		return 404, "会话外的 family_id：家内查不到这个范围 → 404（不给 403，403 等于承认别家存在）", 0
	}
	if len(filt([]string{"budget_alert", "system", "reminder"}, func(k string) bool { return k == kind })) == 0 {
		return 400, "kind 非法：合法形状 kind ∈ budget_alert / system / reminder（不静默当作「全部分型」）", 0
	}
	if first, hit := seenCrid[crid]; hit {
		return 200, fmt.Sprintf("幂等命中：返回首次结果（首次 affected=%d），本次不再写库", first), 0
	}
	n := stamp(func(x note) bool {
		return x.fam == wantFam && x.kind == kind && !x.at.After(cutoff) && x.recall.IsZero()
	}, at)
	seenCrid[crid] = n
	return 200, fmt.Sprintf("affected=%d：只标 %s 里 %s 且 created_at≤%s 的未读行", n, wantFam, kind, hm(cutoff)), n
}

// pageArgs 校验列表入参：limit 1..50，游标 <RFC3339Nano>_<id>；非法一律 400 + 合法形状，绝不静默回落。
func pageArgs(limit int, cursorStr string) (int, cur, string) {
	if limit < 1 || limit > 50 {
		return 0, cur{}, "400 limit 非法：合法形状 1..50（绝不静默改成 20，也不静默截到 50）"
	}
	if cursorStr == "" {
		return limit, cur{}, "200 首页不带游标"
	}
	i := strings.LastIndex(cursorStr, "_")
	t, e := time.Parse(time.RFC3339Nano, cursorStr[:max(i, 0)])
	if e != nil || i < 0 || len(cursorStr[i+1:]) != 4 || cursorStr[i+2] != '-' {
		return 0, cur{}, "400 游标非法：合法形状 <RFC3339Nano>_<id>（例 2026-12-08T08:42:00+08:00_A-06）"
	}
	return limit, cur{t.In(famLoc), cursorStr[i+1:]}, "200 游标可用"
}

// ---------- 本机无 PostgreSQL：DryRun 生成真实 Postgres 语句文本 ----------
type Notification struct {
	ID, FamilyID, Kind, SourceID string
	AmountCents                  int64
	CreatedAt                    time.Time
	DeletedAt                    gorm.DeletedAt // 有这个类型，每条语句自动挂上 deleted_at IS NULL
}

func (Notification) TableName() string { return "homeos_notification" }
func dryDB() *gorm.DB {
	db, e := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_finance:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if e != nil {
		panic(e)
	}
	return db
}

func main() {
