	notes = append(notes, note{"A-19", famA, "system", "homeos", "release#19", 0, tw, time.Time{}, time.Time{}}, note{"A-20", famA, "system", "homeos", "release#20", 0, tw, time.Time{}, time.Time{}})
	all, fams := len(notes), []string{famA, famB, famC}

