	fmt.Printf("  表共 %d 行；分型行数：budget_alert %d｜system %d｜reminder %d；未读按家庭：", all, len(filt(notes, func(x note) bool { return x.kind == "budget_alert" })), len(filt(notes, func(x note) bool { return x.kind == "system" })), len(filt(notes, func(x note) bool { return x.kind == "reminder" })))
	for _, f := range fams {
		fmt.Printf("%s %d｜", f, unread(f))
	}
	fmt.Printf("（unread() 一个来源，三个出口 %s）\n  fam-A 未读列表（(created_at,id) 倒序，翻页就按这个顺序）：%s\n", same3(famA), cat(unreads(famA)))
	fmt.Printf("  同秒双胞胎：%s 与 %s 的 created_at 都是 %s → 游标必须带 id，只带时间戳会在这一秒上漏一条\n  limit 口径：1..50（越界 400 给合法形状，不静默回落）；游标口径：<RFC3339Nano>_<id>；批量已读必带 family_id + kind + 截止时刻\n", "A-19", "A-20", hm(tw))
	fmt.Printf("  未读 COUNT 的真 SQL（DryRun；family_id 恒在且只从会话取，deleted_at IS NULL 自动挂上）：\n    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Notification{}).Where("family_id = ? AND read_at IS NULL AND recalled_at IS NULL", famA).Count(new(int64))
	}))

	hdr("2. ❌ offset 分页遇上「边读边已读」：漏掉的具体几条真跑出来")
	limit := 5
	shO, missO, pgO := walk(unreads(famA), limit, 0)
	for i, x := range missO {
		fmt.Printf("      漏掉第 %d 条：%s %-13s created_at=%s｜read_at=%s｜recalled_at=%s → 客户端翻不到它，未读数却一直挂着它\n", i+1, x.id, x.kind, hm(x.at), ts(x.read), ts(x.recall))
	}
	fmt.Printf("    offset 版翻页 SQL 原文（第 3 页那一支，LIMIT %d OFFSET %d）：\n      %s\n", limit, 2*limit, db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Notification{}).Where("family_id = ? AND read_at IS NULL AND recalled_at IS NULL", famA).Order("created_at DESC, id DESC").Limit(limit).Offset(2 * limit).Find(&[]Notification{})
	}))
	fmt.Printf("  结果：翻了 %d 页、标读 %d 条，但 fam-A 原有未读 %d 条 → 漏掉 %d 条：%s\n  事故点：每标读一页，未读集就少几行，而 OFFSET 还在按「页号*5」往前推 → 被跳过的行永远翻不到；第 2 页只回 4 条（< limit）客户端判定「到末页了」，剩下的未读再也点不到\n", pgO, len(shO), len(shO)+len(missO), len(missO), cat(missO))

	hdr("3. ✅ 游标分页同一场景：逐条齐，一条不漏")
	shC, missC, pgC := walk(unreads(famA), limit, 2)
	fmt.Printf("  游标逐页推进（上一页最后一行的 (created_at,id)）：第 1 页游标＝首页无 → 第 2 页游标＝%s\n  游标版游标推进不依赖行集大小：标读只是让行离开结果集，游标本身还在原来的全序位置上 → 不会跳过任何一行\n", cur{shC[limit-1].at, shC[limit-1].id}.str())
