	hdr("4. 列表入参与跨家庭：非法一律 400 给合法形状，跨家用游标也捞不到别家一行")
	tamper := cur{unreads(famB)[0].at, unreads(famB)[0].id} // 拿别家一行的游标来翻 fam-A 的列表
	cases := []struct {
