	}{{0, "", "400"}, {500, "", "400"}, {5, "not-a-cursor", "400"}, {5, "2026-13-45T99:00:00+08:00_A-06", "400"}, {5, "2026-12-08T08:42:00+08:00_A-06", "200"}, {5, tamper.str(), "200"}}
