	fmt.Println("  真环境要复跑：第 3 节的游标 SELECT 与第 5 节的批量 UPDATE 原句打到 Postgres，用 RETURNING id 复核 affected；(family_id, created_at, id) 建复合索引后 EXPLAIN 确认走索引而不是全表扫 + 外部排序。")
	fmt.Println("\n=== W51 d17 到此结束 ===")
	fmt.Println("明天把 W51 收口：并发投递 + 并发已读 + 并发撤回混跑一遍，输出收敛成确定字节，终态逐行列出，并当场验「未读一个来源、三出口同值」这条判据。")
}

// =====================================================================
// W51 d18（收口）：未读数一致性并发自测 —— 并发投递 + 并发已读 + 并发撤回混跑，收敛后逐行终态与未读数互相咬合。
// 本机没有 PostgreSQL / Docker 守护进程 / nginx，分工写清楚：真实 SQL —— 下面每条 INSERT / UPDATE / SELECT 的语句文本由 GORM DryRun 现场生成（postgres 方言、DisableAutomaticPing、NowFunc 固定 2026-12-09 09:00），只出文本不落库；内存模拟 —— homeos_notification 一张带互斥锁的内存表，投递/点名已读/撤回全部真并发跑，未读数、行数、差值一律现场算，没有写死的结论。
// 确定性怎么来的：① 幂等键 (source_system, source_id, kind) 由唯一约束兜底（内存里就是 store.byKey），已读/撤回都带谓词 CAS（条件不满足就一行不改）→ 无论怎么调度，收敛后的终态是同一份；② 行 id 由事件自带、不是落库时才分配 → 并发插入顺序进不了行集；③ 每路 worker 的结果先收集，wg.Wait() 后按 worker 编号定序打印；「哪一路抢到首次过渡」是调度的产物，只做合计、不印到行上。
// 真环境要复跑：① 把 uniq(source_system, source_id, kind) WHERE deleted_at IS NULL 真建起来，第 2 节 23 路必须只落 7 行（RETURNING 空数组即命中）；② 已读/撤回与 unread 的 COUNT 同事务，用 RETURNING id 复核第 3 节两个合计数；③ 三个出口的数与那条 SELECT count 在真库逐一相等。
// 口径逐字承接 S11 d33 / W51 d13~d17：unread(fam, user) 是唯一未读来源（角标/列表/动作返回三出口读它）；撤回不删行（recalled_at + 出口过滤）；写接口带 client_request_id；跨家庭 404 不是 403；非法参数 400 给合法形状不回落；金额一律 *_cents。
// 学员侧跑法：cd homecube/server && go run ./lab/s12/d18
// =====================================================================
package main

import (
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
	"gorm.io/gorm/clause"
	gormlogger "gorm.io/gorm/logger"
)

var famLoc = time.FixedZone("CST", 8*3600) // 家庭时区＝东八区固定偏移（不查系统 tz 库，两次跑字节一致）
var fixedNow = day0(2026, 12, 9).Add(9 * time.Hour)
var mark, yes = map[bool]string{true: "✅", false: "❌"}, map[bool]int{true: 1, false: 0}

const famA, famB, uDad, uKid, uMom, sep = "fam-A", "fam-B", "u-dad", "u-kid", "u-mom", "|"

var famOf = map[string]string{uDad: famA, uKid: famA, uMom: famB}
var kindOK = map[string]bool{"budget_alert": true, "system": true, "reminder": true}

func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }
func hm(t time.Time) string      { return t.In(famLoc).Format("2006-01-02 15:04") }
func ts(t time.Time) string      { return map[bool]string{true: "—（NULL）", false: hm(t)}[t.IsZero()] }
func hdr(s string)               { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string       { return fmt.Sprintf("%d.%02d 元", c/100, c%100) }
func wd(s string) int            { return (len(s) + len([]rune(s))) / 2 }
func pad(s string, n int) string { return s + strings.Repeat(" ", max(0, n-wd(s))) }
func cut(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n-1]) + "…"
}

// ---------- 内存表：read_at / recalled_at 的零值就是 SQL 里的 NULL；counted() 是全项目唯一未读谓词（d16/d17 口径） ----------
type note struct {
	id, fam, user, kind, sys, sid string
	cents                         int64
	at, read, recall              time.Time
}

func counted(n note) bool { return n.read.IsZero() && n.recall.IsZero() }

// Ev：投递事件。行 id 由事件自带 → 并发落库的先后进不了行集，终态表两次跑逐字节一致。
type Ev struct {
	id, fam, user, kind, sys, sid string
	cents                         int64
	at                            time.Time
}

func (e Ev) dedup() string { return e.sys + sep + e.sid + sep + e.kind }

// store：唯一的一张表。deliver / markRead / recall 三个变更入口共用一把锁；
// 未读数只有 unread() 一处实现，三个出口都是它的薄包装——判据③当场验的就是这个形状。
type store struct {
	mu        sync.Mutex
	rows      []note
	byKey     map[string]string // 幂等键 → 首次那行的 id：等价 uniq(source_system, source_id, kind)
	inserts   int
	hits      int
	cridDone  map[string]bool // crid 幂等表：read|<crid> / recall|<crid>
	markAff   int
	recallAff int
}

func newStore() *store { return &store{byKey: map[string]string{}, cridDone: map[string]bool{}} }

var unreadCalls int

// deliver：落库的唯一入口。先过三道门（收件人归属 / kind / client_request_id），再按幂等键落；
// 命中同键原样返回第一次那条、一行都不新增（等价 ON CONFLICT DO NOTHING）。
func (s *store) deliver(e Ev, crid string) (int, string) {
	if famOf[e.user] != e.fam {
		return 404, "" // 收件人不在投递目标家庭：404 不给 403（403 等于承认别家有这个人）
	}
	if !kindOK[e.kind] {
		return 400, "" // kind 非法：合法形状 ∈ budget_alert / system / reminder，不回落、不置空
	}
	if crid == "" {
		return 400, "" // 缺 client_request_id：写接口必须带
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if id, ok := s.byKey[e.dedup()]; ok {
		s.hits++
		return 200, id
	}
	s.byKey[e.dedup()] = e.id
	s.rows = append(s.rows, note{e.id, e.fam, e.user, e.kind, e.sys, e.sid, e.cents, e.at, time.Time{}, time.Time{}})
	s.inserts++
	return 201, e.id
}

// markRead：点名已读（会话 fam+user 都从会话取）。CAS 谓词：行在本家庭、收件人是自己、且 counted()（已撤回的不许标读）。
// 同 crid 并发重放合计只执行一次——「谁先」是调度的产物，「合计」不是。
func (s *store) markRead(sessFam, sessUser, wantFam, crid string, ids []string, at time.Time) (int, int) {
	if crid == "" {
		return 400, 0
	}
	if wantFam != sessFam {
		return 404, 0 // 会话外的 family_id：家内查不到这个范围 → 404（不给 403）
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.cridDone["read|"+crid] {
		return 200, 0 // 幂等命中：同 crid 重放，一行不再改
	}
	n := 0
	for _, id := range ids {
		for i := range s.rows {
			if s.rows[i].id == id && s.rows[i].fam == sessFam && s.rows[i].user == sessUser && counted(s.rows[i]) {
				s.rows[i].read = at
				n++
			}
		}
	}
	s.cridDone["read|"+crid], s.markAff = true, s.markAff+n
	return 200, n
}

// recall：撤回不删行，只写 recalled_at（d16 口径）；CAS 谓词 recalled_at IS NULL——已撤回的再撤是 no-op。
func (s *store) recall(sessFam, sessUser, wantFam, crid, id string, at time.Time) (int, int) {
	if crid == "" {
		return 400, 0
	}
	if wantFam != sessFam {
		return 404, 0
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.cridDone["recall|"+crid] {
		return 200, 0
	}
	s.cridDone["recall|"+crid] = true
	for i := range s.rows {
		if s.rows[i].id == id && s.rows[i].fam == sessFam && s.rows[i].user == sessUser {
			if !s.rows[i].recall.IsZero() {
				return 200, 0 // 已是撤回态
			}
			s.rows[i].recall = at
			s.recallAff++
			return 200, 1
		}
	}
	return 404, 0 // 该范围内查不到这行（不存在 / 属于别家，一律 404）
}

// unread：全项目唯一的未读来源（d14 定名）。每次调用计入 unreadCalls——收口时打印真实执行次数。
func (s *store) unread(fam, user string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	unreadCalls++
	c := 0
	for _, x := range s.rows {
		if x.fam == fam && x.user == user && counted(x) {
			c++
		}
	}
	return c
}

func (s *store) snapshot() map[string]note { // id → 行副本：对账用的「阶段起点状态」
	s.mu.Lock()
	defer s.mu.Unlock()
	out := map[string]note{}
	for _, x := range s.rows {
		out[x.id] = x
	}
	return out
}

// 三个出口：函数体各一行 return unread(fam, user)，谁都不自己数（判据③的结构保证）。
func exitBadge(s *store, fam, u string) int { return s.unread(fam, u) }
func exitList(s *store, fam, u string) int  { return s.unread(fam, u) }
func exitAct(s *store, fam, u string) int   { return s.unread(fam, u) }
func same3(s *store, fam, u string) string {
	b, l, a := exitBadge(s, fam, u), exitList(s, fam, u), exitAct(s, fam, u)
	return fmt.Sprintf("角标 %d｜列表 %d｜动作返回 %d %s", b, l, a, mark[b == l && l == a])
}

// ---------- 混跑计划：投递 worker → 幂等键；已读/撤回任务表（声明序即打印序，与调度无关） ----------
type readJob struct {
	crid, wantFam string
	ids           []string
}
type recallJob struct {
	crid, wantFam, id string
}

func main() {
	db, cnt6 := dryDB(), new(int64)
	evs := []Ev{
		{"A-06", famA, uDad, "budget_alert", "finance", "finance.budget.exceeded|fam-A|2026-12", 386400, day0(2026, 12, 8).Add(21 * time.Hour)},
		{"A-07", famA, uDad, "reminder", "due-center", "recurring.reminder|rent-house@2026-12-09", 0, day0(2026, 12, 9)},
		{"A-08", famA, uDad, "system", "homeos", "release-1.8.0", 0, day0(2026, 12, 8).Add(18 * time.Hour)},
		{"A-09", famA, uKid, "reminder", "due-center", "recurring.reminder|tuition-learn@2026-12-10", 30000, day0(2026, 12, 8).Add(22 * time.Hour)},
		{"A-10", famA, uDad, "system", "homeos", "backup-window", 0, day0(2026, 12, 9).Add(7 * time.Hour)},
		{"B-02", famB, uMom, "budget_alert", "finance", "finance.budget.exceeded|fam-B|2026-12", 540000, day0(2026, 12, 8).Add(21 * time.Hour)},
		{"B-03", famB, uMom, "system", "homeos", "tz-fix-notice", 0, day0(2026, 12, 6).Add(9 * time.Hour)},
	}
	mult := []int{6, 5, 4, 3, 2, 2, 1} // 7 个键共投 23 次：同键最多 6 路抢一个约束位
	dKeys := []string{}
	byDedup := map[string]Ev{}
	for i, e := range evs {
		byDedup[e.dedup()] = e
		for j := 0; j < mult[i]; j++ {
			dKeys = append(dKeys, e.dedup())
		}
	}
	reads := []readJob{ // 任务表就是混跑计划：目标集合互相重叠（A-06/A-07/A-08 被三路同时点名），read-1 与它的重放同 crid
		{"read-1", famA, []string{"A-01", "A-03", "A-06", "A-07"}},
		{"read-2", famA, []string{"A-06", "A-07", "A-08"}},
		{"read-3", famA, []string{"A-07", "A-08"}},
		{"read-1", famA, []string{"A-01", "A-03", "A-06", "A-07"}}, // 同 crid 并发重放：合计只执行一次
		{"read-4", famB, []string{"B-01"}},                         // 会话 fam-A 想标 fam-B → 404
		{"", famA, []string{"A-08"}},                               // 缺 crid → 400
	}
	recalls := []recallJob{ // recall-1 与它的重放同 crid；A-03 已撤回（no-op）；GHOST 不存在 → 404
		{"recall-1", famA, "A-02"}, // A-02 是「已读」行：撤回不要求先未读，但撤回≠已读（recalled_at 单独一列）
		{"recall-2", famA, "A-03"},
		{"recall-1", famA, "A-02"},
		{"recall-4", famA, "GHOST"},
		{"recall-5", famB, "B-01"}, // 会话 fam-A 想撤 fam-B 的行 → 404
	}

	st := newStore()
	for _, x := range []note{ // 种子：d13~d16 跑下来的家底，状态五花八门（终态表才杀得住）
		{"A-01", famA, uDad, "budget_alert", "finance", "finance.budget.exceeded|2026-11", 328400, day0(2026, 12, 1).Add(9 * time.Hour), time.Time{}, time.Time{}},
		{"A-02", famA, uDad, "system", "homeos", "announcement-07", 0, day0(2026, 12, 2).Add(8 * time.Hour), day0(2026, 12, 2).Add(20 * time.Hour), time.Time{}},
		{"A-03", famA, uDad, "reminder", "due-center", "recurring.reminder|pet-vet@2026-12-03", 0, day0(2026, 12, 3), time.Time{}, day0(2026, 12, 4)},
		{"A-04", famA, uKid, "reminder", "due-center", "recurring.reminder|tuition-learn@2026-12-05", 30000, day0(2026, 12, 5), time.Time{}, time.Time{}},
		{"B-01", famB, uMom, "system", "homeos", "maintenance-window", 0, day0(2026, 12, 4).Add(10 * time.Hour), time.Time{}, time.Time{}},
	} {
		st.rows, st.byKey[x.sys+sep+x.sid+sep+x.kind] = append(st.rows, x), x.id
	}
	checkBad := 0 // 「三个出口不同值」的违例计数：每次 checkpoint 现比现加
	ck := func(fam, u string) string {
		s := same3(st, fam, u)
		checkBad += yes[!strings.Contains(s, "✅")]
		return s
	}

	// ---------- 1 ----------
	hdr("1. 现场：唯一未读来源、一份混跑计划、一条 SELECT")
	startDad := st.unread(famA, uDad)
	fmt.Printf("  口径一句话：read_at IS NULL 且 recalled_at IS NULL 且 family_id=会话家庭 且 recipient_user_id=自己；谓词只有 counted() 一处，实现只有 unread(fam, user)\n  三个出口（首页角标 / 列表页 total_unread / 写接口返回体）都是 unread() 的薄包装：起始 %s\n", ck(famA, uDad))
	fmt.Printf("  种子 %d 行（fam-A/u-dad %d｜fam-A/u-kid %d｜fam-B/u-mom %d），混跑计划：投递 %d 路（7 个幂等键、同键最多 %d 路抢同一个约束位）· 已读 %d 路（含同 crid 并发重放 %d 路、跨家庭 %d 路、缺 crid %d 路）· 撤回 %d 路（含同 crid 重放 1 路、撤已撤回 1 路、不存在 404 1 路、跨家庭 1 路）\n",
		len(st.rows), startDad, st.unread(famA, uKid), st.unread(famB, uMom), len(dKeys), mult[0], len(reads), 1, 1, 1, len(recalls))
	fmt.Printf("  未读 COUNT 的唯一 SQL（DryRun；family_id 恒在且只从会话取；deleted_at IS NULL 由 GORM 自动挂上）：\n    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Notification{}).Where("family_id = ? AND recipient_user_id = ? AND read_at IS NULL AND recalled_at IS NULL", famA, uDad).Count(cnt6)
	}))

	// ---------- 2. 并发投递 ----------
	hdr("2. 并发投递 23 路：7 个幂等键，同键最多 6 路同时抢")
	type dres struct {
		w     int
		key   string
		code  int
		gotID string
	}
	out := make([]dres, len(dKeys))
	var wg sync.WaitGroup
	for i := range dKeys {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			c, id := st.deliver(byDedup[dKeys[i]], fmt.Sprintf("deliver-w%02d", i))
			out[i] = dres{i, dKeys[i], c, id}
		}(i)
	}
	wg.Wait()
	sort.Slice(out, func(i, j int) bool { return out[i].w < out[j].w }) // 稳定键＝worker 编号 → 打印与调度无关
	fmt.Println("  " + pad("worker", 8) + pad("幂等键", 50) + pad("返回行 id", 12) + "行 id 是否等于该键首行（201/200 的「谁抢到首插」随调度，这里不印返码，只印调度无关的量）")
	mism := 0
	for _, r := range out {
		mism += yes[r.gotID != byDedup[r.key].id]
		fmt.Println("  " + pad(fmt.Sprintf("w%02d", r.w), 8) + pad(cut(r.key, 48), 50) + pad("id="+r.gotID, 12) + mark[r.gotID == byDedup[r.key].id])
	}
	dadNew := 0
	for _, e := range evs {
		dadNew += yes[e.fam == famA && e.user == uDad]
	}
	dadNow := st.unread(famA, uDad)
	fmt.Printf("  汇总（全现算）：入口 %d 路 → 真新增 %d 行 · 幂等命中 %d 次 · 表 %d 行（种子 5 + 真新增 %d）；返回行 id 与该键首行不符的 %d 路 %s\n",
		len(out), st.inserts, st.hits, len(st.rows), st.inserts, mism, mark[mism == 0])
	fmt.Printf("  投递不虚增未读：fam-A/u-dad 未读 %d → %d，差 %d == 计划里投给 (fam-A, %s) 且计入未读的新行数 %d %s｜%s\n",
		startDad, dadNow, dadNow-startDad, uDad, dadNew, mark[dadNow-startDad == dadNew], ck(famA, uDad))
	badK, badC, badF := Ev{"X-01", famA, uDad, "budget", "finance", "x", 0, fixedNow}, Ev{"X-02", famA, uDad, "system", "homeos", "x2", 0, fixedNow}, Ev{"X-03", famA, uMom, "system", "homeos", "x3", 0, fixedNow}
	rowsBefore := len(st.rows)
	cK, _ := st.deliver(badK, "w-bad-kind")
	cC, _ := st.deliver(badC, "")
	cF, _ := st.deliver(badF, "w-bad-fam")
	fmt.Printf("  投递前三道门（串行真跑，返码与入参一一对应）：kind=\"budget\" → %d（合法形状 ∈ budget_alert/system/reminder，不回落）；crid 缺 → %d；收件人 u-mom 挂 fam-A → %d（404 不是 403）\n    三门期望 400/400/404 → %s；挡下后表行数 %d → %d %s（被门挡下的一次落库都没有）\n", cK, cC, cF, mark[cK == 400 && cC == 400 && cF == 404], rowsBefore, len(st.rows), mark[len(st.rows) == rowsBefore])

	// ---------- 3. 并发已读 + 并发撤回 ----------
	hdr("3. 并发已读 + 并发撤回混跑：目标重叠、同 crid 重放、跨家庭与缺参都掺进来")
	pre := st.snapshot() // 阶段起点快照：后面的「期望」全部从这份谓词算出来，不是抄的
	type ores struct {
		w    int
		op   string
		crid string
		tgt  string
		code int
	}
	jobs := []ores{}
	for i, r := range reads {
		jobs = append(jobs, ores{100 + i, "read", r.crid, strings.Join(r.ids, ","), 0})
	}
	for i, r := range recalls {
		jobs = append(jobs, ores{200 + i, "recall", r.crid, r.id, 0})
	}
	sort.Slice(jobs, func(i, j int) bool { return jobs[i].w < jobs[j].w })
	res := make([]int, len(jobs))
	aff := make([]int, len(jobs))
	var wg2 sync.WaitGroup
	for i := range jobs {
		wg2.Add(1)
		go func(i int) {
			defer wg2.Done()
			j := jobs[i]
			switch {
			case j.op == "read" && i < len(reads):
				res[i], aff[i] = st.markRead(famA, uDad, reads[i].wantFam, reads[i].crid, reads[i].ids, fixedNow)
			case j.op == "recall" && i >= len(reads):
				k := i - len(reads)
				res[i], aff[i] = st.recall(famA, uDad, recalls[k].wantFam, recalls[k].crid, recalls[k].id, fixedNow)
			}
		}(i)
	}
	wg2.Wait()
	fmt.Println("  " + pad("编号", 8) + pad("动作", 12) + pad("client_request_id", 18) + pad("点名行", 26) + "HTTP（每路 affected 随「谁先抢到」变 → 不进这张表，见下方合计对账）")
	for i, j := range jobs {
		fmt.Println("  " + pad(fmt.Sprintf("j%02d", j.w), 8) + pad(j.op, 12) + pad(map[bool]string{true: "（空）", false: j.crid}[j.crid == ""], 18) + pad(j.tgt, 26) + fmt.Sprint(res[i]))
	}
	// 期望（由计划谓词现算）：起点未读且被任一路点名的行，恰过渡一次。
	expMark, expRecall := 0, 0
	seenID := map[string]bool{}
	for _, r := range reads {
		if r.wantFam != famA || r.crid == "" {
			continue // 跨家庭与缺 crid 的一行都不动
		}
		for _, id := range r.ids {
			if n, ok := pre[id]; ok && !seenID["m|"+id] && n.user == uDad {
				seenID["m|"+id] = true
				expMark += yes[counted(n)]
			}
		}
	}
	for _, r := range recalls {
		if r.wantFam != famA || r.crid == "" {
			continue
		}
		if n, ok := pre[r.id]; ok && !seenID["r|"+r.id] && n.user == uDad {
			seenID["r|"+r.id] = true
			expRecall += yes[n.recall.IsZero()]
		}
	}
	fmt.Printf("  对账（计划算出的期望 vs 真并发跑出的合计）：markAff=%d == 期望 %d %s · recallAff=%d == 期望 %d %s\n    同 crid 的两路 read-1 / 两路 recall-1 各自返码都是 200，其中一路被幂等表挡下（affected=0）——「谁抢到首过渡」随调度变（所以每路 affected 不进上表），但合计只计一次，与期望咬合\n",
		st.markAff, expMark, mark[st.markAff == expMark], st.recallAff, expRecall, mark[st.recallAff == expRecall])
	fmt.Printf("  混跑后 %s｜fam-A/u-kid %d（没人替他点已读）｜fam-B/u-mom %d（跨家庭两路 404 一行没动）\n", ck(famA, uDad), st.unread(famA, uKid), st.unread(famB, uMom))

	// ---------- 4. 终态表 ----------
	hdr("4. 收敛后的终态逐行列出：未读数必须与每一行的状态互相咬合")
	rows := append([]note{}, st.rows...)
	sort.Slice(rows, func(i, j int) bool { return rows[i].id < rows[j].id })
	fmt.Println("  " + pad("id", 6) + pad("kind", 13) + pad("家庭", 7) + pad("收件人", 8) + pad("幂等键", 44) + pad("read_at", 17) + pad("recalled_at", 17) + pad("计入未读", 9) + "amount_cents")
	type scope struct{ fam, user string }
	sc0 := []scope{{famA, uDad}, {famA, uKid}, {famB, uMom}}
	tally := map[string][3]int{}
	for _, x := range rows {
		k := x.fam + sep + x.user
		t := tally[k]
		t[0] += yes[counted(x)]
		t[1] += yes[!x.read.IsZero()]
		t[2] += yes[!x.recall.IsZero()]
		tally[k] = t
		fmt.Println("  " + pad(x.id, 6) + pad(x.kind, 13) + pad(x.fam, 7) + pad(x.user, 8) + pad(cut(x.sys+sep+x.sid+sep+x.kind, 42), 44) + pad(ts(x.read), 17) + pad(ts(x.recall), 17) +
			pad(map[bool]string{true: "✅", false: "—"}[counted(x)], 9) + fmt.Sprint(x.cents))
	}
	scopeOk := 0
	for _, sc := range sc0 {
		k := sc.fam + sep + sc.user
		one, two := st.unread(sc.fam, sc.user), tally[k][0]
		scopeOk += yes[one == two]
		fmt.Printf("  自洽（%s）：unread()=%d == 终态表现数「计入未读」=%d %s（未读 %d / 已读 %d / 撤回 %d；撤回行留在表里不删，也不混进已读）\n",
			k, one, two, mark[one == two], tally[k][0], tally[k][1], tally[k][2])
	}
	phys := len(rows)
	fmt.Printf("  物理行数全程只有两条路：种子 %d + 投递真新增 %d = %d 行，已读/撤回一行没删 %s；unread() 到此真实执行 %d 次，出口违例 %d %s\n",
		5, st.inserts, phys, mark[phys == 5+st.inserts], unreadCalls, checkBad, mark[checkBad == 0])
	readNil, recalledUnread := 0, 0
	for _, x := range rows {
		if x.fam == famA && x.user == uDad {
			readNil += yes[x.read.IsZero()]
			recalledUnread += yes[x.read.IsZero() && !x.recall.IsZero()]
		}
	}
	truth := st.unread(famA, uDad)
	fmt.Printf("  ❌ 反例（第二份账长歪的样子，只算不落地、不喂任何出口）：若角标自数「只滤 read_at IS NULL、漏 recalled_at IS NULL」→ fam-A/u-dad 会报 %d，真值 %d，差 %d == 恰是那 %d 行「已撤回且从未读过」——d14 三件套在并发混跑下同样当场露馅\n",
		readNil, truth, readNil-truth, recalledUnread)

	// ---------- 5. 抢跑复验 ----------
	hdr("5. 收敛不是运气：同一行 20 路抢标已读、同一键 20 路抢投递，各复跑 20 轮")
	okMark, okDel := 0, 0
	for r := 0; r < 20; r++ {
		ms := newStore()
		ms.rows = []note{{"R-01", famA, uDad, "system", "homeos", fmt.Sprintf("probe-mark-r%d", r), 0, fixedNow, time.Time{}, time.Time{}}}
		var wg3 sync.WaitGroup
		var mu sync.Mutex
		sum := 0
		for i := 0; i < 20; i++ {
			wg3.Add(1)
			go func(i int) {
				defer wg3.Done()
				_, a := ms.markRead(famA, uDad, famA, fmt.Sprintf("cr-r%d-w%d", r, i), []string{"R-01"}, fixedNow)
				mu.Lock()
				sum += a
				mu.Unlock()
			}(i)
		}
		wg3.Wait()
		okMark += yes[sum == 1 && !ms.rows[0].read.IsZero()]
		ds := newStore()
		e := Ev{"R-01", famA, uDad, "system", "homeos", fmt.Sprintf("probe-deliver-r%d", r), 0, fixedNow}
		var wg4 sync.WaitGroup
		for i := 0; i < 20; i++ {
			wg4.Add(1)
			go func(i int) {
				defer wg4.Done()
				ds.deliver(e, fmt.Sprintf("cr-r%d-w%d", r, i))
			}(i)
		}
		wg4.Wait()
		okDel += yes[ds.inserts == 1 && len(ds.rows) == 1]
	}
	fmt.Printf("  每轮结论只取「与调度无关」的合计：同一行 20 路并发标已读 → 真过渡合计恰为 1（其余 19 路锁内读到 read_at 非空、affected=0）：成立 %d/20 轮 %s\n", okMark, mark[okMark == 20])
	fmt.Printf("  同一幂等键 20 路并发投递 → 表里恰 1 行、inserts 恰 1：成立 %d/20 轮 %s。「哪一路赢」每轮都可能不同，程序不印它——那只是这次调度的产物，印出来就成了第二次账\n", okDel, mark[okDel == 20])

	// ---------- 6. DryRun ----------
	hdr("6. 三条写路径与一条读路径的 Postgres 原文（DryRun；本机不落库）")
	fmt.Printf("  投递（唯一入口 + ON CONFLICT DO NOTHING，等价 store.byKey 那把 map 键）：\n    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		r := Notification{ID: "A-06", FamilyID: famA, RecipientUserID: uDad, Kind: "budget_alert", SourceSystem: "finance",
			SourceID: "finance.budget.exceeded|fam-A|2026-12", DedupKey: evs[0].dedup(), ClientRequestID: "deliver-w00", AmountCents: evs[0].cents, CreatedAt: evs[0].at}
		return tx.Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "source_system"}, {Name: "source_id"}, {Name: "kind"}}, DoNothing: true}).Create(&r)
	}))
	fmt.Printf("  点名已读（family_id 与收件人都来自会话；read_at IS NULL AND recalled_at IS NULL 就是 CAS 谓词；真库补 RETURNING id 即第 3 节合计）：\n    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Notification{}).Where("family_id = ? AND recipient_user_id = ? AND id IN (?) AND read_at IS NULL AND recalled_at IS NULL", famA, uDad, []string{"A-01", "A-06", "A-07", "A-08"}).UpdateColumn("read_at", fixedNow)
	}))
	fmt.Printf("  撤回（不删行，只写 recalled_at；谓词挡「撤已撤回」）：\n    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Notification{}).Where("family_id = ? AND recipient_user_id = ? AND id = ? AND recalled_at IS NULL", famA, uDad, "A-02").UpdateColumn("recalled_at", fixedNow)
	}))
	fmt.Printf("  列表页（游标翻页与 limit 永远不参与未读口径——第 1 节那条 SELECT count 才是数）：\n    %s\n", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
		return tx.Model(&Notification{}).Where("family_id = ? AND recipient_user_id = ? AND read_at IS NULL AND recalled_at IS NULL", famA, uDad).Order("created_at DESC, id DESC").Limit(20).Find(&[]Notification{})
	}))

	// ---------- 7. 判据③ ----------
	hdr("7. 判据③「未读数只有一个来源，三个出口同值」逐条打 ✅（每条的数都来自上面的真跑）")
	b, l, a := exitBadge(st, famA, uDad), exitList(st, famA, uDad), exitAct(st, famA, uDad)
	// 阶段起点快照里 fam-B/u-mom 的未读行数：混跑后必须还是这个数（跨家庭与缺参的一行都不许误伤）。
	preMom := 0
	for _, n := range pre {
		if n.fam == famB && n.user == uMom && counted(n) {
			preMom++
		}
	}
	cross404, bad400 := 0, 0
	for i, j := range jobs {
		cross404 += yes[res[i] == 404]
		bad400 += yes[res[i] == 400 && j.crid == ""]
	}
	crossCnt, crossAll404 := 0, 0
	for i, r := range reads { // jobs 按 w 定序后：前 len(reads) 路就是 reads 原序，其后是 recalls 原序
		if r.wantFam != famA {
			crossCnt++
			crossAll404 += yes[res[i] == 404]
		}
	}
	for k, r := range recalls {
		if r.wantFam != famA {
			crossCnt++
			crossAll404 += yes[res[len(reads)+k] == 404]
		}
	}
	momUntouched := st.unread(famB, uMom) == preMom
	items := []struct {
