	}{
		{"唯一谓词：未读判定只有 counted() 一处", scopeOk == len(sc0), fmt.Sprintf("三个收件范围的 unread() 与终态表现数逐行咬合：%d/%d 全对（第 4 节）", scopeOk, len(sc0))},
