type Feed struct {
	ID, Topic, Kind, FamilyID, MemberID, DisplayName, Currency, SourceSystem, SourceID, DedupKey, ClientRequestID, WrittenBy string
	AmountCents                                                                                                              int64
	OccurredAt, CreatedAt                                                                                                    time.Time
