}
type Audit struct {
	ID, FamilyID, Actor, Action, EntityID, Before, After, WrittenBy string
	At, RetainUntil                                                 time.Time
}
type Txn struct {
	ID, FamilyID, Kind, MemberID, DisplayName, Currency, ClientRequestID string
	Cents                                                                int64
	At                                                                   time.Time
	DeletedAt                                                            *time.Time
}
type Ev struct {
	Topic, FamilyID, MemberID, DisplayName, Kind, Actor, Currency, SourceSystem, SourceID, ClientRequestID, Before, After string
	Cents                                                                                                                 int64
	At                                                                                                                    time.Time
}

func (Feed) TableName() string  { return "homeos_activity" }
func (Audit) TableName() string { return "homeos_audit_log" }
func (Txn) TableName() string   { return "finance_transaction" }

var feed []Feed
var audit []Audit
var ledger = []Txn{{"T-30", famA, "expense", "M-dad", "爸爸", "CNY", "fin-T-30", 128000, day(2026, 10, 12), nil}}
var subs = map[string][]func(Ev) int{}
var delivered = map[string]int{}
var busPub int

func day(y, m, d int) time.Time {
	return time.Date(y, time.Month(m), d, 9, 0, 0, 0, fixedNow.Location())
}
func hdr(s string)          { fmt.Printf("\n===== %s =====\n", s) }
func abs(v int64) int64     { return map[bool]int64{true: -v, false: v}[v < 0] }
func at(t time.Time) string { return t.Format("2006-01-02 15:04") } // 布局年是 2006，写成 2026 会打出 19196 年
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs(c)/100, abs(c)%100)
}
func orE(s string) string { return map[bool]string{true: "（空）", false: s}[s == ""] }

// tsStr：软删列的打印口径——NULL（没删）或 at() 那个格式的时间戳。
func tsStr(t *time.Time) string {
	if t == nil {
		return "NULL"
	}
	return at(*t)
}
func inList(s string, l []string) bool {
	for _, x := range l {
		if s == x {
			return true
		}
	}
	return false
}
func (e Ev) dedup() string                                { return e.SourceSystem + sep + e.SourceID + sep + e.Kind }
func sub(t string, f func(Ev) int)                        { subs[t] = append(subs[t], f) }
func sqlOf(db *gorm.DB, f func(*gorm.DB) *gorm.DB) string { return db.ToSQL(f) }

// publish：全项目唯一的事件出口，业务面手里只有它，没有流表句柄。返回值＝两个投影器各自的 append 行数（现数）。
func publish(e Ev) (int, int) {
	busPub++
	delivered[e.dedup()]++
	f0, a0 := len(feed), len(audit)
	for _, s := range subs[e.Topic] {
		s(e)
	}
	return len(feed) - f0, len(audit) - a0
}

// feedProjector：homeos_activity 的唯一写入者；内部变更类 topic（改预算）不落，用户的流只放用户看得懂的。
func feedProjector(e Ev) int {
	if !userTopic[e.Topic] {
		return 0
	}
	for _, f := range feed {
		if f.DedupKey == e.dedup() {
			return 0 // 同幂等键命中 → no-op，等价 ON CONFLICT DO NOTHING
		}
	}
	feed = append(feed, Feed{ID: fmt.Sprintf("AF-%02d", len(feed)+1), Topic: e.Topic, Kind: e.Kind, FamilyID: e.FamilyID, MemberID: e.MemberID,
		DisplayName: e.DisplayName, Currency: e.Currency, AmountCents: e.Cents, SourceSystem: e.SourceSystem, SourceID: e.SourceID,
		DedupKey: e.dedup(), ClientRequestID: e.ClientRequestID, WrittenBy: projector, OccurredAt: e.At, CreatedAt: fixedNow})
	return 1
}

// auditProjector：homeos_audit_log 的唯一写入者，同样按「同事实同前后值」去重；soft_delete_projector 只置删不删行。
func auditProjector(e Ev) int {
	if e.Before == "" {
		return 0
	}
	for _, a := range audit {
		if a.Action+sep+a.EntityID+sep+a.Before+sep+a.After == e.Topic+sep+e.SourceID+sep+e.Before+sep+e.After {
			return 0
		}
	}
	audit = append(audit, Audit{ID: fmt.Sprintf("AL-%02d", len(audit)+1), FamilyID: e.FamilyID, Actor: e.Actor, Action: e.Topic,
		EntityID: e.SourceID, Before: e.Before, After: e.After, WrittenBy: auditwr, At: e.At, RetainUntil: e.At.AddDate(cAuditDays/365, 0, 0)})
	return 1
}
func softDeleteProjector(e Ev) int {
	i := idxSID(e.SourceSystem, e.SourceID)
	if i < 0 || feed[i].DeletedAt != nil {
		return 0
	}
	feed[i].DeletedAt = &fixedNow
	return 1
}

// directInsertFeed：❌ 业务面 handler 里顺手 INSERT 流表。真库里 svc_finance 对该表只有 SELECT；
// 本机无库，用 written_by 标签等价复现这条路径，好让第 4 节逐行数出它缺了哪几项。
func directInsertFeed(t Txn) {
	feed = append(feed, Feed{ID: fmt.Sprintf("AF-%02d", len(feed)+1), Kind: t.Kind, FamilyID: t.FamilyID, MemberID: t.MemberID,
		AmountCents: t.Cents, WrittenBy: directWr, OccurredAt: t.At, CreatedAt: fixedNow})
}

// guard：未登录 401 / 非本家庭 404 / 本家庭角色不足 403 / 非法 kind 400（给合法形状，不回落默认）。
func guard(user, wantFam, kind string, isWrite bool) (int, string) {
	if user == "" {
		return 401, "无会话：先登录；family_id 只能从会话取，不接受 query"
	}
	if famOf[user] != wantFam {
		return 404, fmt.Sprintf("%s 家没有这个资源：404 而不是 403（403 等于告诉对方「这行存在」）", wantFam)
	}
	if isWrite && roleOf[user] == "viewer" {
		return 403, "本家庭 viewer 可读不可写：角色不足 403（资源确实在他自家，才敢用 403）"
	}
	if kind != "" && !inList(kind, kinds) {
		return 400, fmt.Sprintf("kind=%q 非法：合法形状＝kind ∈ {%s} 四选一，不回落「全部」、不置空", kind, strings.Join(kinds, ", "))
	}
	return 200, "放行"
}
func visible(rs []Feed) (out []Feed) {
	for _, f := range rs {
		if f.DeletedAt == nil {
			out = append(out, f)
		}
	}
	return
}
func idxOf(dk string) int {
	for i, f := range feed {
		if f.DedupKey == dk {
			return i
		}
	}
	return -1
}
func idxSID(sys, sid string) int {
	for i, f := range feed {
		if f.SourceSystem == sys && f.SourceID == sid && sid != "" {
			return i
		}
	}
	return -1
}
func by(tag string) int {
	c := 0
	for _, f := range feed {
		c += yes[f.WrittenBy == tag]
	}
	return c
}
func nSoft() int {
	c := 0
	for _, f := range feed {
		c += yes[f.DeletedAt != nil]
	}
	return c
}
func rowsOf(dk string) int {
	c := 0
	for _, f := range feed {
		c += yes[f.DedupKey == dk]
	}
	return c
}
func missOf(rs []Feed, k string) int {
	c := 0
	for _, f := range rs {
		c += yes[map[string]string{"sys": f.SourceSystem, "dedup": f.DedupKey, "snap": f.DisplayName, "crid": f.ClientRequestID}[k] == ""]
	}
	return c
}
func idsOf(rs []Feed) []string {
	o := []string{}
	for _, f := range rs {
		o = append(o, f.ID)
	}
	sort.Strings(o)
	return o
}
func netOf(rs []Txn, skipSoft bool) (v int64) {
	for _, t := range rs {
		if !skipSoft || t.DeletedAt == nil {
			v += map[bool]int64{true: -1, false: 1}[t.Kind == "expense"] * t.Cents
		}
	}
	return
}

