type Member struct {
	ID, FamilyID, DisplayName string
	DeletedAt                 *time.Time
}
type Feed struct {
	ID, FamilyID, MemberID, SnapName, Kind, Currency, Text string // Text ❌：格式化字符串那一版才会用
	Cents                                                  int64
	SourceSystem, SourceID, Dedup, WrittenBy               string
	At                                                     time.Time
}

func (Feed) TableName() string   { return "homeos_activity" }
func (Member) TableName() string { return "homeos_member" }

// Txt：❌「存格式化字符串」那一版会存进去的东西（符号 + 千分位）；parseText 是读它的人不得不做的反向解析。
func (f Feed) Txt() string { return thousands(f.Cents) + " 元" }
func thousands(c int64) string {
	yuan, fen, neg := abs(c)/100, abs(c)%100, c < 0
	s := strconv.FormatInt(yuan, 10)
	for n := len(s); n > 3; n -= 3 {
		s = s[:n-3] + "," + s[n-3:]
	}
	return map[bool]string{true: "-" + s, false: s}[neg] + fmt.Sprintf(".%02d", fen)
}
func parseText(s string) int64 {
	v, _ := strconv.ParseFloat(strings.ReplaceAll(strings.TrimSuffix(s, " 元"), ",", ""), 64)
	return int64(v * 100) // 0.01 不能被二进制整除：分→元→分 一定会有桶掉 1 分
}

var members = []Member{
	{"M-dad", famA, "爸爸", nil}, {"M-mom", famA, "妈妈", nil}, {"M-kid", famA, "小豆", nil},
	{"M-gma", famA, "奶奶", nil}, {"M-gpa", famA, "爷爷", nil}, {"M-sis", famA, "姐姐", nil},
}
var feedSnap []Feed // ✅ 快照版：条目里带 member_display_name
var feedJoin []Feed // ❌ 读时 JOIN 版：同事实，条目里只存 member_id
var seen = map[string]int{}
var strictFail, lenientRows int
var lostCents int64 // 少算的分数：与 bc.truth / Feed.Cents 同为整数分 int64

func hdr(s string)        { fmt.Printf("\n===== %s =====\n", s) }
func abs(v int64) int64   { return map[bool]int64{true: -v, false: v}[v < 0] }
func orE(s string) string { return map[bool]string{true: "（缺）", false: s}[s == ""] }
func money(c int64) string {
	return fmt.Sprintf("%s%d.%02d", map[bool]string{true: "-", false: ""}[c < 0], abs(c)/100, abs(c)%100)
}
func nameOf(id string) string { // 读时 JOIN：永远拿「此刻」的名字——这就是它会漂的原因
	for _, m := range members {
		if m.ID == id {
			return m.DisplayName
		}
	}
	return "（成员不存在）"
}
func dedupOf(f map[string]string) string {
	return f["source_system"] + sep + f["source_id"] + sep + f["kind"]
}

// decodeStrict：载荷少一个必填字段就 error，error 文本里必须给出合法形状（对应接口层 400，不回落、不补默认）。
func decodeStrict(p map[string]string) (Feed, error) {
	miss := []string{}
	for _, k := range reqFields {
		if p[k] == "" {
			miss = append(miss, k)
		}
	}
	if len(miss) > 0 {
		return Feed{}, fmt.Errorf("payload 缺必填字段 {%s}：合法形状＝%s 七项齐全且非空（服务端不补默认值）", strings.Join(miss, ","), strings.Join(reqFields, "/"))
	}
	c, e := strconv.ParseInt(p["amount_cents"], 10, 64)
	if e != nil {
		return Feed{}, fmt.Errorf("amount_cents=%q 不是整数分：合法形状＝BIGINT 整数（如 386000），不接受 \"3,860.00 元\" 这类格式化字符串", p["amount_cents"])
	}
	return Feed{FamilyID: p["member_id"], MemberID: p["member_id"], SnapName: p["member_display_name"], Kind: p["kind"], Currency: p["currency"],
		Cents: c, SourceSystem: p["source_system"], SourceID: p["source_id"], Dedup: dedupOf(p), WrittenBy: proj}, nil
}

// decodeLenient：❌ 「取不到就给个默认值」那种写法——不报错，静默把 0 和空串写进用户的流。
func decodeLenient(p map[string]string) Feed {
	c, _ := strconv.ParseInt(p["amount_cents"], 10, 64) // 缺字段 → err 被丢掉 → c == 0
	return Feed{MemberID: p["member_id"], SnapName: p["member_display_name"], Kind: p["kind"], Currency: p["currency"],
		Cents: c, SourceSystem: p["source_system"], SourceID: p["source_id"], Dedup: dedupOf(p), WrittenBy: "homeos.feed_projector(lenient)"}
}

// writeSnap：快照版落库，同幂等键 no-op（等价 ON CONFLICT DO NOTHING）。
func writeSnap(f Feed) int {
	if f.Dedup != "" {
		seen[f.Dedup]++
		if seen[f.Dedup] > 1 {
			return 0
		}
	}
	f.ID = fmt.Sprintf("AF-%02d", len(feedSnap)+1)
	feedSnap = append(feedSnap, f)
	return 1
}

// csvRow：把一行条目拼成 CSV。格式化字符串那版带逗号 → 列数当场被撑爆（第 4 节数出来）。
func csvRow(id, who, amt string) string { return strings.Join([]string{id, famA, who, amt}, ",") }

func dryDB() *gorm.DB {
	db, e := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_homeos:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if e != nil {
		panic(e)
	}
	return db
}
func sqlOf(db *gorm.DB, f func(*gorm.DB) *gorm.DB) string { return db.ToSQL(f) }

func main() {
	db := dryDB()
	// 六条业务事实：同一批数据喂给「快照版」和「读时 JOIN 版」两种实现，改名后逐行对照
	type fact struct {
		mid, kind, sid string
		cents          int64
		txt            string
	}
	facts := []fact{
		{"M-dad", "transaction_created", "fam-A|T-41", 386000, "3,860.00 元"},
		{"M-kid", "transaction_created", "fam-A|T-42", 115, "1.15 元"},
		{"M-mom", "transaction_refunded", "fam-A|R-43", 29, "0.29 元"},
		{"M-gma", "transaction_created", "fam-A|T-44", 860, "8.60 元"},
		{"M-sis", "due_fired", "fam-A|R-45", 180000, "1,800.00 元"},
		{"M-gpa", "transaction_created", "fam-A|T-46", 4350, "43.50 元"},
	}
	for _, f := range facts {
		p := map[string]string{"member_id": f.mid, "member_display_name": nameOf(f.mid), "amount_cents": strconv.FormatInt(f.cents, 10),
			"currency": "CNY", "kind": f.kind, "source_system": "finance", "source_id": f.sid}
		row, _ := decodeStrict(p)
		writeSnap(row)
		j, _ := decodeStrict(p)
		j.ID = fmt.Sprintf("AJ-%02d", len(feedJoin)+1)
		j.SnapName = "" // ❌ 这一版不存快照，读时才去 JOIN member 表
		feedJoin = append(feedJoin, j)
	}

	hdr("1. 载荷契约：三档字段——必存 / 快照存 / 禁止存")
	fmt.Printf("  必存（缺一个就 error，服务端不补默认）：%s\n", strings.Join(reqFields, " · "))
	fmt.Printf("  快照存（写定就不动）：member_display_name —— 它是「当时叫什么」，不是「现在叫什么」\n")
	fmt.Printf("  禁止存：格式化金额文本（含符号/千分位）、百分比、相对时间（「3 分钟前」）、JOIN 出来的当前值\n")
	fmt.Printf("  现场：member %d 行 · 快照版条目 %d 行 · 读时 JOIN 版条目 %d 行 · 幂等键已见 %d 个\n", len(members), len(feedSnap), len(feedJoin), len(seen))
	fmt.Printf("  一条正例载荷长这样（第 2 节那批就是由它投影出来的）：\n    %s\n", jsonish(map[string]string{"topic": "finance.transaction.created", "member_id": "M-kid",
		"member_display_name": "小豆", "amount_cents": "115", "currency": "CNY", "kind": "transaction_created", "source_system": "finance", "source_id": "fam-A|T-42"}))

	hdr("2. ✅ 快照版：成员改名后，历史条目逐行不动")
	before2 := snapshotNames()
	for _, m := range []struct{ id, to string }{{"M-kid", "豆豆"}, {"M-gma", "外婆"}} {
		rename(m.id, m.to)
	}
	fmt.Printf("  %-6s %-9s %-13s %-13s %-9s %-9s %s\n", "id", "member_id", "条目里的快照", "member 表现名", "漂了吗", "条目句子", "判定")
	drift := 0
	for i, f := range feedSnap {
		d := f.SnapName != before2[i]
		drift += yes[d]
		fmt.Printf("  %-6s %-9s %-13s %-13s %-9s %-9s %s\n", f.ID, f.MemberID, f.SnapName, nameOf(f.MemberID), map[bool]string{true: "漂", false: "不动"}[d], sentence(f), mark[!d])
	}
	fmt.Printf("  改名 2 人（M-kid 小豆→豆豆 · M-gma 奶奶→外婆）：快照漂移行数 %d（判据 0）· 与改名前逐行相同 %d/%d 行\n",
		drift, len(feedSnap)-drift, len(feedSnap))
	fmt.Printf("  成员改名这条业务动作本身也走事件：homeos.member.renamed → 只更新 member 表（%d 行），一条动态条目都不新增（历史不归它改）\n", 2)

	hdr("3. ❌ 读时 JOIN 版：同批改名，历史条目逐行跟着漂；软删成员还会把行整个弄丢")
	fmt.Printf("  %-6s %-9s %-13s %-13s %-11s %s\n", "id", "member_id", "当时真名(快照)", "JOIN 出现名", "漂了吗", "条目句子（用 JOIN 拼）")
	jd, lost := 0, 0
	for i := range members {
		if members[i].ID == "M-gpa" {
			members[i].DeletedAt = &fixedNow // 爷爷那个账号注销、成员软删：历史条目本该原样留着
		}
	}
	for _, f := range feedJoin {
		now, alive := nameOf(f.MemberID), joinAlive(f.MemberID)
