	fmt.Printf("  全表 Σamount_cents（整数加）= %d 分（=%s 元）；逐条先转元再加再转回分 = %d 分 → 差 %d 分 %s\n",
		sumCents(feedSnap), money(sumCents(feedSnap)), sumFloatBack(feedSnap), abs(sumCents(feedSnap)-sumFloatBack(feedSnap)), mark[sumCents(feedSnap) != sumFloatBack(feedSnap)])

	hdr("5. 幂等键 (source_system, source_id, kind)：重投三次只涨一行")
	key := map[string]string{"member_id": "M-dad", "member_display_name": nameOf("M-dad"), "amount_cents": "99000", "currency": "CNY",
		"kind": "transaction_created", "source_system": "finance", "source_id": "fam-A|T-47"}
	row, _ := decodeStrict(key)
	fmt.Printf("  %-22s %-11s %-13s %-11s %s\n", "动作", "投递次数", "快照版新增", "表内同键行数", "判定")
	addAll := 0
	for i := 1; i <= 3; i++ {
		c := writeSnap(row)
		addAll += c
		fmt.Printf("  %-22s %-11d %-13d %-11d %s\n", fmt.Sprintf("同幂等键第 %d 次投递", i), seen[row.Dedup], c, rowsWithKey(row.Dedup), mark[c == yes[i == 1]])
	}
	fmt.Printf("  幂等键 %s → 三次投递净增 %d 行；反例（无唯一键，d19 第 4 节那种直写）同样三次 → %d 行\n", row.Dedup, addAll, 3)
	fmt.Printf("  键里为什么带 kind：同一笔账可能被发成 transaction_created 与 transaction_refunded 两个事实，它们必须是两条条目而不是互相吞掉\n")

	hdr("6. 载荷缺字段：strict 显式失败（400）vs ❌ lenient 静默补默认 / 塌键吞条目")
	type badCase struct {
		p     map[string]string
		truth int64 // 这条业务事实真实的金额（分）：lenient 写进去多少，报表就少算多少
	}
	bad := []badCase{
		{map[string]string{"member_id": "M-kid", "member_display_name": nameOf("M-kid"), "currency": "CNY", "kind": "transaction_created", "source_system": "finance", "source_id": "fam-A|T-51"}, 12345},
		{map[string]string{"member_id": "M-mom", "amount_cents": "120000", "currency": "CNY", "kind": "transaction_created", "source_system": "finance", "source_id": "fam-A|T-52"}, 120000},
		{map[string]string{"member_id": "M-gpa", "member_display_name": nameOf("M-gpa"), "amount_cents": "360000", "kind": "transaction_created", "source_system": "finance", "source_id": "fam-A|T-53"}, 360000},
		{map[string]string{"member_id": "M-sis", "member_display_name": nameOf("M-sis"), "amount_cents": "7700", "currency": "CNY", "source_system": "finance", "source_id": "fam-A|T-54"}, 7700},
		{map[string]string{"member_id": "M-dad", "member_display_name": nameOf("M-dad"), "amount_cents": "3,860.00 元", "currency": "CNY", "kind": "transaction_created", "source_system": "finance", "source_id": "fam-A|T-55"}, 386000},
		{map[string]string{"member_id": "M-mom", "member_display_name": nameOf("M-mom"), "amount_cents": "4500", "currency": "CNY", "kind": "transaction_created"}, 4500},
		{map[string]string{"member_id": "M-kid", "member_display_name": nameOf("M-kid"), "amount_cents": "6400", "currency": "CNY", "kind": "transaction_created"}, 6400},
	}
	fmt.Printf("  %-25s %-13s %-52s %-19s %-9s %s\n", "缺哪项", "kind", "✅ strict 的 error（等价接口 400）", "❌ lenient 写进表的值", "少算(分)", "后果")
	swallowed := []string{}
	for _, bc := range bad {
		p, e := bc.p, "—"
		if _, err := decodeStrict(p); err != nil {
			strictFail++
			e = err.Error()
		}
		l := decodeLenient(p)
		key := l.Dedup
		dup := rowsWithKey(key) > 0 // 塌键：真实键段空了，与更早一条同键 → 第二条被静默吞掉
		c := writeSnap(l)
		if dup {
			swallowed = append(swallowed, fmt.Sprintf("%s %s 元（%s·应为 %s，实际未落库）", p["member_id"], money(bc.truth), key, "AF-新行"))
		}
		lenientRows += c
		lostCents += bc.truth - l.Cents
		fmt.Printf("  %-25s %-13s %-52s %-19s %-9d %s\n", cut(missList(p), 24), orE(p["kind"]), cut(e, 50),
			cut(fmt.Sprintf("cents=%d name=%q cur=%q", l.Cents, l.SnapName, l.Currency), 18), bc.truth-l.Cents,
