	}
	fmt.Printf("  对拍结论：strict 拒收 %d/%d 条（每条 error 都给出合法形状，绝不回落默认档）；lenient 落库 %d 行、少算 %d 分、塌键被吞掉的事实 %d 条\n",
		strictFail, len(bad), lenientRows, lostCents, len(swallowed))
	for _, s := range swallowed {
		fmt.Printf("  ❌ 被静默吞掉的条目点名：%s —— 缺 source_system/source_id 让幂等键塌成 %s，两条不同事实合成一条\n", s, "||transaction_created")
	}
	fmt.Printf("  lenient 那几行还会一路传染：动态条目显示「%s 记了 0.00 元」、报表桶值 0、导出 CSV 里 0——三处都合法，没有一处报错\n", nameOf("M-kid"))

	hdr("7. DryRun：这张表的 Postgres 原文（本机不连库，只打印）")
	fmt.Printf("  Q1 读流（family_id 恒进、软删不出、快照列直接读，不 join member）\n    %s\n", sqlOf(db, func(g *gorm.DB) *gorm.DB {
		return g.Model(&Feed{}).Select("id, kind, member_id, snap_name, cents, currency, source_system, source_id").Where("family_id = ? AND deleted_at IS NULL", famA).Order("at DESC").Limit(20).Find(&[]map[string]any{})
	}))
	fmt.Printf("  I1 投影写入（七个必填列一个都不许空）\n    %s\n", sqlOf(db, func(g *gorm.DB) *gorm.DB { return g.Create(&feedSnap[0]) }))
	fmt.Printf("  J1 ❌ 读时 JOIN 那一版的实际语句（改名后它读到的是现名，历史条目跟着漂）\n    %s\n", sqlOf(db, func(g *gorm.DB) *gorm.DB {
		return g.Table("homeos_activity a").Select("a.id, m.display_name").Joins("JOIN homeos_member m ON m.id = a.member_id").Where("a.family_id = ?", famA).Find(&[]map[string]any{})
	}))
	fmt.Println("    ALTER TABLE homeos_activity ALTER COLUMN snap_name SET NOT NULL;  -- 载荷缺字段时在库里就写不进去")
	fmt.Println("    CREATE UNIQUE INDEX uniq_homeos_activity_dedup ON homeos_activity (source_system, source_id, kind) WHERE deleted_at IS NULL;")
	fmt.Println("  这两句是迁移契约文本（本机不建表，不声称跑过）；真环境复跑：① 把第 6 节 5 条缺字段载荷原样投给消费者，期望 5 次约束/NOT NULL 报错；② 同键投 3 次，期望表内 1 行。")

	hdr("8. 收口 + 交 d21")
	fmt.Printf("  收口数字：条目表 %d 行（快照 %d · lenient %d）· 漂移行 快照版 %d / JOIN 版 %d · 幂等重投净增 %d 行 · strict 拒收 %d/%d · lenient 少算 %d 分\n",
		len(feedSnap), len(feedSnap)-lenientRows, lenientRows, drift, jd, addAll, strictFail, len(bad), lostCents)
	fmt.Println("  · 快照存「当时叫什么」，JOIN 读「现在叫什么」：改名后历史条目必须逐行不动（第 2 节 0 漂移 vs 第 3 节逐行点名）。")
	fmt.Println("  · 金额只存 amount_cents + 币种；格式化字符串既会丢分（第 4 节实测）又会撑爆 CSV 列。")
	fmt.Println("  · 幂等键 (source_system, source_id, kind)：三次投递一行；键里带 kind，别把两个事实合成一条。")
	fmt.Println("  · 载荷缺字段＝显式失败并在 error 里给合法形状（接口层 400）；静默补 0 会让流、报表、导出三处一起「合法地错」。")
	fmt.Printf("\n=== W52 d20 到此：条目字段契约定稿 ===\n明天 d21：字段齐了就能聚合——首屏只放 home/summary 一个业务请求，四区并行取、坏一区不整页 500。\n")
}

func snapshotNames() (out []string) {
	for _, f := range feedSnap {
		out = append(out, f.SnapName)
	}
	return
}
func rename(id, to string) {
	for i := range members {
		if members[i].ID == id {
			members[i].DisplayName = to
		}
	}
}
func snapNameOf(id string) string {
	for _, f := range feedSnap {
		if f.MemberID == id {
			return f.SnapName
		}
	}
	return "—"
}
func joinAlive(id string) bool { // INNER JOIN homeos_member 的语义：软删成员（deleted_at 非空）不产出行 → 历史条目整个消失
	for _, m := range members {
		if m.ID == id && m.DeletedAt == nil {
			return true
		}
	}
	return false
}
func sentence(f Feed) string {
	return fmt.Sprintf("%s %s %s 元", f.SnapName, map[bool]string{true: "记了", false: "退了"}[f.Kind == "transaction_created"], money(f.Cents))
}
func sentenceJ(f Feed) string {
	return fmt.Sprintf("%s %s %s 元", nameOf(f.MemberID), map[bool]string{true: "记了", false: "退了"}[f.Kind == "transaction_created"], money(f.Cents))
}
func rowsWithKey(dk string) int {
	c := 0
	for _, f := range feedSnap {
		c += yes[f.Dedup == dk && f.Kind != ""]
	}
	return c
}
func sumCents(rs []Feed) (v int64) {
	for _, f := range rs {
		v += f.Cents
	}
	return
}
func sumFloatBack(rs []Feed) int64 { // ❌ 文本→float→元→分：第 4 节用它算偏差
	var f float64
	for _, x := range rs {
		f += float64(parseText(x.Txt()))
	}
	return int64(f)
}
func cut(s string, n int) string {
	r := []rune(s)
	return map[bool]string{true: string(r[:n]) + "…", false: s}[len(r) > n]
}
func missList(p map[string]string) string {
	m := []string{}
	for _, k := range reqFields {
		if p[k] == "" {
			m = append(m, k)
		}
	}
	sort.Strings(m)
	return map[bool]string{true: "（齐全）", false: strings.Join(m, ",")}[len(m) == 0]
}
func jsonish(p map[string]string) string {
	ks := []string{}
	for k := range p {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	out := "{"
	for _, k := range ks {
		out += fmt.Sprintf("%q:%q,", k, p[k])
	}
	return strings.TrimSuffix(out, ",") + "}"
}

// =====================================================================
// W52 d21：首页首屏只有 home/summary 一个业务请求（前端半 —— 请求计数只能这样证）
//
// ★ 这张卡的 expect 取哪一份 stdout：取 main.mjs（node）这一份。
//   runner（run.sh s12 21）在目录里看到 .mjs 就只跑 node，out/s12_d21.txt 就是下面打印的这些字节；
//   同目录的 main.go 是「同一道题的 Go 版」（errgroup 并行取四区 + degraded 标记 + DryRun 四区 SQL），
//   本地 `cd homecube/server && go run ./lab/s12/d21` 可整体跑完，但它不是这张卡的对拍产物。
//   两个入口混在一个目录容易把卡片对不齐，所以第 4~6 节把 Go 版要证的三件事——一个请求带出四区 /
//   单区失败只标 degraded 不整页 500 / 未读数走唯一来源函数——在同一份内存模型里用 JS 复算一遍：
//   两边打印的字段名、区名、判定用同一套口径，expect 只认 main.mjs。
//
// 这一天在解决什么问题：首屏要摆四个区（账目摘要 / 待办提醒 / 通知未读 / 最近动态）。
// 「四个区」是**视图**的分法，不是**请求**的分法。客户端一旦照区名各打一次，就同时踩四条线：
//   ① 口径散：四个接口各自算「本月」，日界线谁切谁的（d22 专章对拍的就是这个）；
//   ② 未读数出现第二个来源（d14 定的是 unread() 一个函数、三个出口）；
//   ③ 弱网下首屏变成四张拼图，一张没回来就空一块，客户端还得自己写合并与超时；
//   ④ 灰度和角色改动要前端发版才能跟进（d07/d11 立的规矩：清单在服务端合成）。
// 正解只有一个业务请求：GET /api/home/summary，四区在响应体里；区取不到由服务端标 degraded。
//
// 确定性：没有真 fetch、没有 setTimeout、没有 Date.now、没有随机。模拟延迟是钉死的常数表，
// 一切顺序来自 sort；两次跑字节一致。零请求判据（d09 那条）在本机就是这个假 fetch 计数器数出来的条数。
// 学员侧跑法：node lab/s12/d21/main.mjs　或　bash run.sh s12 21
// =====================================================================

const L = (s = '') => console.log(s)
const H = (t) => L('\n===== ' + t + ' =====')
// 显示宽度补齐：CJK 占两列。纯函数 → 同一份输入永远同一份字节（不用 padEnd 是按码元补的，表会歪）。
const dw = (s) => [...String(s)].reduce((n, ch) => n + (ch.codePointAt(0) > 0x2e7f ? 2 : 1), 0)
const P = (s, n) => String(s) + ' '.repeat(Math.max(0, n - dw(String(s))))

// ---------- 会话 · 面目录 · 合成清单（d08 的唯一合成函数，d12 定稿的响应形状） ----------
const SESS = { fam: 'fam-A', user: 'u-dad', role: 'owner' }
const MONTH = '2026-10'
const DUE = '2026-10-26T09:00' // 钉死的「到期前」界：真环境由服务端按家庭时区算，客户端不传日期
const RANK = { viewer: 10, editor: 20, owner: 30 }

// [code, 名称, 最低角色, 阶段, 本家庭是否已启用, route]
const DIR = [
  ['ledger', '账本', 'viewer', 'ga', true, '/api/finance/summary'],
  ['budget', '预算', 'viewer', 'ga', true, '/api/finance/budget'],
  ['report', '报表', 'viewer', 'ga', true, '/api/finance/report'],
  ['export', '导出', 'editor', 'gray', true, '/api/finance/export'],
  ['reminder', '提醒', 'editor', 'ga', true, '/api/calendar/reminder'],
  ['notification', '通知', 'viewer', 'ga', true, '/api/homeos/notification'],
  ['activity', '动态', 'viewer', 'gray', true, '/api/homeos/activity'],
  ['settings', '设置', 'owner', 'ga', true, '/api/homeos/settings'],
  ['lab', '实验田', 'viewer', 'unborn', false, '/api/lab/entry'],
  ['homeos', '主机', 'owner', 'unborn', false, '/api/homeos/host'],
]

// synthesize：目录 ∩ 家庭已启用 ∩ 已出生 ∩ 角色可见 —— 唯一一份，客户端不许再 filter 一次（d08/d12）。
function synthesize(sess) {
  return DIR.filter((f) => f[4] && f[3] !== 'unborn' && RANK[sess.role] >= RANK[f[2]]).map((f) => f[0])
}
const routeOf = (code) => DIR.find((f) => f[0] === code)[5]
const MANIFEST = synthesize(SESS)

// 首屏四区：区名 → 依赖的面（面不在合成清单里，这个区在响应体里就不出现，客户端一条请求都不发）
const SECTIONS = [
  { name: '账目摘要', face: 'ledger' },
  { name: '待办提醒', face: 'reminder' },
  { name: '通知未读', face: 'notification' },
  { name: '最近动态', face: 'activity' },
]

// ---------- 假 fetch 计数器：这台机器上没有网络，请求数就是一次都不许多打的判据本身 ----------
const CTR = { biz: 0, bizLog: [], other: 0, otherLog: [] }
function fakeFetch(url, kind = 'biz') {
  ;(kind === 'biz' ? CTR.bizLog : CTR.otherLog).push(url)
  if (kind === 'biz') CTR.biz++
  else CTR.other++
  return { status: 200, url, kind }
}
const reset = () => {
  CTR.biz = CTR.other = 0
  CTR.bizLog = []
  CTR.otherLog = []
}

// 模拟延迟：钉死的常数表（不是测出来的耗时）。任何「谁先谁后」都不进 stdout，只有排过序的数字进。
const LAT = { 账目摘要: 90, 待办提醒: 60, 通知未读: 40, 最近动态: 120 }
const HANDLER = 15 // home/summary 自己的封装配额
const sumLat = (a) => a.reduce((x, y) => x + y, 0)
const maxLat = (a) => a.reduce((x, y) => (x > y ? x : y), 0)

// ---------- homeos_notification 内存表（口径与 d14/d15 逐字一致） ----------
const NOTES = [
  { id: 1, fam: 'fam-A', to: 'u-dad', kind: 'budget_alert', read: null, del: null },
  { id: 2, fam: 'fam-A', to: 'u-dad', kind: 'budget_alert', read: null, del: null },
  { id: 3, fam: 'fam-A', to: 'u-dad', kind: 'reminder', read: null, del: null },
  { id: 4, fam: 'fam-A', to: 'u-dad', kind: 'system', read: '2026-10-18T21:00', del: null },
  { id: 5, fam: 'fam-A', to: 'u-dad', kind: 'system', read: null, del: '2026-10-18T22:00' }, // 已撤回：软删行不算未读
  { id: 6, fam: 'fam-A', to: 'u-kid', kind: 'reminder', read: null, del: null }, // 收件人不是自己
  { id: 7, fam: 'fam-B', to: 'u-mom', kind: 'system', read: null, del: null }, // 别家
]
// unread：全项目唯一的未读数来源（d14 定名）。三个出口只许调它——自己 COUNT 一遍就是第二个来源。
function unread(fam, user) {
  return NOTES.filter((x) => x.fam === fam && x.to === user && x.read === null && x.del === null).length
}
const ledgerNet = () => -248600 // 本月净额（整数分，负=净支出）：来自 finance 域，本卡只当四区之一的载荷
const duesCount = () => 3
const actLast = () => '小豆 210.00 元'

// ---------- 服务端那一半：一个请求带出四区，单区失败只标 degraded（main.go 同逻辑的 JS 复算） ----------
function homeSummary(failSection) {
  return SECTIONS.map((s) => {
    if (!MANIFEST.includes(s.face)) return null // 面不在清单 → 这个区根本不组装
    if (s.name === failSection) return { name: s.name, face: s.face, val: null, ok: false, err: 'downstream rpc timeout', latency: LAT[s.name] }
    const val =
      s.face === 'ledger' ? `${ledgerNet()} 分` : s.face === 'reminder' ? `${duesCount()} 条待办` : s.face === 'notification' ? `${unread(SESS.fam, SESS.user)} 条未读` : actLast()
    return { name: s.name, face: s.face, val, ok: true, err: '', latency: LAT[s.name] }
  })
    .filter(Boolean)
    .sort((a, b) => (a.name < b.name ? -1 : 1)) // 按区名定序打印 → 与并发完成先后无关
}

L('===== 1. 现场：会话、合成清单、首屏四区，外加一个只会数数的假 fetch =====')
L(`  会话 fam=${SESS.fam} user=${SESS.user} role=${SESS.role}（family_id 只从会话取，客户端传了也不认）`)
