L(`  首屏业务请求数 ${CTR.biz} 个 → URL 里出现 family_id 的次数 ${CTR.bizLog.filter((u) => u.includes('family_id=')).length} 次（会话注入那一次）`)

H('3. ❌ 反例：客户端照区名自己并发四区，各打一次')
reset()
const FOUR = SECTIONS.map((s) => {
  const q = s.face === 'ledger' ? `month=${MONTH}` : s.face === 'reminder' ? `due_before=${DUE}` : s.face === 'notification' ? `recipient_user_id=${SESS.user}` : `cursor=&size=8`
  return `${routeOf(s.face)}?family_id=${SESS.fam}&${q}`
})
FOUR.forEach((u) => fakeFetch(u))
