const merge = FOUR.length
L(`  这四条各自算「本月/本次」，日界线由四个服务各切一次 → d22 就是专门跟这个记账的（口径漂移当场对拍）。`)
L(`  判据落成布尔：请求数 ${CTR.biz}==1 ${CTR.biz === 1 ? '✅' : '❌'} ／ 多打 ${CTR.biz - 1} 条须为 0 ${CTR.biz - 1 === 0 ? '✅' : '❌'} ／ 客户端为此要多写的合并与超时分支 ${merge} 条（正解 1 条：只有一个响应）`)

H('4. 服务端那一半：一个请求进来，errgroup 并行取四区（main.go 同一道题的等价复算）')
reset()
fakeFetch(ONE)
