L(`  四区固定延迟排序后 ${latG.join(' ')} ms → 并行取数耗时取最大 ${maxLat(latG)} ms（不是求和 ${sumLat(latG)} ms）`)
L(`  收集完按区名定序再打印：stdout 里没有任何一个数由 goroutine 调度顺序决定`)
for (const r of good) L(`    ${P(r.name, 10)}ok=${P(String(r.ok), 7)}${P(r.ok ? '值=' + r.val : 'err=' + r.err, 22)}degraded=${!r.ok}`)
L(`  四区都健康时 degraded=${good.filter((r) => !r.ok).length} · 整页 200 · 业务请求数 ${CTR.biz}`)

