	gormlogger "gorm.io/gorm/logger"
)

var famLoc = time.FixedZone("CST", 8*3600) // 家庭时区＝东八区固定偏移：报表、summary、详情页三处共用它，任何一处换成 UTC 都是缺陷
var fixedNow = day0(2026, 11, 2).Add(9 * time.Hour)
var mark, yes = map[bool]string{true: "✅", false: "❌"}, map[bool]int{true: 1, false: 0}

const famA, famB, uDad, uKid, sep = "fam-A", "fam-B", "u-dad", "u-kid", "|"

// 切窗与切桶的字面量只有一个出处：tzFam 是上线口径（家庭时区），tzUTC 只允许出现在第 7 节那条 ❌ 展示里；
// netExpr 是「净额」在 SQL 里的唯一写法（整数分上做 CASE 求和），summary / 报表 / 详情页三条语句共用同一个常量。
const (
	tzFam, tzUTC = "Asia/Shanghai", "UTC"
	colAt, TZ    = "occurred_at", "to_char"
	AT, netExpr  = "AT TIME ZONE", "sum(CASE WHEN kind = 'income' THEN amount_cents ELSE -amount_cents END)"
)

func day0(y, m, d int) time.Time { return time.Date(y, time.Month(m), d, 0, 0, 0, 0, famLoc) }
func hdr(s string)               { fmt.Printf("\n===== %s =====\n", s) }
func hm(t time.Time) string      { return t.In(famLoc).Format("2006-01-02 15:04") }
func hmDay(t time.Time) string   { return t.In(famLoc).Format("2006-01-02") }
func utcStr(t time.Time) string  { return t.UTC().Format("2006-01-02 15:04") }
func fLocal(t time.Time) string  { return t.In(famLoc).Format("2006-01-02 15:04:05-07") } // SQL 里把 timestamp 钉到家庭时区的那次转换
func abs(c int64) int64          { return map[bool]int64{true: -c, false: c}[c < 0] }
func money(c int64) string       { return fmt.Sprintf("%d.%02d", c/100, abs(c)%100) } // 分→元：只在展示层、只在聚合之后，全链路唯一一次
func wd(s string) int            { return (len(s) + len([]rune(s))) / 2 }
func pad(s string, n int) string { return s + strings.Repeat(" ", max(0, n-wd(s))) }

// ---------- 内存表：finance_transaction 的行，金额只有 amount_cents 一列整数 ----------
type txn struct {
	id, fam, kind string // kind ∈ income / expense
	cents         int64  // amount_cents：恒为正整数分，方向只由 kind 决定
	at            time.Time
	soft          bool // true = deleted_at 非空（软删，有恢复路径）
}

func (r txn) signed() int64 {
	return map[bool]int64{true: r.cents, false: -r.cents}[r.kind == "income"]
}

// 账本八笔：t-04 / t-05 是两条日界样本——一笔「家庭时区已在 10 月、UTC 还在 9 月末」，另一笔反之；
// t-07 是软删行、t-08 是别家行，所有口径都必须看不见它们。
var ledger = []txn{
	{"t-01", famA, "expense", 128000, day0(2026, 10, 8).Add(21*time.Hour + 30*time.Minute), false},
	{"t-02", famA, "expense", 86600, day0(2026, 10, 12).Add(12*time.Hour + 30*time.Minute), false},
	{"t-03", famA, "income", 300000, day0(2026, 10, 15).Add(9 * time.Hour), false},
	{"t-04", famA, "expense", 54000, day0(2026, 10, 1).Add(7*time.Hour + 30*time.Minute), false}, // UTC 2026-09-30 23:30
	{"t-05", famA, "expense", 77000, day0(2026, 11, 1).Add(3 * time.Hour), false},                // UTC 2026-10-31 19:00
	{"t-06", famA, "expense", 420000, day0(2026, 9, 30).Add(10 * time.Hour), false},
	{"t-07", famA, "expense", 9900, day0(2026, 10, 17).Add(20 * time.Hour), true},
	{"t-08", famB, "expense", 77000, day0(2026, 10, 12).Add(18 * time.Hour), false},
}

func rowOf(id string) txn {
	for _, r := range ledger {
		if r.id == id {
			return r
		}
	}
	panic("unknown row " + id)
}

// ---------- W46 桶契约（S11 d18）原样引用：比较量连同产出它的那段半开窗一起传 ----------
type measure struct {
	label    string
	from, to time.Time
	cents    int64
}

func sameWin(a, b measure) bool { return a.from.Equal(b.from) && a.to.Equal(b.to) }

func versus(a, b measure) (string, bool) { // 同窗才比：窗不一致就拒绝判定，并把两边的窗原样打出来
	if !sameWin(a, b) {
		return fmt.Sprintf("❌ 拒绝跨窗对拍：%s 窗 [%s, %s) %s 元 vs %s 窗 [%s, %s) %s 元 —— 两边各自都没算错，只是不是同一段窗，先把比较量挪到同一扇窗再谈等号",
			a.label, hmDay(a.from), hmDay(a.to), money(a.cents), b.label, hmDay(b.from), hmDay(b.to), money(b.cents)), false
	}
	return fmt.Sprintf("✅ 同窗 [%s, %s)：%s %s 元 == %s %s 元（差 %d 分）", hmDay(a.from), hmDay(a.to),
		a.label, money(a.cents), b.label, money(b.cents), a.cents-b.cents), a.cents == b.cents
}

// ---------- 筛选条件的唯一开窗处：非法即 error，由入口换成 400 并给合法形状，绝不回落默认窗 ----------
func parseMonthKey(s string) (time.Time, time.Time, error) {
	bad := func(shape string) (time.Time, time.Time, error) {
		return time.Time{}, time.Time{}, fmt.Errorf("month=%q 非法：%s 服务端不猜当前月、不回落默认窗", s, shape)
	}
	if len(s) != 7 || s[4] != '-' || !digits(s[:4]) || !digits(s[5:]) {
		return bad("month 形如 YYYY-MM（例如 2026-10）")
	}
	y, m := mustAtoi(s[:4]), mustAtoi(s[5:])
	if m < 1 || m > 12 {
		return bad("月份要在 01..12 之间（2026-13、2026-00 都不接受）")
	}
	f := day0(y, m, 1)
	return f, f.AddDate(0, 1, 0), nil
}

func digits(s string) bool {
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return len(s) > 0
}
func mustAtoi(s string) int {
	n := 0
	for _, c := range s {
		n = n*10 + int(c-'0')
	}
	return n
}
func mustWin(key string) (time.Time, time.Time) {
	f, t, e := parseMonthKey(key)
	if e != nil {
		panic(e)
	}
	return f, t
}

// inWin：半开区间 [from, to)——右端排他，是三条路径共用、也是唯一的一条窗谓词。
func inWin(t, from, to time.Time) bool { return !t.Before(from) && t.Before(to) }

// 路径 A：home/summary 的账目摘要区（d21 里那个函数），取数窗必须与另两条逐字相同才算对拍。
func summaryNet(fam string, from, to time.Time) measure {
	var c int64
	for _, r := range ledger {
		if r.fam == fam && !r.soft && inWin(r.at, from, to) {
			c += r.signed()
		}
	}
	return measure{"summary 本月净额", from, to, c}
}

// 路径 B：S11 报表的月桶值——先按家庭时区切 YYYY-MM 分桶，再取窗口首月那一桶。
func bucketKeyOf(r txn) string { return r.at.In(famLoc).Format("2006-01") }
func monthUTC(r txn) string    { return r.at.UTC().Format("2006-01") } // 只用来数「两边月份键不一致」的行，不参与任何上线口径

func reportBucket(fam string, from, to time.Time) measure {
	c := map[string]int64{}
	for _, r := range ledger {
		if r.fam == fam && !r.soft && inWin(r.at, from, to) {
			c[bucketKeyOf(r)] += r.signed()
		}
	}
	return measure{"S11 报表月桶", from, to, c[hmDay(from)[:7]]}
}

// 路径 C：流水详情页「筛选后逐笔求和」——同一 family_id、同一对窗参数、cursor 翻到底的三类合计。
type detail struct{ net, inc, exp int64 }

func detailSum(fam string, from, to time.Time) (detail, measure) {
	d := detail{}
	for _, r := range ledger {
		if r.fam == fam && !r.soft && inWin(r.at, from, to) {
			d.net += r.signed()
			if r.kind == "income" {
				d.inc += r.cents
			} else {
				d.exp += r.cents
			}
		}
	}
	return d, measure{"详情页逐笔和", from, to, d.net}
}

// rowsIn：同窗的行集（详情页逐笔展示的就是它），按 id 定序 → 与取数顺序无关。
func rowsIn(fam string, from, to time.Time) []txn {
	var out []txn
	for _, r := range ledger {
		if r.fam == fam && !r.soft && inWin(r.at, from, to) {
			out = append(out, r)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
	return out
}

// ---------- 稠密桶契约：一行 == 一桶，空桶照样出一行（值 0），补 0 只准出现在这一处 ----------
func monthSeq(from, to time.Time) []measure {
	var out []measure
	for t := from; t.Before(to); t = t.AddDate(0, 1, 0) {
		out = append(out, summaryNet(famA, t, t.AddDate(0, 1, 0)))
	}
	return out
}

// ---------- 时区口径差：把「差在哪一笔」点名到行，而不是只报一个差额 ----------
type diffRow struct {
	id  string
	d   int64
	why string
}

// tzDiff：同一份账本，分别用家庭时区窗与 UTC 窗切同一个 key，返回两边净额与造成差额的行；
// d 是「UTC 口径 − 家庭时区口径」的边际贡献，全部点名的行合计必须与总差闭合。
func tzDiff(fam, key string) (int64, int64, []diffRow) {
	loF, loT := mustWin(key)
	ucF, ucT := winUTC(key)
	var locSum, utcSum int64
	var rows []diffRow
	for _, r := range ledger {
		if r.fam != fam || r.soft {
			continue
		}
		inL, inU := inWin(r.at, loF, loT), inWin(r.at, ucF, ucT)
		if inL {
			locSum += r.signed()
		}
		if inU {
			utcSum += r.signed()
		}
		switch {
		case inL && !inU:
			rows = append(rows, diffRow{r.id, -r.signed(), "家庭时区算这个月，UTC 还在上一月末：这笔被 UTC 口径整笔丢出该月"})
		case !inL && inU:
			rows = append(rows, diffRow{r.id, r.signed(), "家庭时区已是下个月，UTC 还在该月末：这笔被 UTC 口径整笔错收进该月"})
		}
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].id < rows[j].id })
	return locSum, utcSum, rows
}

// ---------- 游标分页：详情页只准 cursor，禁止 offset ----------
func descRows(rows []txn) []txn { // 与 SQL 的 ORDER BY occurred_at DESC, id DESC 同序
	out := append([]txn{}, rows...)
	sort.Slice(out, func(i, j int) bool {
		if !out[i].at.Equal(out[j].at) {
			return out[i].at.After(out[j].at)
		}
		return out[i].id > out[j].id
	})
	return out
}
func cursorOf(r txn) string { return fmt.Sprintf("%d|%s", r.at.UTC().UnixNano(), r.id) }

func nextPage(sorted []txn, cursor string, limit int) ([]txn, string, error) {
	start := 0
	if cursor != "" {
		found := false
		for i, r := range sorted {
			if cursorOf(r) == cursor {
				start, found = i+1, true
				break
			}
		}
		if !found {
			return nil, "", fmt.Errorf("cursor=%q 非法：只接受上一页最后一行回传的不透明串，页码 / offset 一律不收", cursor)
		}
	}
	end := min(start+limit, len(sorted))
	out := sorted[start:end]
	next := ""
	if len(out) > 0 && end < len(sorted) {
		next = cursorOf(out[len(out)-1])
	}
	return out, next, nil
}

// ---------- 未读数：全项目唯一谓词（W51 d14~d18），三道出口都是它的薄包装 ----------
type note struct {
	id, fam, user string
	read, recall  time.Time
	soft          bool
}

var notes = []note{
	{"n-01", famA, uDad, time.Time{}, time.Time{}, false},
	{"n-02", famA, uDad, time.Time{}, time.Time{}, false},
	{"n-03", famA, uDad, day0(2026, 10, 28).Add(21 * time.Hour), time.Time{}, false},
	{"n-04", famA, uDad, time.Time{}, day0(2026, 10, 29).Add(8 * time.Hour), false},
	{"n-05", famA, uDad, time.Time{}, time.Time{}, true},
	{"n-06", famA, uKid, time.Time{}, time.Time{}, false},
}

func counted(n note) bool { return n.read.IsZero() && n.recall.IsZero() && !n.soft }

// unread：唯一未读来源，谓词逐字＝read_at IS NULL AND recalled_at IS NULL AND deleted_at IS NULL AND family_id AND recipient。
func unread(fam, user string) int {
	var c int
	for _, n := range notes {
		if n.fam == fam && n.user == user && counted(n) {
			c++
		}
	}
	return c
}

// 三道出口都只是 unread() 的薄包装，没有第二处算术（W51 d14 定的形状）：
// 角标回数字、列表页回 total_unread、summary 通知区回一行文案——文案里的数字必须能原样解析回同一个值。
func exitBadge(fam, user string) int      { return unread(fam, user) }
func exitListTotal(fam, user string) int  { return unread(fam, user) }
func exitSection(fam, user string) string { return fmt.Sprintf("%d 条未读", unread(fam, user)) }
func sectionVal(s string) int             { var n int; _, _ = fmt.Sscanf(s, "%d 条未读", &n); return n }

// 反例一：拿「当页行数」当未读（LIMIT 分页只回一页）；反例二：family 维度 COUNT（漏掉 recipient 谓词）。
func pageRows(fam, user string, limit int) int {
	var c int
	for _, n := range notes {
		if c < limit && n.fam == fam && n.user == user && counted(n) {
			c++
		}
	}
	return c
}
func famOnlyCount(fam string) int {
	var c int
	for _, n := range notes {
		if n.fam == fam && counted(n) {
			c++
		}
	}
	return c
}

// ---------- 周期预算：只有 (family_id, period) 真设过才有一行；未设就显「未设该周期预算」，任何周期都不外推 ----------
var budgetOf = map[string]int64{famA + sep + "2026-10": 400000}

func budgetLine(fam, period string) string {
	c, ok := budgetOf[fam+sep+period]
	if !ok {
		return fmt.Sprintf("%s / %s：未设该周期预算 → 预算行整体不出现，不做 ×3 / ×12 折算，不预估支出占比", fam, period)
	}
	f, t := mustWin(period)
	d, _ := detailSum(fam, f, t)
	return fmt.Sprintf("%s / %s：预算 %s 元（整数分 %d）· 该周期实际支出 %s 元（现算 %d 分）· 占比由两边现场相除，不预估",
		fam, period, money(c), c, money(d.exp), d.exp)
}

