type txnModel struct {
	ID          string    `gorm:"column:id;primaryKey"`
	FamilyID    string    `gorm:"column:family_id"`
	Kind        string    `gorm:"column:kind"`
	AmountCents int64     `gorm:"column:amount_cents"`
	OccurredAt  time.Time `gorm:"column:occurred_at"`
	DeletedAt   time.Time `gorm:"column:deleted_at"`
}

func (txnModel) TableName() string { return "finance_transaction" }

type noteModel struct {
	ID              string    `gorm:"column:id;primaryKey"`
	FamilyID        string    `gorm:"column:family_id"`
	RecipientUserID string    `gorm:"column:recipient_user_id"`
	ReadAt          time.Time `gorm:"column:read_at"`
	RecalledAt      time.Time `gorm:"column:recalled_at"`
	DeletedAt       time.Time `gorm:"column:deleted_at"`
}

func (noteModel) TableName() string { return "homeos_notification" }

// 日界与锚点的唯一产出处：fLocal 给上线口径（家庭时区的墙上窗，第 1 节三条路径与第 7 节四条语句都用它）；
// winUTC 只服务第 4 节的反例演算，业务出口一处都不碰。
func winUTC(key string) (time.Time, time.Time) {
	f := time.Date(mustAtoi(key[:4]), time.Month(mustAtoi(key[5:])), 1, 0, 0, 0, 0, time.UTC)
	return f, f.AddDate(0, 1, 0)
}

type sqlStmt struct{ title, sql string }

// buildSQLs：上线要跑的 SQL。标题里点名口径，窗参数与游标锚点全部由 fLocal 现场生成——
// 语句文本里不出现 tzUTC，切桶写法整站只有一处 to_char(occurred_at AT TIME ZONE tzFam, 'YYYY-MM')。
func buildSQLs(db *gorm.DB, from, to time.Time, anchor txn) []sqlStmt {
	wF, wT, wA := fLocal(from), fLocal(to), fLocal(anchor.at)
	var n int64
	return []sqlStmt{
		{"summary 账目摘要区（本月净额，整数分进、整数分出）", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
			return tx.Model(&txnModel{}).Select(netExpr+" AS net_cents").
				Where("family_id = ? AND deleted_at IS NULL AND "+colAt+" >= ? AND "+colAt+" < ?", famA, wF, wT).
				Find(&[]map[string]any{})
		})},
		{"S11 报表月桶（整站唯一一处切桶，与 summary 同窗才可比）", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
			return tx.Model(&txnModel{}).
				Select(TZ+"("+colAt+" "+AT+" '"+tzFam+"', 'YYYY-MM') AS bucket, "+netExpr+" AS cents").
				Where("family_id = ? AND deleted_at IS NULL AND "+colAt+" >= ? AND "+colAt+" < ?", famA, wF, wT).
				Group("bucket").Order("bucket").Find(&[]map[string]any{})
		})},
		{"详情页逐笔（同 family、同窗、游标续页：只准 LIMIT，出现 OFFSET 即为缺陷）", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
			return tx.Model(&txnModel{}).Select("id, kind, amount_cents, "+colAt).
				Where("family_id = ? AND deleted_at IS NULL AND "+colAt+" >= ? AND "+colAt+" < ? AND ("+colAt+", id) < (?, ?)",
					famA, wF, wT, wA, anchor.id).
				Order(colAt + " DESC, id DESC").Limit(20).Find(&[]map[string]any{})
		})},
		{"未读 COUNT（全项目唯一谓词，三道出口共用；软删行由 GORM 自动补 IS NULL）", db.ToSQL(func(tx *gorm.DB) *gorm.DB {
			return tx.Model(&noteModel{}).
				Where("family_id = ? AND recipient_user_id = ? AND read_at IS NULL AND recalled_at IS NULL", famA, uDad).Count(&n)
		})},
	}
}

func colJoin(ss []sqlStmt, titles bool) string {
	out := make([]string, len(ss))
	for i, s := range ss {
		out[i] = map[bool]string{true: s.title, false: s.sql}[titles]
	}
	return strings.Join(out, " ~ ")
}

var checkBad int

func ck(cond bool, format string, a ...any) {
	checkBad += yes[!cond]
	fmt.Printf("  %s %s\n", mark[cond], fmt.Sprintf(format, a...))
}

