	for _, p := range paths {
		fmt.Println("  " + pad(p.tag, 20) + pad(p.how, 44) + pad(fmt.Sprint(len(rowsIn(famA, p.m.from, p.m.to))), 8) + fmt.Sprint(p.m.cents))
