	fmt.Printf("  详情页三类合计：收入 %s 元 · 支出 %s 元 · 净额 %s 元（收入−支出 = %d 分，与逐笔和同值：%s）\n",
		money(d.inc), money(d.exp), money(d.net), d.inc-d.exp, mark[d.inc-d.exp == d.net])
	for _, pr := range [][2]measure{{a, b}, {a, c}, {b, c}} {
