	}
	ck(sameWin(a, b) && sameWin(b, c), "三条路径拿到的是同一段窗（同一个 parseMonthKey 的返回值），等号才有意义")
	ck(a.cents == b.cents && b.cents == c.cents, "判据① 同一筛选条件下三条路径净额逐分相等：%d 分（%s 元）——summary 与详情页对拍通过", a.cents, money(a.cents))
	ck(len(rowsIn(famA, from, to)) == len(rowsIn(famA, b.from, b.to)) && len(rowsIn(famA, from, to)) == len(rowsIn(famA, c.from, c.to)),
