	fmt.Printf("  窗口：[%s, %s)，按自然月步进\n", hmDay(seqFrom), hmDay(seqTo))
	bs := monthSeq(seqFrom, seqTo)
	fmt.Println("  " + pad("桶键", 12) + pad("该桶窗口", 30) + pad("净额（分）", 14) + "该桶行数")
