func mapIds(rows []diffRow) []string {
	var out []string
	for _, r := range rows {
		out = append(out, r.id)
	}
	return out
}
func mapTxnIDs(rows []txn) []string {
	var out []string
	for _, r := range rows {
		out = append(out, r.id)
	}
	return out
}
func sameStrs(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
func cut(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n-1]) + "…"
}
func tsOr(t time.Time) string {
	return map[bool]string{true: "—（NULL）", false: hm(t)}[t.IsZero()]
}
func noteWhy(n note) string {
	switch {
	case n.soft:
		return "软删行：deleted_at 非空，任何出口都不计数"
	case !n.recall.IsZero():
		return "已撤回：recalled_at 非空，行还在但三道出口都不计数"
	case !n.read.IsZero():
		return "已读：read_at 非空，不计数"
	case n.user != uDad:
		return "同家他人（" + n.user + "）：family 维度 COUNT 会误把它算进来"
	default:
		return "未读：计入唯一来源"
	}
}

// =====================================================================
// W52 d23：端到端链路 —— 记一笔账之后发生什么
//
// 一笔账落库只是开头：finance 写行 → 发一条事件 → 三个订阅者（动态条目 / 超支通知 / 向到期中心注册
// 下期提醒）→ 首页 home/summary 四区跟着变。链路里任何一跳静默少做，用户看到的就是「账记了，别的什么都没动」。
// 这一天把每一跳的行数由程序自己数出来逐跳对账，再把同一条事件重放 1/2/3 次验证不双计
// （幂等键 (source_system, source_id, kind)），并把「挂掉一跳」的补偿跑通。
//
// 内存里真跑：三张表（finance_transaction / homeos_activity / homeos_notification）+ 到期中心注册表、事件总线与
// 三个订阅者、逐跳 Δ 对账、重放、断跳补偿、summary 四区（errgroup 并行取、按区名定序打印 → 字节确定）。
// DryRun 真实 SQL：第 8 节三张表 DDL + 写账 INSERT + 两条幂等查重 SELECT + 未读 COUNT + 动态 SELECT + 月桶 GROUP BY，
// 由 GORM DryRun 生成（DisableAutomaticPing + 固定 NowFunc），是 Postgres 原文、本机不连库只打印。
// 真环境要复跑：① (source_system,source_id,kind) 唯一索引建起来后，第 5 节的重放由数据库报 23505 而不是内存判；
// ② 第 6 节 outbox 换成真表 + 退避重试，验未 ack 那条最终追平；③ 第 4 节四区换真 RPC 注入超时，验 degraded 而整页不 500。
