// 月预算只有 fam-A 这一行；fam-B 的预算行故意留在库里不读（第 3 节用它证「未设该周期预算」不折算）
var budgetCents = map[string]int64{fam + sep + period: 450000, famB + sep + period: 3000000}
var owner = map[string]string{fam: uDad, famB: "u-other"}

// ---------- 三张表 + 事件 ----------
type Txn struct {
	ID, AmountCents                     int64
	FamilyID, MemberID, MemberName      string
	Category, Currency, ClientRequestID string
	OccurredAt                          time.Time
	DeletedAt                           gorm.DeletedAt
}
type Act struct {
	ID, AmountCents                    int64
	FamilyID, Kind                     string
	SourceSystem, SourceID, MemberName string
	CreatedAt                          time.Time
	DeletedAt                          gorm.DeletedAt
}
type Note struct {
	ID, AmountCents                                int64
	FamilyID, RecipientUserID, Kind                string
	SourceSystem, SourceID, ClientRequestID, Title string
	CreatedAt                                      time.Time
	ReadAt                                         *time.Time
	DeletedAt                                      gorm.DeletedAt
}
type Ev struct {
	Topic, FamilyID, SourceSystem, SourceID, Kind             string
	MemberID, MemberName, Category, Currency, ClientRequestID string
	AmountCents                                               int64
	OccurredAt                                                time.Time
	acked                                                     bool
}

func (Txn) TableName() string  { return txnTab }
func (Act) TableName() string  { return actTab }
func (Note) TableName() string { return noteTab }
func (e Ev) Dedup() string     { return e.SourceSystem + sep + e.SourceID + sep + e.Kind }
func (n Note) Dedup() string   { return n.SourceSystem + sep + n.SourceID + sep + n.Kind }

var (
	txns                    []Txn
	acts                    []Act
	notes                   []Note
	outbox                  []Ev
	byAct                   = map[string]Act{}
	byNote                  = map[string]Note{}
	byReq                   = map[string]Txn{}
	dues                    = map[string]string{}
	broken                  = map[string]bool{}
	lastBad                 []string
	txnSeq, actSeq, noteSeq int64
	failHop                 int
	dupAct                  int
	dupNote                 int
	dupDue                  int
	reused                  int
	rejected                int
)

func nid(p *int64) int64      { *p++; return *p }
func hdr(s string)            { fmt.Printf("\n===== %s =====\n", s) }
func at(t time.Time) string   { return t.Format("2006-01-02 15:04:05") }
func money(c int64) string    { return fmt.Sprintf("%d.%02d", c/100, c%100) }
func or(s, alt string) string { return map[bool]string{true: alt, false: s}[s == ""] }
func pad(s string, n int) string {
	return s + strings.Repeat(" ", max(0, n-(len(s)+len([]rune(s)))/2))
}
func cut(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:max(0, n-1)]) + "…"
}
func keys(m map[string]string) (out []string) {
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return
}
func parseNum(s string) int    { n := 0; fmt.Sscanf(s, "%d", &n); return n }
func alertKey(f string) string { return "finance" + sep + f + sep + period + sep + kAlert }

// 未读口径全项目只有一个函数（判据③）：角标 / 列表页 / summary 通知区三个出口都调它。
func isUnread(n Note) bool { return n.ReadAt == nil && !n.DeletedAt.Valid }
func unread(f, u string) int {
	n := 0
	for _, x := range notes {
		if x.FamilyID == f && x.RecipientUserID == u && isUnread(x) {
			n++
		}
	}
	return n
}

// spent：月桶支出永远从账本现算，不从事件累加 —— 这是「重放不双计」的根，不是事后打的补丁。
func spent(f string) int64 {
	var s int64
	for _, t := range txns {
		if t.FamilyID == f && t.OccurredAt.Format("2006-01") == period && !t.DeletedAt.Valid {
			s += t.AmountCents
		}
	}
	return s
}
func cntTxn(f string) int {
	n := 0
	for _, t := range txns {
		if t.FamilyID == f && t.OccurredAt.Format("2006-01") == period {
			n++
		}
	}
	return n
}

// ---------- 三个订阅者：动态流 / 超支通知 / 下期提醒注册 ----------
func projectFeed(e Ev) error {
	if _, ok := byAct[e.Dedup()]; ok {
		dupAct++
		return nil
	}
	r := Act{ID: nid(&actSeq), FamilyID: e.FamilyID, Kind: e.Kind, SourceSystem: e.SourceSystem, SourceID: e.SourceID, MemberName: e.MemberName, AmountCents: e.AmountCents, CreatedAt: e.OccurredAt}
	acts = append(acts, r)
	byAct[e.Dedup()] = r
	return nil
}

// 预算是「周期」级的，所以通知的 source_id 是 fam-A|2026-10 而不是某一笔账：
// 同周期内再超支三次也只有第一条 budget_alert —— 幂等键把这件事变成库级保证。
func projectAlert(e Ev) error {
	if e.Kind != kCreated {
		return nil
	}
	b, s := budgetCents[e.FamilyID+sep+period], spent(e.FamilyID)
	if b == 0 || s <= b {
		return nil // 未设该周期预算 → 整条不产（不是产了再藏）；没超支同样不产
	}
	if _, ok := byNote[alertKey(e.FamilyID)]; ok {
		dupNote++
		return nil
	}
	n := Note{ID: nid(&noteSeq), FamilyID: e.FamilyID, RecipientUserID: owner[e.FamilyID], Kind: kAlert, SourceSystem: "finance",
		SourceID: e.FamilyID + sep + period, ClientRequestID: "alert-" + e.FamilyID + "-" + period, Title: "本月支出已超预算", AmountCents: s, CreatedAt: e.OccurredAt}
	notes = append(notes, n)
	byNote[n.Dedup()] = n
	return nil
}

// 业务面不许自起计时器：周期性类目只向到期中心注册 {code}.due.registered，到点由中心发提醒。
var dueCode = map[string]string{kRent: "rent", "学习班": "tuition"}

func projectDue(e Ev) error {
	code, ok := dueCode[e.Category]
	if !ok {
		return nil
	}
	key := "finance" + sep + e.SourceID + sep + "recurring_reminder"
	if _, ok := dues[key]; ok {
		dupDue++
		return nil
	}
	dues[key] = code + ".due." + nextPer + "（next_at=2026-11-01 09:00）"
	return nil
}

var subs = []struct {
	tag, name string
	fn        func(Ev) error
}{{"feed", "feedProjector→" + actTab, projectFeed}, {"alert", "alertProjector→" + noteTab, projectAlert}, {"due", "dueProjector→到期中心", projectDue}}

// deliver：按声明序逐个投（顺序固定 → 字节确定）；订阅者侧故障就返回错误，绝不静默吞掉。
func deliver(e Ev) []string {
	var bad []string
	for _, s := range subs {
		if broken[s.tag] {
			failHop++
			bad = append(bad, s.name+"：写库口不可用（订阅者侧故障，不是业务面的错）")
			continue
		}
		if err := s.fn(e); err != nil {
			bad = append(bad, s.name+"："+err.Error())
		}
	}
	return bad
}

// publish：先留痕再投；任一订阅者失败就不 ack —— 第 6 节的补偿全靠这条留痕。
func publish(e Ev) []string {
	i := len(outbox)
	outbox = append(outbox, e)
	bad := deliver(e)
	if len(bad) == 0 {
		outbox[i].acked = true
	}
	lastBad = bad
	return bad
}

func unacked() int {
	n := 0
	for _, e := range outbox {
		if !e.acked {
			n++
		}
	}
	return n
}

// retryPending：将未 ack 的事件按登记序重投；能不能重跑取决于订阅者的幂等键。
func retryPending() (int, []string) {
	n := 0
	var still []string
	for i := range outbox {
		if outbox[i].acked {
			continue
		}
		if bad := deliver(outbox[i]); len(bad) > 0 {
			still = append(still, outbox[i].SourceID+" 仍失败 "+fmt.Sprint(len(bad))+" 跳")
			continue
		}
		outbox[i].acked = true
		n++
	}
	return n, still
}

type txnIn struct {
	SessionFam, ReqFam, MemberID, MemberName, Category, Currency string
	Cents                                                        int64
	CRID                                                         string
}

// writeTxn＝写账接口：family_id 只从会话取；入口幂等键 (family_id, client_request_id) 命中就回首次那条且不再发事件。
func writeTxn(in txnIn) (Txn, string, bool) {
	if in.SessionFam == "" {
		rejected++
		return Txn{}, "401", false
	}
	f := in.SessionFam
	if in.ReqFam != "" && in.ReqFam != f {
		rejected++
		return Txn{}, "404", false // 不是 403：403 等于替调用方确认「fam-B 这个家庭确实存在」
	}
	if in.Cents <= 0 || in.Currency == "" || len(in.CRID) < 8 {
		rejected++
		return Txn{}, "400", false
	}
	if r, ok := byReq[f+sep+in.CRID]; ok {
		reused++
		return r, "200", true
	}
	t := Txn{ID: nid(&txnSeq), FamilyID: f, MemberID: in.MemberID, MemberName: in.MemberName, Category: in.Category, Currency: in.Currency, AmountCents: in.Cents, ClientRequestID: in.CRID, OccurredAt: fixedNow}
	txns = append(txns, t)
	byReq[f+sep+in.CRID] = t
	publish(eventOf(t)) // 账已落库；订阅者失败由 outbox 补偿，绝不回滚账（否则用户以为没记上）
	return t, "201", false
}

func eventOf(t Txn) Ev {
	return Ev{Topic: "finance.transaction.created", FamilyID: t.FamilyID, SourceSystem: "finance", SourceID: fmt.Sprintf("txn-%d", t.ID), Kind: kCreated,
		MemberID: t.MemberID, MemberName: t.MemberName, Category: t.Category, Currency: t.Currency, ClientRequestID: t.ClientRequestID, AmountCents: t.AmountCents, OccurredAt: t.OccurredAt}
}

// ---------- 逐跳对账 ----------
type Ctr struct{ Txn, Ev, Act, Note, Due, Unread int }

func (c Ctr) v() [6]int { return [6]int{c.Txn, c.Ev, c.Act, c.Note, c.Due, c.Unread} }
func snap() Ctr {
	return Ctr{len(txns), len(outbox), len(acts), len(notes), len(dues), unread(fam, uDad)}
}

var hopName = [6]string{"1 写账", "2 事件", "3 动态", "4 通知", "5 待办", "6 未读"}
var hopTab = [6]string{txnTab + "（记账接口）", "bus 发布条数（含重放）", actTab + "（订阅者写）",
	noteTab + "（订阅者写）", "到期中心注册数", "unread() 唯一口径"}

// trip：一次链路的六跳行数全部现场数出来，与期望 Δ 并排；对不上就点名哪一跳。
func trip(label string, a, want Ctr) {
	b := snap()
	av, bv, wv := a.v(), b.v(), want.v()
	fmt.Println("  ─ " + label)
	fmt.Println("  " + pad("跳", 10) + pad("写进哪张表 / 口径", 36) + pad("起点", 6) + pad("终点", 6) + pad("Δ", 5) + pad("期望", 6) + "判定")
	miss := 0
	for i := range hopName {
		ok := bv[i]-av[i] == wv[i]
		miss += yes[!ok]
		fmt.Println("  " + pad(hopName[i], 10) + pad(hopTab[i], 36) + pad(fmt.Sprint(av[i]), 6) + pad(fmt.Sprint(bv[i]), 6) + pad(fmt.Sprint(bv[i]-av[i]), 5) + pad(fmt.Sprint(wv[i]), 6) + mark[ok])
	}
	fmt.Printf("  订阅者返回：%s\n  对账结论：%d/%d 跳与期望一致；%s\n", map[bool]string{true: "3/3 全部成功", false: strings.Join(lastBad, " | ")}[len(lastBad) == 0], 6-miss, 6,
		map[bool]string{true: "链路通", false: "有跳对不上 → 这条事件不能 ack，等 outbox 追"}[miss == 0])
}

// ---------- home/summary：一个业务请求带出四区 ----------
type sec struct {
	Name, Val string
	Degraded  bool
}

func homeSummary(f, u, fail string) []sec {
	names := []string{"账目摘要", "待办提醒", "通知未读", "最近动态"}
	fns := []func() (string, error){
		func() (string, error) { return money(spent(f)) + " 元 / " + fmt.Sprint(cntTxn(f)) + " 笔", nil },
		func() (string, error) { return fmt.Sprint(len(dues)) + " 条（中心注册）", nil },
		func() (string, error) { return fmt.Sprint(unread(f, u)) + " 条未读", nil },
		func() (string, error) {
			if len(acts) == 0 {
				return "暂无动态", nil
			}
			x := acts[len(acts)-1]
			return cut(x.MemberName+" "+money(x.AmountCents)+" 元", 16), nil
		},
	}
	out := make([]sec, len(names))
	var g errgroup.Group
	for i := range fns {
		i := i
		g.Go(func() error {
			if names[i] == fail {
				out[i] = sec{Name: names[i], Val: "—", Degraded: true}
				return errors.New("下游 RPC timeout")
			}
			v, err := fns[i]()
			out[i] = sec{Name: names[i], Val: v, Degraded: err != nil}
			return nil // 单区取不到只标 degraded：整页必须 200
		})
	}
	_ = g.Wait()
	return out
}
func deg(ss []sec) int {
	n := 0
	for _, s := range ss {
		n += yes[s.Degraded]
	}
	return n
}

