// ---------- 面目录：切片顺序＝声明序（清单排序的唯一依据，不是 map 序、不是字典序）----------
type Face struct {
	Code, Name, Dep string
	MinRole         int
	Born            bool
}

var registry = []Face{{"ledger", "账本", "finance", 1, true}, {"budget", "预算", "finance", 1, true},
	{"calendar", "日程", "calendar", 1, true}, {"feed", "动态", "homeos", 1, true},
	{"lab", "实验室", "homeos", 1, true}, {"insights", "洞察报表", "finance", 2, true}, {"iot", "设备", "homeos", 1, false}}

// 家庭级开关（d10：按 family 灰度，不是全局布尔）
var enabled = map[string]bool{fam + "|ledger": true, fam + "|budget": true, fam + "|calendar": true,
	fam + "|feed": true, fam + "|insights": true, fam + "|lab": false, fam + "|iot": true}

type Entry struct {
	Code, Name  string
	Available   bool
	Reason      string // available=false 时给客户端出引导文案的键（标灰而不是抹掉）
	MinRoleName string
}
type Composed struct {
	List                     []Entry
	BornCut, RoleCut, Greyed []string
}

// compose＝全项目唯一的面清单产出函数（四处合成）；客户端只许渲染它的返回。
func compose(famKey, role string) Composed {
	var c Composed
	for _, f := range registry {
		switch {
		case !f.Born:
			c.BornCut = append(c.BornCut, f.Code)
		case rank[role] < f.MinRole:
			c.RoleCut = append(c.RoleCut, fmt.Sprintf("%s(需 %s)", f.Code, rName(f.MinRole)))
		default:
			e := Entry{Code: f.Code, Name: f.Name, Available: enabled[famKey+sep+f.Code], MinRoleName: rName(f.MinRole)}
			if !e.Available {
				e.Reason = "family_disabled"
				c.Greyed = append(c.Greyed, f.Code)
			}
			c.List = append(c.List, e)
		}
	}
	return c
}
func rName(r int) string {
	for k, v := range rank {
		if v == r && k != "" {
			return k
		}
	}
	return "?"
}
func dirCodes(fs []Face) []string {
	var o []string
	for _, f := range fs {
		o = append(o, f.Code)
	}
	return o
}
func without(fs []Face, cut []string) []Face {
	var o []Face
	for _, f := range fs {
		if !inList(cut, f.Code) {
			o = append(o, f)
		}
	}
	return o
}

// 第 3 层（家庭已启用）单独产出一次：这一层不抹掉，只标 available=false + reason。
func enabledLayer(born []Face, famKey string) []Entry {
	var o []Entry
	for _, f := range born {
		e := Entry{Code: f.Code, Name: f.Name, Available: enabled[famKey+sep+f.Code]}
		if !e.Available {
			e.Reason = "family_disabled"
		}
		o = append(o, e)
	}
	return o
}
func codesOf(ls []Entry) string {
	var o []string
	for _, e := range ls {
		o = append(o, e.Code+map[bool]string{true: "", false: "(灰)"}[e.Available])
	}
	return strings.Join(o, " ")
}
func elCodes(ls []Entry) []string {
	var o []string
	for _, e := range ls {
		o = append(o, e.Code)
	}
	return o
}
func availCodes(ls []Entry) []string {
	var o []string
	for _, e := range ls {
		if e.Available {
			o = append(o, e.Code)
		}
	}
	return o
}
func lostCodes(a, b []Entry) []string {
	var o []string
	for _, e := range a {
		if !inList(elCodes(b), e.Code) {
			o = append(o, e.Code)
		}
	}
	return o
}
func guideCount(a []Entry, lost []string) int {
	n := 0
	for _, e := range a {
		if inList(lost, e.Code) && e.Reason != "" {
			n++
		}
	}
	return n
}
func firstDiff(a, b []Entry) int {
	for i := range a {
		if i >= len(b) || a[i].Code != b[i].Code {
			return i + 1
		}
	}
	return 0
}
func inList(xs []string, s string) bool {
	for _, x := range xs {
		if x == s {
			return true
		}
	}
	return false
}

