func alive(n Note) bool    { return !n.Deleted && n.RecalledAt == nil }
func isUnread(n Note) bool { return n.ReadAt == nil && alive(n) }

// 唯一口径：全项目只有这一个函数产出未读数，三个出口都调它（判据③的正面）。
func unread(f, u string) int {
	n := 0
	for _, x := range notes {
		if x.FamilyID == f && x.Recipient == u && isUnread(x) {
			n++
		}
	}
	return n
}
func exitBadge() int    { return unread(fam, uDad) }
func exitListPage() int { return unread(fam, uDad) }
func exitMarkRead(id int64) int {
	for i := range notes {
		if notes[i].ID == id {
			t := fixedNow
			notes[i].ReadAt = &t
		}
	}
	return unread(fam, uDad) // 正例：标完重新数一次，而不是把旧值减 1
}

// ❌ 三种「另起炉灶」的未读算法（判据③的反例，各自的数现场算）
