func localMinus1(cached int) int { return cached - 1 } // ❌ 已读接口返回「前端本地减 1」
func sameKey(sys, sid, kind string) int {
	n := 0
	for _, x := range notes {
		if x.SourceSystem == sys && x.SourceID == sid && x.Kind == kind {
			n++
		}
