	sess, famArg, code, shape string
}

var denied = map[string]int{"401": 0, "403": 0, "404": 0, "400": 0}
var hitOtherFam, wroteCents = 0, 0

func guardCases() []req {
	return []req{{uDad, fam, "ledger", ""}, {"", fam, "ledger", ""}, {uMom, "fam-B", "ledger", ""},
		{uMom, fam, "insights", ""}, {uDad, fam, "budget", "amount=128.00"}, {uDad, fam, "budget", "amount_cents=12800"}}
}
func orDash(s string) string {
	if s == "" {
		return "（无会话）"
	}
	return s
}

func route(r req) (string, string) {
	if r.sess == "" {
		denied["401"]++
		return "401", "未登录：会话里没有 user_id"
	}
	if r.famArg != fam {
		hitOtherFam++
		denied["404"]++
		return "404", "family_id 与会话不一致 → 404（用 403 就等于承认这个家庭存在）"
	}
	if r.code == "insights" && rank[roleOf(r.sess)] < 2 {
		denied["403"]++
		return "403", "本家庭但角色不足：" + r.code + " 需 editor，会话角色 " + roleOf(r.sess)
	}
	if r.shape != "" && !strings.Contains(r.shape, "_cents") {
		denied["400"]++
		return "400", "金额字段必须是整数 *_cents，收到 " + r.shape + " → 400 并回合法形状 amount_cents=整数（不回落默认 0）"
	}
	if r.shape != "" {
		wroteCents++
	}
	return "200", "命中会话家庭 " + fam + "；查询里带 family_id=" + fam
}
func roleOf(sess string) string {
	if sess == uDad {
		return "editor"
	}
	return "viewer"
}

// 每条查询都带 family_id：这里数的是「本次跑过的取数里，几条带上了会话家庭」。
var queryLog []string

func runQuery(name, f string) {
	queryLog = append(queryLog, name+"|family_id="+f)
}
func qWithFam() int {
	n := 0
	for _, q := range queryLog {
		if strings.Contains(q, "family_id="+fam) {
			n++
		}
	}
	return n
}

func clientFetchCodes(cs []string) {
	for _, c := range cs {
		reqLog = append(reqLog, "GET /"+c+"/data")
		runQuery("GET /"+c+"/data", fam)
	}
}
func render(ls []Entry) string { return codesOf(ls) } // 正例：只渲染，不改内容、不改顺序

// ❌ 客户端 .filter(e => e.available)：判据⑥的破坏面从这里量
func clientTrim(ls []Entry) []Entry {
	clientFilterCalls++
	var o []Entry
	for _, e := range ls {
		if e.Available {
			o = append(o, e)
		}
	}
	return o
}

