type Ev struct {
	SourceSystem, SourceID, Kind, FamilyID, MemberName string
	Cents                                              int64
}

func (e Ev) Dedup() string { return e.SourceSystem + sep + e.SourceID + sep + e.Kind }

func writeActivity(caller string, e Ev) error {
	mu.Lock()
	defer mu.Unlock()
	writes++
	if !strings.HasPrefix(caller, "subscriber:") {
		writeBlocked++
		return fmt.Errorf("写入口拒绝：caller=%s 不是订阅者（%s 只由事件写入）", caller, actTab)
	}
	if _, ok := actSeen[e.Dedup()]; ok {
		return nil
	}
	acts = append(acts, Act{ID: int64(len(acts) + 1), FamilyID: e.FamilyID, Kind: e.Kind,
		SourceSystem: e.SourceSystem, SourceID: e.SourceID, MemberName: e.MemberName, AmountCents: e.Cents})
	actSeen[e.Dedup()] = 1
	return nil
}

func writeNote(caller string, n Note) string {
	mu.Lock()
	defer mu.Unlock()
	if !strings.HasPrefix(caller, "subscriber:") {
		return "被写入口拒绝"
	}
	key := n.SourceSystem + sep + n.SourceID + sep + n.Kind
	if _, ok := noteSeen[key]; ok {
		return "命中已有行（幂等键）"
	}
	n.ID = int64(len(notes) + 1)
	notes = append(notes, n)
	noteSeen[key] = 1
	return "新落 1 行"
}

// deliver20：20 个投递者投同一条 budget_alert（同幂等键）。
// 哪个 goroutine 抢先是不确定的 → 只按「结局」聚合计数、再按结局文本排序打印，字节才确定。
func deliver20() []string {
	var wg sync.WaitGroup
	ch := make(chan string, 20)
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			ch <- writeNote("subscriber:alertProjector", Note{FamilyID: fam, Recipient: uDad, Kind: "budget_alert",
				SourceSystem: "finance", SourceID: fam + sep + period, Title: "本月支出已超预算", AmountCents: 478600})
		}()
	}
	wg.Wait()
	close(ch)
	tally := map[string]int{}
	for s := range ch {
		tally[s]++
	}
	var out []string
	for k, v := range tally {
		out = append(out, fmt.Sprintf("结局=%-24s 次数=%d", k, v))
	}
	sort.Strings(out)
	return out
}

// ---------- summary：一个业务请求带四区 ----------
var httpCalls, rpcCalls int
var secCost = map[string]int{"账目摘要": 6, "待办提醒": 2, "通知未读": 1, "最近动态": 3}
var ledgerCents = map[string]int64{fam + sep + period: 478600}
var dues = []string{"rent.due.2026-10", "tuition.due.2026-11"}

type sec struct {
	Name, Val string
	Degraded  bool
}

func homeSummary(fail string) []sec {
	httpCalls++
	names := []string{"账目摘要", "待办提醒", "通知未读", "最近动态"}
	fns := []func() (string, error){
		func() (string, error) { return money(ledgerCents[fam+sep+period]) + " 元（本月支出）", nil },
		func() (string, error) { return fmt.Sprint(len(dues)) + " 条到期提醒", nil },
		func() (string, error) { return fmt.Sprint(unread(fam, uDad)) + " 条未读", nil },
		func() (string, error) {
			if len(acts) == 0 {
				return "暂无动态", nil
			}
			x := acts[len(acts)-1]
			return cut(x.MemberName+" "+money(x.AmountCents)+" 元", 16), nil
		},
	}
	out := make([]sec, len(names))
	var g errgroup.Group
	for i := range fns {
		i := i
		g.Go(func() error {
			rpcCalls++
			if names[i] == fail {
				out[i] = sec{Name: names[i], Val: "—", Degraded: true}
				return fmt.Errorf("timeout")
			}
			v, err := fns[i]()
			out[i] = sec{Name: names[i], Val: v, Degraded: err != nil}
			return nil
		})
	}
	_ = g.Wait()
	return out
}
func deg(ss []sec) int {
	n := 0
	for _, s := range ss {
		n += yes[s.Degraded]
	}
	return n
}
func restOf(ss []sec, name string) (o []string) {
	for _, s := range ss {
		if s.Name != name {
			o = append(o, s.Name+"="+s.Val)
		}
	}
	return
}
func maxOf(m map[string]int) int {
	v := 0
	for _, x := range m {
		if x > v {
			v = x
		}
	}
	return v
}
func costText() string {
	var o []string
	for _, k := range []string{"账目摘要", "待办提醒", "通知未读", "最近动态"} {
		o = append(o, fmt.Sprintf("%s=%dms", k, secCost[k]))
	}
	return strings.Join(o, " ")
}

