type NoteRow struct {
	ID, AmountCents                 int64
	FamilyID, RecipientUserID, Kind string
	SourceSystem, SourceID, Title   string
	ReadAt, RecalledAt              *time.Time
	DeletedAt                       gorm.DeletedAt
}
type ActRow struct {
	ID, AmountCents                    int64
	FamilyID, Kind                     string
	SourceSystem, SourceID, MemberName string
	CreatedAt                          time.Time
	DeletedAt                          gorm.DeletedAt
}

func (NoteRow) TableName() string { return noteTab }
func (ActRow) TableName() string  { return actTab }

func dryDB() *gorm.DB {
	db, e := gorm.Open(postgres.New(postgres.Config{DSN: "postgres://svc_homeos:dev@localhost:5432/homecube?sslmode=disable"}), &gorm.Config{
		DryRun: true, DisableAutomaticPing: true, NowFunc: func() time.Time { return fixedNow }, Logger: gormlogger.Default.LogMode(gormlogger.Silent)})
	if e != nil {
		panic(e)
	}
	return db
}

func pad(s string, n int) string {
	return s + strings.Repeat(" ", max(0, n-(len(s)+len([]rune(s)))/2))
}
func cut(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:max(0, n-1)]) + "…"
}
func hdr(s string)         { fmt.Printf("\n===== %s =====\n", s) }
func money(c int64) string { return fmt.Sprintf("%d.%02d", c/100, c%100) }

// errTextOf：nil 与 error 两条分支必须惰性求值，早期写成 map 字面量取值 → err==nil 时 e.Error() 直接 panic。
func errTextOf(e error) string {
	if e == nil {
		return "（写入口接受）"
	}
	return e.Error()
}

// elStrip 把请求日志里的 "GET /x/data" 折成裸 code，好跟违规面名单对照。
func elStrip(rs []string) (o []string) {
	for _, r := range rs {
		o = append(o, strings.TrimSuffix(strings.TrimPrefix(r, "GET /"), "/data"))
	}
	return
}

// reasonText：该出引导（而不是出请求）的那些面，各自挂的 reason 键。
func reasonText(c Composed) string {
	var o []string
	for _, e := range c.List {
		if !e.Available {
			o = append(o, e.Code+"→"+e.Reason)
		}
	}
	for _, b := range c.BornCut {
		o = append(o, b+"→face_not_born（整条不进清单）")
	}
	return strings.Join(o, " · ")
}

